import { Book } from "@/lib/types";

export const exodus: Book = {
  id: "exodus",
  name: "2. Mose",
  shortName: "2.Mose",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Und dies sind die Namen der Söhne Israel, die nach Ägypten kamen — mit Jakob kamen sie, jeder mit seinem Haus*:", heading: "Vermehrung und Knechtschaft der Söhne Israel in Ägypten", footnotes: ["d. i. die Familie\n℘ 1Mo 46,8-25"] },
      { number: 2, text: "Ruben, Simeon, Levi und Juda;" },
      { number: 3, text: "Issaschar, Sebulon und Benjamin;" },
      { number: 4, text: "Dan und Naftali, Gad und Asser*.", footnotes: ["℘ 1Mo 35,22-26"] },
      { number: 5, text: "Und die Zahl aller Seelen, die aus Jakobs Schoß hervorgegangen waren*, betrug siebzig* Seelen*. Josef aber war schon in Ägypten*.", footnotes: ["d. h. die von Jakob abstammten", "LXX liest: fünfundsiebzig", "℘ 1Mo 46,26.27", "℘ 1Mo 50,22"] },
      { number: 6, text: "Und Josef starb* und alle seine Brüder und jene ganze Generation*.", footnotes: ["℘ 1Mo 50,26", "℘ Ri 2,10; Pred 1,4; Apg 7,15"] },
      { number: 7, text: "Die Söhne Israel aber waren fruchtbar und wimmelten und mehrten sich und wurden sehr, sehr stark*, und das Land wurde voll von ihnen*.", footnotes: ["o. zahlreich", "℘ 1Mo 46,3; 5Mo 26,5; Neh 9,23; Ps 107,38; Apg 7,17"] },
      { number: 8, text: "Da trat ein neuer König die Herrschaft über Ägypten an, der Josef nicht mehr kannte*.", footnotes: ["℘ Ri 2,10; Apg 7,18"] },
      { number: 9, text: "Der sagte zu seinem Volk: Siehe, das Volk der Söhne Israel ist zahlreicher und stärker als wir*.", footnotes: ["℘ Ps 105,24"] },
      { number: 10, text: "Auf, lasst uns klug gegen es vorgehen*, damit es sich nicht noch weiter vermehrt! Sonst könnte es geschehen, wenn Krieg ausbricht, dass es sich auch noch zu unseren Feinden schlägt und gegen uns kämpft und dann aus dem Land hinaufzieht*.", footnotes: ["℘ Ps 83,3; 105,25", "o. sich des Landes bemächtigt\n℘ 1Sam 29,4"] },
      { number: 11, text: "Daher setzten sie Arbeitsaufseher* über es, um es mit ihren Lastarbeiten zu drücken*. Und es baute für den Pharao Vorratsstädte: Pitom und Ramses*.", footnotes: ["w. Oberste der Zwangsarbeit", "℘ Kap. 3,7; 5,8.9; 1Mo 15,13; 5Mo 26,6", "℘ 1Mo 47,11"] },
      { number: 12, text: "Aber je mehr sie es bedrückten, desto mehr nahm es zu; und so breitete es sich aus*, so dass sie ein Grauen erfasste vor den Söhnen Israel*.", footnotes: ["℘ 1Mo 46,3; 5Mo 26,5; Neh 9,23; Ps 107,38; Apg 7,17", "℘ 4Mo 22,3"] },
      { number: 13, text: "Da zwangen die Ägypter die Söhne Israel mit Gewalt zur Arbeit*", footnotes: ["℘ Spr 28,15"] },
      { number: 14, text: "und machten ihnen das Leben bitter durch harte Arbeit* an Lehm und an Ziegeln und durch allerlei Arbeit auf dem Feld, mit* all ihrer Arbeit, zu der sie sie mit Gewalt zwangen.*", footnotes: ["℘ Kap. 2,23; 5,14; Apg 7,18.19", "o. neben, außer", "℘ 1Mo 15,13; 5Mo 4,20; Ps 129,1; Jes 10,24"] },
      { number: 15, text: "Und der König von Ägypten sprach zu den hebräischen Hebammen, von denen die eine Schifra und die andere Pua hieß," },
      { number: 16, text: "und sagte: Wenn ihr den Hebräerinnen bei der Geburt helft und bei der Entbindung* seht, dass es ein Sohn ist, dann tötet ihn, wenn es aber eine Tochter ist, dann mag sie am Leben bleiben*.", footnotes: ["w. an den Töpferscheiben o. bei den Steinen seht: wenn. — Gemeint sind vielleicht die Steine, auf denen die Gebärende kauert, oder die Geschlechtsteile der Kinder.", "℘ Ps 105,25"] },
      { number: 17, text: "Aber weil die Hebammen Gott fürchteten*, taten sie nicht, wie ihnen der König von Ägypten gesagt hatte, sondern ließen die Jungen am Leben*.", footnotes: ["℘ 1Mo 42,18", "℘ 1Sam 22,17; Spr 8,13; 16,6"] },
      { number: 18, text: "Da rief der König von Ägypten die Hebammen zu sich und sagte zu ihnen: Warum habt ihr das getan, dass ihr die Jungen am Leben gelassen habt?" },
      { number: 19, text: "Die Hebammen antworteten dem Pharao: Ja, die hebräischen Frauen sind nicht wie die ägyptischen, denn sie sind lebenskräftig; ehe die Hebamme zu ihnen kommt, haben sie schon geboren." },
      { number: 20, text: "Und Gott tat den Hebammen Gutes*, und das Volk vermehrte sich und wurde sehr stark*.", footnotes: ["℘ Pred 8,12", "o. zahlreich"] },
      { number: 21, text: "Und weil die Hebammen Gott fürchteten, geschah es, dass er ihnen Nachkommen schenkte*.", footnotes: ["w. Häuser machte\n℘ 2Sam 7,11; Ps 112,1-3"] },
      { number: 22, text: "Da gebot der Pharao seinem ganzen Volk: Jeden Sohn, der geboren wird*, sollt ihr in den Nil werfen*, jede Tochter aber sollt ihr am Leben lassen*!", footnotes: ["℘ Kap. 2,6", "℘ Apg 7,19", "℘ 1Mo 46,3; 5Mo 26,5; Neh 9,23; Ps 107,38; Apg 7,17"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "*Und ein Mann vom Haus* Levi* ging hin und nahm eine Tochter Levi zur Frau.", heading: "Moses Geburt, Bewahrung und Erziehung", footnotes: ["℘ V. 1-25: Apg 7,20-30", "d. h. hier: von den Nachkommen", "℘ Kap. 6,20; 4Mo 26,59"] },
      { number: 2, text: "Und die Frau wurde schwanger und gebar einen Sohn*. Als sie sah, dass er schön war, verbarg sie ihn drei Monate lang*.", footnotes: ["℘ Kap. 6,20; 4Mo 26,59", "℘ 2Kö 11,3; Hebr 11,23"] },
      { number: 3, text: "Und als sie ihn nicht länger verbergen konnte, nahm sie für ihn ein Kästchen aus Schilfrohr und verklebte es mit Asphalt und Pech, legte das Kind hinein und setzte es in das Schilf am Ufer des Nil." },
      { number: 4, text: "Seine Schwester* aber stellte sich in einiger Entfernung hin, um zu erfahren*, was mit ihm geschehen würde.", footnotes: ["℘ Kap. 15,20; 4Mo 20,1", "o. erkennen"] },
      { number: 5, text: "Und die Tochter des Pharao ging hinab, um am Nil zu baden, während ihre Dienerinnen am Ufer des Nil hin und her gingen. Und sie sah das Kästchen mitten im Schilf und sandte ihre Magd hin und ließ es holen." },
      { number: 6, text: "Und als sie es geöffnet hatte, sah sie das Kind, und siehe, ein weinender Junge lag darin. Da hatte sie Mitleid mit ihm und sagte: Das ist eins von den Kindern der Hebräer*.", footnotes: ["℘ Kap. 1,22"] },
      { number: 7, text: "Und seine Schwester sagte zur Tochter des Pharao: Soll ich hingehen und dir eine stillende Frau von den Hebräerinnen herbeirufen, damit sie das Kind für dich stillt?" },
      { number: 8, text: "Die Tochter des Pharao antwortete ihr: Geh hin! Da ging das Mädchen* hin und rief die Mutter des Kindes herbei.", footnotes: ["o. junge Frau; bezeichnet das Mädchen. Dasselbe Wort findet sich auch in 1Mo 24,43 und Jes 7,14."] },
      { number: 9, text: "Und die Tochter des Pharao sagte zu ihr: Nimm dieses Kind mit und stille es für mich, dann werde ich dir deinen Lohn geben! Da nahm die Frau das Kind und stillte es." },
      { number: 10, text: "Als aber das Kind groß geworden war, brachte sie es der Tochter des Pharao, und es wurde ihr zum Sohn. Und sie gab ihm den Namen Mose, indem sie sagte: Ich habe ihn ja aus dem Wasser gezogen." },
      { number: 11, text: "Und es geschah in jenen Tagen, als Mose groß geworden war, da ging er zu seinen Brüdern* hinaus* und sah bei ihren Lastarbeiten zu. Da sah er, wie ein ägyptischer Mann einen hebräischen Mann, einen von seinen Brüdern, schlug.", heading: "Moses Übereifer für sein Volk — Flucht und Heirat in Midian", footnotes: ["d. h. hier: zu seinen hebräischen Volksgenossen", "℘ Hebr 11,24"] },
      { number: 12, text: "Und er wandte sich hierhin und dorthin, und als er sah, dass niemand in der Nähe war, erschlug er den Ägypter und verscharrte ihn im Sand." },
      { number: 13, text: "Als er aber am Tag darauf wieder hinausging, siehe, da rauften sich zwei hebräische Männer, und er sagte zu dem Schuldigen: Warum schlägst du deinen Nächsten?" },
      { number: 14, text: "Der aber antwortete: Wer hat dich zum Aufseher* und Richter über uns gesetzt?* Gedenkst du etwa, mich umzubringen, wie du den Ägypter umgebracht hast? Da fürchtete sich Mose und sagte sich: Also ist die Sache doch bekannt geworden!", footnotes: ["w. Obersten", "℘ 1Mo 19,9; 37,8; 4Mo 16,13; Apg 7,35"] },
      { number: 15, text: "Und der Pharao hörte diese Sache und suchte, Mose umzubringen*. Mose aber floh vor dem Pharao und hielt sich im Land Midian auf*. Und er setzte sich an einen Brunnen.", footnotes: ["℘ Kap. 18,4", "℘ 1Kö 11,18; Hab 3,7; Apg 7,29"] },
      { number: 16, text: "Nun hatte der Priester von Midian sieben Töchter; die kamen, schöpften Wasser und füllten die Tränkrinnen, um die Herde ihres Vaters zu tränken*.", footnotes: ["℘ 1Mo 24,11; 29,9.10"] },
      { number: 17, text: "Aber die Hirten kamen und trieben sie weg. Da stand Mose auf, half ihnen und tränkte ihre Herde." },
      { number: 18, text: "Als sie nun zu ihrem Vater Reguël kamen, sagte er: Warum seid ihr heute so früh gekommen?" },
      { number: 19, text: "Sie antworteten: Ein ägyptischer Mann hat uns aus der Gewalt* der Hirten befreit, und er hat sogar eifrig für uns geschöpft und die Herde getränkt.", footnotes: ["w. Hand"] },
      { number: 20, text: "Da sagte er zu seinen Töchtern: Und wo ist er? Warum habt ihr denn den Mann draußen gelassen? Ladet ihn doch ein, damit er Brot mit uns isst!" },
      { number: 21, text: "Und Mose willigte ein, bei dem Mann zu bleiben. Und er gab Mose seine Tochter Zippora zur Frau*.", footnotes: ["℘ Kap. 3,1; 4,25; 18,2; 4Mo 10,29; 12,1"] },
      { number: 22, text: "Die gebar einen Sohn, und er gab ihm den Namen Gerschom*, indem er sagte: Ein Fremder bin ich in einem fremden Land geworden*.", footnotes: ["Gerschom klingt an das hebr. Wort ger, d. h. der Fremde, an.", "℘ Kap. 4,20; 18,3; Apg 7,6"] },
      { number: 23, text: "Und es geschah während jener vielen Tage, da starb der König von Ägypten. Und die Söhne Israel seufzten wegen ihrer Arbeit und schrien um Hilfe*. Und ihr Geschrei wegen der Arbeit stieg auf zu Gott*.", footnotes: ["℘ Kap. 1,14; Ri 4,3; 1Sam 12,8", "℘ 4Mo 20,16; 1Sam 9,16; Ps 102,2; Apg 7,34"] },
      { number: 24, text: "Da hörte Gott ihr Ächzen*, und Gott dachte an seinen Bund mit Abraham*, Isaak* und Jakob*.", footnotes: ["℘ 4Mo 20,16; 1Sam 9,16; Ps 102,2; Apg 7,34", "℘ 1Mo 15,18", "℘ 1Mo 26,3.24", "℘ Kap. 6,5; 1Mo 28,13.14; 35,11.12; 2Kö 13,23; Ps 105,8-11"] },
      { number: 25, text: "Und Gott sah nach den Söhnen Israel, und Gott kümmerte sich um sie*.", footnotes: ["o. und Gott erkannte sie. — LXX liest: wurde von ihnen erkannt\n℘ Kap. 3,7.8.16; 4,31; 18,8; 5Mo 26,7; Ps 10,14; 31,8"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Mose aber weidete die Herde* Jitros, seines Schwiegervaters, des Priesters von Midian*. Und er trieb die Herde über die Wüste hinaus und kam an den Berg Gottes, den Horeb*.", heading: "Moses Berufung und Auftrag", footnotes: ["℘ 1Sam 16,11.19; Am 1,1", "℘ Kap. 2,16.21; 4,18; 1Kö 19,19", "℘ Kap. 4,27; 18,5; 19,2; 4Mo 10,33; 5Mo 1,6; 1Kö 19,8"] },
      { number: 2, text: "Da erschien ihm der Engel des HERRN in einer Feuerflamme mitten aus dem Dornbusch*. Und er sah hin, und siehe, der Dornbusch brannte im Feuer, und der Dornbusch wurde nicht verzehrt.", footnotes: ["℘ 5Mo 33,16; Mk 12,26; Apg 7,30.31.35"] },
      { number: 3, text: "Und Mose sagte sich: Ich will doch hinzutreten* und diese große Erscheinung* sehen, warum der Dornbusch nicht verbrennt.", footnotes: ["w. vom Weg abbiegen", "o. Vision"] },
      { number: 4, text: "Als aber der HERR sah, dass er herzutrat, um zu sehen, da rief ihm Gott mitten aus dem Dornbusch zu* und sprach: Mose! Mose!* Er antwortete: Hier bin ich*.", footnotes: ["℘ Kap. 19,3; 3Mo 1,1", "℘ Kap. 33,12.17", "℘ 1Mo 22,1"] },
      { number: 5, text: "Und er sprach: Tritt nicht näher heran! Zieh deine Sandalen von deinen Füßen, denn die Stätte, auf der du stehst, ist heiliger Boden*!", footnotes: ["℘ 1Mo 28,17; Jos 5,15; Apg 7,33"] },
      { number: 6, text: "Dann sprach er: Ich bin der Gott deines Vaters, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs*. Da verhüllte Mose sein Gesicht, denn er fürchtete sich, Gott anzuschauen*.", footnotes: ["℘ V. 15; Kap. 4,5; 1Mo 28,13; 5Mo 6,3; 1Kö 18,36; Mt 22,32; Apg 3,13; 7,32", "℘ Kap. 33,20; Ri 13,22; 1Kö 19,13; Jes 6,2.5"] },
      { number: 7, text: "Der HERR aber sprach: Gesehen habe ich das Elend meines Volkes in Ägypten*, und sein Geschrei wegen seiner Antreiber habe ich gehört*; ja, ich kenne seine Schmerzen*.", footnotes: ["℘ Kap. 1,8-22; 2,25; Ps 9,14", "℘ 1Mo 31,12; 2Kö 20,5; Neh 9,9", "℘ Kap. 1,11.14; 2,23-25"] },
      { number: 8, text: "Und ich bin herabgekommen, um es aus der Gewalt* der Ägypter zu retten* und es aus diesem Land hinaufzuführen in ein gutes und geräumiges Land*, in ein Land, das von Milch und Honig* überfließt*, an den Ort der Kanaaniter, Hetiter, Amoriter, Perisiter, Hewiter und Jebusiter*.", footnotes: ["w. Hand", "℘ Ps 12,6", "℘ 5Mo 1,25; 8,7-10", "d. i. Trauben- und Dattelhonig. Bienenhonig war eine Seltenheit und wurde wohl nur als Zufallsfund konsumiert, vgl. Ri 14,8—9.", "℘ Kap. 13,5; 33,3; 3Mo 20,24; 4Mo 13,27; 5Mo 6,3; Jos 5,6; Jer 11,5; Hes 20,6.15", "℘ 1Mo 15,21"] },
      { number: 9, text: "Und nun siehe, das Geschrei der Söhne Israel ist vor mich gekommen*; und ich habe auch die Bedrängnis gesehen*, mit der die Ägypter sie quälen*.", footnotes: ["℘ Kap. 1,8-22; 2,25; Ps 9,14", "℘ Kap. 1,8-22; 2,25; Ps 9,14", "o. bedrängen"] },
      { number: 10, text: "Nun aber geh hin, denn ich will dich zum Pharao senden, damit du mein Volk, die Söhne Israel, aus Ägypten herausführst*!", footnotes: ["℘ Ri 6,14; Ps 105,26.37; Apg 7,34"] },
      { number: 11, text: "Mose aber antwortete Gott: Wer bin ich*, dass ich zum Pharao gehen und die Söhne Israel aus Ägypten herausführen sollte*?", footnotes: ["℘ 1Chr 29,14; 1Kor 3,5", "℘ Kap. 4,10.13; Ri 6,15"] },
      { number: 12, text: "Da sprach er: Ich werde ja mit dir sein*. Und dies sei dir das Zeichen*, dass ich dich gesandt habe: Wenn du das Volk aus Ägypten herausgeführt hast, werdet ihr an diesem Berg Gott dienen*.", footnotes: ["℘ 1Mo 26,3.24; Ri 6,16; 1Chr 9,20; Apg 18,10", "℘ 1Sam 14,10", "℘ Kap. 19,1-4; Apg 7,7"] },
      { number: 13, text: "Mose aber antwortete Gott: Siehe, wenn ich zu den Söhnen Israel komme und ihnen sage: Der Gott eurer Väter hat mich zu euch gesandt, und sie mich fragen: Was ist sein Name?, was soll ich dann zu ihnen sagen?*", footnotes: ["℘ Jes 52,6"] },
      { number: 14, text: "Da sprach Gott zu Mose: »Ich bin, der ich bin*.«* Dann sprach er: So sollst du zu den Söhnen Israel sagen: Der »Ich bin*« hat mich zu euch gesandt.", footnotes: ["o. Ich werde sein, der ich sein werde", "℘ Jes 42,8; Offb 1,4.8", "Das hebr. Wort für »sein« klingt an den Gottesnamen Jahwe an. Siehe Vorwort."] },
      { number: 15, text: "Und Gott sprach weiter zu Mose: So sollst du zu den Söhnen Israel sagen: Jahwe*, der Gott eurer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs*, hat mich zu euch gesandt. Das ist mein Name in Ewigkeit*, und das ist meine Benennung* von Generation zu Generation*.", footnotes: ["d. i. der Eigenname Gottes im Alten Testament, sonst mit HERR wiedergegeben. Siehe Vorwort.", "℘ 1Chr 29,18", "℘ Mal 3,6", "o. Anrufung; o. mein Gedenken; d. h. der Name, unter dem ich angerufen werde", "℘ Kap. 6,2.3; Ps 30,5; 68,5; 102,13; Hos 12,6"] },
      { number: 16, text: "Geh hin, versammle die Ältesten* Israels und sprich zu ihnen: Jahwe*, der Gott eurer Väter, ist mir erschienen*, der Gott Abrahams, Isaaks und Jakobs, und hat gesagt: Ich habe genau achtgehabt auf euch und auf das, was euch in Ägypten angetan worden ist*,", footnotes: ["℘ Kap. 4,29", "d. i. der Eigenname Gottes im Alten Testament, sonst mit HERR wiedergegeben. Siehe Vorwort.", "℘ Kap. 4,5", "℘ Kap. 1,8-22; 2,25"] },
      { number: 17, text: "und habe gesagt: Ich will euch aus dem Elend Ägyptens hinaufführen* in das Land der Kanaaniter, Hetiter, Amoriter, Perisiter, Hewiter und Jebusiter*, in ein Land, das von Milch und Honig* überfließt*.", footnotes: ["℘ Ps 102,21", "℘ Kap. 13,5; 33,3; 3Mo 20,24; 4Mo 13,27; 5Mo 6,3; Jos 5,6; Jer 11,5; Hes 20,6.15", "s. Anm. zu V. 8", "℘ Kap. 13,5; 33,3; 3Mo 20,24; 4Mo 13,27; 5Mo 6,3; Jos 5,6; Jer 11,5; Hes 20,6.15"] },
      { number: 18, text: "Und sie werden auf deine Stimme hören*. Und du sollst zum König von Ägypten hineingehen, du und die Ältesten Israels, und ihr sollt zu ihm sagen: Jahwe*, der Gott der Hebräer, ist uns begegnet. So lass uns nun drei Tagereisen weit in die Wüste ziehen*, damit wir Jahwe*, unserm Gott, opfern*!", footnotes: ["℘ Kap. 4,1.31", "s. Anm. zu V. 15", "℘ Kap. 8,23", "s. Anm. zu V. 15", "w. zum Opfer schlachten\n℘ Kap. 5,1-3"] },
      { number: 19, text: "Aber ich weiß wohl, dass der König von Ägypten euch nicht ziehen lassen wird*, auch nicht* durch eine starke Hand gezwungen.", footnotes: ["℘ Kap. 4,21; 5,2; 7,14.27; 8,28; 9,7.35; 10,20.27; 11,10; 13,15", "LXX und Vulg. üs.: es sei denn"] },
      { number: 20, text: "Deshalb werde ich meine Hand ausstrecken und Ägypten schlagen mit all meinen Wundern, die ich in seiner Mitte tun werde*. Danach erst wird er euch ziehen lassen*.", footnotes: ["℘ Kap. 7,3; 5Mo 6,22; Neh 9,10; Jer 32,20.21", "℘ Kap. 6,1; 11,1; 12,31"] },
      { number: 21, text: "Und ich werde diesem Volk Gunst geben in den Augen der Ägypter*, und es wird geschehen, wenn ihr auszieht, sollt ihr nicht mit leeren Händen ausziehen:", footnotes: ["℘ Kap. 11,3"] },
      { number: 22, text: "Jede Frau soll von ihrer Nachbarin und von ihrer Hausgenossin silberne Schmuckstücke* und goldene Schmuckstücke* und Kleidung* fordern. Die sollt ihr euren Söhnen und Töchtern anlegen und so die Ägypter ausplündern*!", footnotes: ["w. Gegenstände, o. Gefäße", "w. Gegenstände, o. Gefäße", "w. Obergewänder. — Das Obergewand bestand meistens aus einem großen viereckigen Stück Tuch, das man in verschiedener Weise umwarf.", "℘ Kap. 12,35.36; 1Mo 15,14"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Da antwortete Mose und sagte: Und wenn sie mir nicht glauben und nicht auf meine Stimme hören*, sondern sagen: Der HERR ist dir nicht erschienen?", heading: "Moses Beglaubigung durch Zeichen — Beistand durch Aaron", footnotes: ["℘ Kap. 3,18; 6,12"] },
      { number: 2, text: "Da sprach der HERR zu ihm: Was ist das da in deiner Hand*? Er sagte: Ein Stab.", footnotes: ["℘ 2Kö 4,2"] },
      { number: 3, text: "Und er sprach: Wirf ihn auf die Erde! Da warf er ihn auf die Erde, und er wurde zu einer Schlange*, und Mose floh vor ihr.", footnotes: ["℘ Kap. 7,9.10"] },
      { number: 4, text: "Der HERR aber sprach zu Mose: Strecke deine Hand aus und fasse sie beim Schwanz! Da streckte er seine Hand aus und ergriff sie, und sie wurde in seiner Hand zum Stab:" },
      { number: 5, text: "Damit sie glauben, dass dir der HERR erschienen ist*, der Gott ihrer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs*.", footnotes: ["℘ Kap. 3,16; Joh 4,48", "℘ Kap. 3,6"] },
      { number: 6, text: "Und der HERR sprach weiter zu ihm: Stecke doch deine Hand in deinen Gewandbausch*! Da steckte er seine Hand in seinen Gewandbausch. Und als er sie herauszog, siehe, da war seine Hand weiß von Aussatz*, wie Schnee*.", footnotes: ["d. i. die vom Gürtel gebildete bauschige Falte des Gewandes, in die man auch Gegenstände steckte", "o. vom Hautausschlag", "℘ 4Mo 12,10; 2Kö 5,27"] },
      { number: 7, text: "Und er sprach: Tu deine Hand wieder in deinen Gewandbausch! Da tat er seine Hand wieder in seinen Gewandbausch. Und als er sie aus seinem Gewandbausch herauszog, da war sie wieder wie sein übriges Fleisch." },
      { number: 8, text: "Und es wird geschehen, wenn sie dir nicht glauben und nicht auf die Stimme des ersten Zeichens hören, dann werden sie doch wegen der Stimme des zweiten Zeichens glauben*.", footnotes: ["w. auf die Stimme . . . hören, so werden sie der Stimme . . . glauben\n℘ Ri 6,17"] },
      { number: 9, text: "Und es wird geschehen, wenn sie selbst diesen beiden Zeichen nicht glauben* und nicht auf deine Stimme hören, dann nimm vom Wasser des Nil und gieße es auf das trockene Land*! Dann wird das Wasser, das du aus dem Nil nehmen wirst, auf dem trockenen Land zu Blut werden.", footnotes: ["℘ Joh 12,37", "℘ Kap. 7,19.20"] },
      { number: 10, text: "Mose aber antwortete dem HERRN: Ach, Herr! Ich bin kein redegewandter Mann*, weder seit gestern noch seit vorgestern, noch seitdem du zu deinem Knecht redest; denn unbeholfen ist mein Mund und unbeholfen meine Zunge*.", footnotes: ["w. kein Mann der Worte", "w. denn ich bin schweren Mundes und schwerer Zunge\n℘ Kap. 3,11; 6,12.30; Jer 1,6"] },
      { number: 11, text: "Da sprach der HERR zu ihm: Wer hat dem Menschen den Mund gemacht? Oder wer macht stumm oder taub, sehend oder blind? Nicht ich, der HERR?*", footnotes: ["℘ Ps 94,9; Spr 20,12"] },
      { number: 12, text: "Und nun geh hin! Ich will mit deinem Mund sein und dich unterweisen, was du reden sollst*.", footnotes: ["℘ 5Mo 18,18; Mt 10,19"] },
      { number: 13, text: "Er aber erwiderte: Ach, Herr! Sende doch, durch wen du senden willst!*", footnotes: ["℘ Jon 1,3"] },
      { number: 14, text: "Da entbrannte der Zorn des HERRN gegen Mose, und er sprach: Ist nicht dein Bruder Aaron da, der Levit? Ich weiß*, dass er reden kann. Und siehe, er geht auch schon aus, dir entgegen. Und wenn er dich sieht, wird er sich freuen in seinem Herzen.", footnotes: ["o. habe erkannt"] },
      { number: 15, text: "Dann sollst du zu ihm reden und die Worte in seinen Mund legen, und ich will mit deinem Mund und mit seinem Mund sein* und will euch unterweisen, was ihr tun sollt*.", footnotes: ["℘ 4Mo 23,5; 5Mo 18,18; Jes 51,16; Jer 1,9", "℘ Ps 25,12"] },
      { number: 16, text: "Er aber soll für dich zum Volk reden. Und es wird geschehen, er wird für dich zum Mund sein, und du wirst für ihn zum Gott sein*.", footnotes: ["℘ Kap. 7,1.2"] },
      { number: 17, text: "Und diesen Stab sollst du in deine Hand nehmen; damit sollst du die Zeichen tun." },
      { number: 18, text: "Darauf ging Mose hin und kehrte zu seinem Schwiegervater Jitro* zurück und sagte zu ihm: Ich möchte gern gehen und zu meinen Brüdern zurückkehren, die in Ägypten sind, um zu sehen, ob sie noch am Leben sind. Und Jitro sagte zu Mose: Geh hin in Frieden*!", heading: "Moses Rückkehr nach Ägypten", footnotes: ["℘ Kap. 3,1", "℘ Ri 18,6; 2Kö 5,10; Mk 5,34; Lk 7,50; Apg 16,36"] },
      { number: 19, text: "Und der HERR sprach zu Mose in Midian: Geh hin, kehre nach Ägypten zurück! Denn alle Männer sind gestorben, die dir nach dem Leben trachteten*.", footnotes: ["℘ Mt 2,20"] },
      { number: 20, text: "Da nahm Mose seine Frau und seine Söhne mit sich*, ließ sie auf dem Esel reiten und kehrte in das Land Ägypten zurück. Und Mose nahm den Stab Gottes in seine Hand*.", footnotes: ["℘ Kap. 2,22; 18,6", "℘ Kap. 17,9"] },
      { number: 21, text: "Und der HERR sprach zu Mose: Wenn du hinziehst, um nach Ägypten zurückzukehren, sieh zu, dass du all die Wunder*, die ich in deine Hand gelegt habe, vor dem Pharao tust! Und ich, ich will sein Herz verstocken*, so dass er das Volk nicht ziehen lassen wird*.", footnotes: ["o. Wahrzeichen", "℘ Kap. 7,3; 9,12; 10,20.27; 11,10; 14,4.8.17; 5Mo 2,30; Röm 9,18", "℘ Kap. 3,19; 8,15"] },
      { number: 22, text: "Und du sollst zum Pharao sagen: »So spricht der HERR: Mein erstgeborener Sohn* ist Israel —", footnotes: ["℘ 5Mo 32,6; Hos 11,1; Mal 1,6; Röm 9,4; Jer 2,14; 31,9"] },
      { number: 23, text: "und ich sage dir: Lass meinen Sohn ziehen*, damit er mir dient*! Wenn du dich aber weigerst, ihn ziehen zu lassen*, siehe, dann werde ich deinen erstgeborenen Sohn umbringen*.«", footnotes: ["℘ Kap. 5,1", "℘ Kap. 3,18; 7,16.26; 8,16; 9,1.13; 10,3", "℘ Kap. 7,27; 8,17; 9,2; 10,4", "℘ Kap. 11,5; 12,29; 13,15"] },
      { number: 24, text: "Und es geschah auf dem Weg, in der Herberge, da trat der HERR ihm entgegen und wollte ihn töten*.", footnotes: ["℘ 1Mo 17,14"] },
      { number: 25, text: "Da nahm Zippora* einen scharfen Stein, schnitt ihrem Sohn die Vorhaut ab, berührte damit seine Füße* und sagte: Wahrhaftig, du bist mir ein Blutbräutigam!", footnotes: ["℘ Kap. 2,21", "d. i. ein verhüllender Ausdruck für das Geschlechtsteil des Mose"] },
      { number: 26, text: "Da ließ er von ihm ab. Damals sagte sie »Blutbräutigam« wegen der Beschneidung." },
      { number: 27, text: "Und der HERR sprach zu Aaron: Geh Mose entgegen in die Wüste! Da ging er hin und traf ihn am Berg Gottes* und küsste ihn.", footnotes: ["℘ Kap. 3,1"] },
      { number: 28, text: "Und Mose teilte Aaron alle Worte des HERRN mit, der ihn gesandt, und all die Zeichen, die er ihm aufgetragen hatte*.", footnotes: ["℘ Kap. 3,5-4,9; 19,7; 4Mo 30,1"] },
      { number: 29, text: "Da gingen Mose und Aaron hin und versammelten alle Ältesten der Söhne Israel*.", footnotes: ["℘ Kap. 3,16; Ps 105,26"] },
      { number: 30, text: "Und Aaron redete zu ihnen alle Worte, die der HERR zu Mose geredet hatte, und tat die Zeichen vor den Augen des Volkes*.", footnotes: ["℘ Mk 16,20; 2Kor 12,12"] },
      { number: 31, text: "Und das Volk glaubte*. Und als sie hörten, dass der HERR die Söhne Israel heimgesucht* und ihr Elend gesehen habe, da warfen sie sich nieder und beteten an*.", footnotes: ["℘ Kap. 3,18; 14,31; 2Chr 32,8; Joh 2,11.23", "℘ Kap. 2,25; 1Mo 50,24; Rt 1,6", "℘ Kap. 12,27; 34,8; 1Mo 24,26; 2Chr 7,3; Hi 1,20"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Danach gingen Mose und Aaron hinein und sagten zum Pharao: So spricht der HERR, der Gott Israels: Lass mein Volk ziehen*, damit sie mir in der Wüste ein Fest feiern*!", heading: "Mose und Aaron vor Pharao", footnotes: ["℘ Kap. 4,23; 6,11; 7,2.16; 8,16; 9,1.13; 10,3", "℘ Kap. 10,9"] },
      { number: 2, text: "Der Pharao aber antwortete ihnen: Wer ist der HERR, dass ich auf seine Stimme hören sollte*, Israel ziehen zu lassen? Ich kenne den HERRN nicht und werde Israel auch nicht ziehen lassen*.", footnotes: ["℘ 1Sam 25,10; 2Kö 18,35; Hi 15,25.26; 21,15; Ps 12,5; Spr 30,9", "℘ Kap. 3,19"] },
      { number: 3, text: "Und sie sagten: Der Gott der Hebräer ist uns begegnet. Lass uns doch drei Tagereisen weit in die Wüste ziehen und dem HERRN, unserm Gott, opfern*, damit er uns nicht mit der Pest oder dem Schwert schlägt*!", footnotes: ["w. zum Opfer schlachten\n℘ Kap. 3,18", "℘ 3Mo 26,25; Esr 7,23"] },
      { number: 4, text: "Der König von Ägypten antwortete ihnen: Wozu, Mose und Aaron, wollt ihr das Volk von seinen Arbeiten abhalten? Geht an eure Lastarbeiten!" },
      { number: 5, text: "Weiter sagte der Pharao: Siehe, das Volk des Landes ist jetzt schon zahlreich, und ihr wollt sie mit ihren Lastarbeiten aufhören lassen!" },
      { number: 6, text: "Und der Pharao befahl am gleichen Tag den Antreibern des Volkes und seinen Aufsehern*:", heading: "Israels noch härtere Bedrückung", footnotes: ["w. Schreiber(n); d. i. eine Beamtenbezeichnung"] },
      { number: 7, text: "Ihr sollt dem Volk nicht mehr wie bisher* Häcksel zur Anfertigung der Ziegel liefern! Sie sollen selbst hingehen und sich Häcksel sammeln!", footnotes: ["w. gestern und vorgestern"] },
      { number: 8, text: "Aber ihr sollt ihnen dieselbe Anzahl Ziegel auferlegen, die sie bisher* angefertigt haben; ihr sollt nichts daran kürzen*! Denn sie sind faul; darum schreien* sie: Wir wollen hinziehen, wir wollen unserm Gott opfern*!", footnotes: ["w. gestern und vorgestern", "℘ Kap. 1,11", "o. jammern, zetern", "w. zum Opfer schlachten"] },
      { number: 9, text: "Die Arbeit soll schwer auf den Männern lasten, damit sie daran zu schaffen haben und nicht auf trügerische Reden achten*.", footnotes: ["℘ 2Kö 18,20"] },
      { number: 10, text: "Da gingen die Antreiber des Volkes und seine Aufseher* hinaus, redeten zum Volk und sagten: So spricht der Pharao: Ich gebe euch kein Häcksel mehr.", footnotes: ["w. Schreiber(n); d. i. eine Beamtenbezeichnung"] },
      { number: 11, text: "Geht selbst hin, holt euch Häcksel, wo ihr es findet; doch von eurer Arbeit wird nichts gekürzt." },
      { number: 12, text: "Darauf zerstreute sich das Volk im ganzen Land Ägypten, um Strohstoppeln für Häcksel zu sammeln." },
      { number: 13, text: "Und die Antreiber drängten sie und sagten: Vollendet eure Arbeiten, die Tagesleistung an ihrem Tag* wie früher, als noch Häcksel da war!", footnotes: ["d. h. Tag für Tag dieselbe Leistung"] },
      { number: 14, text: "Dazu wurden die Aufseher* der Söhne Israel, die die Antreiber des Pharao über sie gesetzt hatten, geschlagen*, indem man sagte: Warum habt ihr weder gestern noch heute euer Maß* an Ziegeln erfüllt wie bisher*?", footnotes: ["w. Schreiber(n); d. i. eine Beamtenbezeichnung", "℘ Kap. 1,14", "w. eure Ordnung", "w. gestern und vorgestern"] },
      { number: 15, text: "Da gingen die Aufseher* der Söhne Israel hinein und schrien zum Pharao: Warum verfährst du so mit deinen Knechten?", footnotes: ["w. Schreiber(n); d. i. eine Beamtenbezeichnung"] },
      { number: 16, text: "Häcksel wird deinen Knechten nicht gegeben, und doch sagt man zu uns: Stellt Ziegel her! Und siehe, deine Knechte werden geschlagen, und dein Volk wird schuldig*.", footnotes: ["w. die Schuld deines Volkes. — LXX und die syr. Üs. lesen: und du versündigst dich an deinem Volk; eine andere griech. Üs.: und Sünde ist bei dir"] },
      { number: 17, text: "Er antwortete: Faulenzer seid ihr, Faulenzer! Darum sagt ihr: Wir wollen hinziehen, wir wollen dem HERRN opfern*.", footnotes: ["w. zum Opfer schlachten"] },
      { number: 18, text: "Und jetzt geht, arbeitet! Häcksel wird euch nicht gegeben, aber die bestimmte Anzahl Ziegel sollt ihr abliefern*!", footnotes: ["℘ Pred 4,1"] },
      { number: 19, text: "Da sahen sich die Aufseher* der Söhne Israel in einer üblen Lage, weil man sagte: Ihr sollt nichts an euren Ziegeln kürzen: die Tagesleistung an ihrem Tag*!", footnotes: ["w. Schreiber(n); d. i. eine Beamtenbezeichnung", "d. h. Tag für Tag dieselbe Leistung"] },
      { number: 20, text: "Als sie nun vom Pharao herauskamen, trafen sie Mose und Aaron; die traten ihnen entgegen." },
      { number: 21, text: "Und sie* sagten zu ihnen: Der HERR sehe auf euch* und halte Gericht darüber, dass ihr unseren Geruch beim Pharao und bei seinen Hofbeamten* stinkend gemacht habt*, indem ihr ihnen das Schwert in die Hand gegeben habt, uns umzubringen.", footnotes: ["d. h. die Aufseher", "o. erscheine über euch", "w. Knechten", "℘ 1Mo 34,30"] },
      { number: 22, text: "Da wandte sich Mose an den HERRN und sagte: Herr, warum hast du so übel an diesem Volk gehandelt*? Wozu hast du mich denn gesandt*?", footnotes: ["℘ Jos 7,7", "℘ 4Mo 11,11; Jer 20,7"] },
      { number: 23, text: "Seitdem ich nämlich zum Pharao hineingegangen bin, um in deinem Namen zu reden, hat er an diesem Volk übel gehandelt, aber gerettet hast du dein Volk keineswegs*.", footnotes: ["℘ Hi 22,17"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Der HERR jedoch sprach zu Mose: Nun sollst du sehen, was ich dem Pharao antun werde*. Denn durch eine starke Hand gezwungen, wird er sie ziehen lassen*, ja, durch eine starke Hand* gezwungen, wird er sie aus seinem Land hinausjagen*.", footnotes: ["℘ 4Mo 11,23; 2Chr 20,17; Ps 12,6", "℘ Kap. 3,19.20; 13,3.14.16", "LXX und die syr. Üs. lesen: durch einen ausgestreckten Arm", "℘ Kap. 12,31"] },
      { number: 2, text: "Und Gott redete zu Mose und sprach zu ihm: Ich bin Jahwe*.", heading: "Moses erneute Berufung und weiterer Auftrag", footnotes: ["s. Anm. zu Kap. 3,15"] },
      { number: 3, text: "Ich bin Abraham, Isaak und Jakob erschienen als Gott, der Allmächtige*; aber mit meinem Namen Jahwe* habe ich mich ihnen nicht zu erkennen gegeben*.", footnotes: ["d. i. ein anderer Name Gottes; hebr. el schaddaj. Die Bedeutung des Wortes — gewöhnlich als »der Allmächtige« übersetzt — ist unsicher.\n℘ 1Mo 17,1", "s. Anm. zu Kap. 3,15", "℘ Kap. 3,14.15; Ps 83,19"] },
      { number: 4, text: "Auch habe ich meinen Bund mit ihnen aufgerichtet, ihnen das Land Kanaan* zu geben, das Land ihrer Fremdlingschaft, in dem sie sich als Fremdlinge aufgehalten haben*.", footnotes: ["℘ V. 8; Kap. 13,5; 1Mo 12,7", "℘ 1Mo 17,8; Ps 105,11.12"] },
      { number: 5, text: "Und ich habe auch das Ächzen der Söhne Israel gehört, die die Ägypter zur Arbeit zwingen, und ich habe an meinen Bund gedacht*.", footnotes: ["℘ Kap. 2,24"] },
      { number: 6, text: "Darum sage zu den Söhnen Israel: »Ich bin der HERR; ich werde euch herausführen unter den Lastarbeiten der Ägypter hinweg, euch aus ihrer Arbeit retten* und euch erlösen mit ausgestrecktem Arm* und durch große Gerichte*.", footnotes: ["℘ Kap. 3,8.17; Ps 81,7", "℘ Kap. 13,16; 32,11; 5Mo 4,34; 5,15; 9,29; 11,2; 26,8; 1Kö 8,42; Ps 77,16; 136,12; Apg 13,17", "℘ Kap. 7,4"] },
      { number: 7, text: "Und ich will euch mir zum Volk annehmen* und will euer Gott* sein*. Und ihr sollt erkennen, dass ich der HERR, euer Gott, bin*, der euch herausführt unter den Lastarbeiten der Ägypter hinweg*.", footnotes: ["℘ Kap. 15,16; 19,5; 2Sam 7,23.24; Neh 1,10; Ps 100,3; Tit 2,14", "w. für euch zum Gott", "℘ Kap. 15,2; 29,45.46; 1Mo 17,8; 26,3; 28,13; 5Mo 29,12; Jer 31,33; Mk 12,26.27", "℘ Kap. 7,17; 14,4.18; 16,12; 5Mo 29,5; 1Kö 8,60; 20,28; Jes 49,23.26; 51,15; Joe 4,17; Joh 8,28", "℘ Kap. 13,3.14; 4Mo 15,41"] },
      { number: 8, text: "Dann werde ich euch in das Land bringen, um dessentwillen ich meine Hand zum Schwur erhoben habe*, dass ich es Abraham, Isaak und Jakob geben will, und ich werde es euch zum Besitz geben*, ich, der HERR*.«", footnotes: ["℘ Hes 20,5", "℘ 4Mo 10,29; 11,12; 5Mo 4,31; Hes 47,14", "o. ich bin der HERR"] },
      { number: 9, text: "Mose nun redete so zu den Söhnen Israel. Aber aus Verzagtheit* und wegen ihrer schweren Arbeit hörten sie nicht auf Mose*.", footnotes: ["o. Ungeduld", "℘ Spr 18,14"] },
      { number: 10, text: "Da redete der HERR zu Mose und sprach:" },
      { number: 11, text: "Geh hinein, sage dem Pharao, dem König von Ägypten, er soll die Söhne Israel aus seinem Land ziehen lassen*!", footnotes: ["℘ Kap. 5,1"] },
      { number: 12, text: "Mose aber redete vor dem HERRN und sagte: Siehe, die Söhne Israel haben nicht auf mich gehört, wie sollte da der Pharao mich anhören, zumal ich unbeschnittene Lippen* habe*!", footnotes: ["d. h. unreine Lippen; vgl. Jes 6,5", "℘ V. 30; Kap. 4,10; Jes 6,5; Lk 5,8"] },
      { number: 13, text: "Aber der HERR redete zu Mose und zu Aaron und beauftragte sie als Gesandte an die Söhne Israel und an den Pharao, den König von Ägypten, die Söhne Israel aus dem Land Ägypten hinauszuführen*.", footnotes: ["℘ Ps 77,21"] },
      { number: 14, text: "Dies sind die Häupter ihrer Vaterhäuser*: Die Söhne Rubens, des Erstgeborenen Israels: Henoch, Pallu, Hezron und Karmi; das sind die Sippen Rubens*.", heading: "Stammbaum Moses und Aarons", footnotes: ["℘ 4Mo 1,18", "℘ 4Mo 26,5-9; 1Chr 5,3"] },
      { number: 15, text: "Und die Söhne Simeons: Jemuël, Jamin, Ohad, Jachin, Zohar und Schaul, der Sohn der Kanaaniterin; das sind die Sippen Simeons*.", footnotes: ["℘ 4Mo 26,12-14; 1Chr 4,24"] },
      { number: 16, text: "*Und dies sind die Namen der Söhne Levis nach ihrer Generationenfolge*: Gerschon, Kehat und Merari*; und die Lebensjahre Levis betrugen 137 Jahre.", footnotes: ["℘ V. 16-25: 1Chr 5,27-30; 6,1-15", "o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1", "℘ 1Mo 46,9-11; 2Chr 29,12"] },
      { number: 17, text: "Die Söhne Gerschons waren: Libni und Schimi nach ihren Sippen." },
      { number: 18, text: "Und die Söhne Kehats: Amram, Jizhar, Hebron und Usiël*; und die Lebensjahre Kehats betrugen 133 Jahre.", footnotes: ["℘ 1Chr 15,10; 23,12"] },
      { number: 19, text: "Und die Söhne Meraris: Machli und Muschi*; das sind die Sippen Levis nach ihrer Generationenfolge*.", footnotes: ["℘ 4Mo 3,17-20; 1Chr 23,21; 24,26", "o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 20, text: "Und Amram nahm sich Jochebed, die Schwester seines Vaters, zur Frau*; die gebar ihm Aaron und Mose*; und die Lebensjahre Amrams betrugen 137 Jahre.", footnotes: ["℘ Kap. 2,1", "℘ 4Mo 26,58.59; 1Chr 23,13"] },
      { number: 21, text: "Die Söhne Jizhars aber waren Korach*, Nefeg und Sichri,", footnotes: ["℘ 4Mo 16,1; 1Chr 6,22.23"] },
      { number: 22, text: "und die Söhne Usiëls Mischaël, Elizafan* und Sitri.", footnotes: ["℘ 3Mo 10,4; 4Mo 3,30; 1Chr 15,8; 2Chr 29,13"] },
      { number: 23, text: "Aaron aber nahm sich Elischeba, die Tochter Amminadabs, die Schwester Nachschons*, zur Frau; die gebar ihm Nadab, Abihu*, Eleasar* und Itamar*.", footnotes: ["℘ 4Mo 1,7", "℘ Kap. 24,1; 3Mo 10,1", "℘ 4Mo 20,28; Jos 24,33", "℘ Kap. 28,1; 3Mo 10,6; 4Mo 3,2; 26,60; 1Chr 24,1"] },
      { number: 24, text: "Und die Söhne Korachs waren Assir, Elkana und Abiasaf*; das sind die Sippen der Korachiter.", footnotes: ["℘ 4Mo 26,11"] },
      { number: 25, text: "Eleasar aber, der Sohn Aarons, nahm sich eine von den Töchtern Putiëls zur Frau; die gebar ihm Pinhas*; dies sind die Familienhäupter der Leviten nach ihren Sippen*.", footnotes: ["℘ 4Mo 25,7; Jos 22,13; 24,33; Ri 20,28", "℘ 4Mo 26,57-60"] },
      { number: 26, text: "Dieser Aaron und dieser Mose sind es, zu denen der HERR gesprochen hat: Führt die Söhne Israel aus dem Land Ägypten hinaus nach ihren Heerscharen geordnet!*", footnotes: ["℘ Kap. 7,4; 12,41.51; 4Mo 33,1"] },
      { number: 27, text: "Diese sind es, die zum Pharao, dem König von Ägypten, redeten*, um die Söhne Israel aus Ägypten hinauszuführen: das sind Mose und Aaron*.", footnotes: ["℘ Kap. 5,1-3", "℘ Jos 24,5; 1Sam 12,6; Ps 105,26; Mi 6,4"] },
      { number: 28, text: "Und es geschah an dem Tag, an dem der HERR zu Mose im Land Ägypten redete,", heading: "Beglaubigungszeichen vor Pharao" },
      { number: 29, text: "dass der HERR zu Mose redete und sprach: Ich bin der HERR. Rede zum Pharao, dem König von Ägypten, alles, was ich zu dir rede*!", footnotes: ["℘ Kap. 7,2; Jer 1,7.17; Hes 2,7"] },
      { number: 30, text: "Mose aber sagte vor dem HERRN: Siehe, ich habe unbeschnittene Lippen*, wie sollte der Pharao auf mich hören?*", footnotes: ["d. h. unreine Lippen; vgl. Jes 6,5", "℘ V. 12"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und der HERR sprach zu Mose: Siehe, ich habe dich für den Pharao zum Gott eingesetzt, und dein Bruder Aaron soll dein Prophet* sein*.", footnotes: ["d. h. jemand, der im Namen Gottes spricht", "℘ Kap. 4,15.16"] },
      { number: 2, text: "Du sollst alles reden, was ich dir befehlen werde*, und dein Bruder Aaron soll zum Pharao reden, dass er die Söhne Israel aus seinem Land ziehen lassen soll*.", footnotes: ["℘ Kap. 6,29", "℘ Kap. 5,1"] },
      { number: 3, text: "Ich aber will das Herz des Pharao verhärten* und meine Zeichen und Wunder* im Land Ägypten zahlreich machen*.", footnotes: ["℘ Kap. 4,21; Spr 21,1", "o. Wahrzeichen", "℘ Kap. 3,20; Ps 78,12; 105,27; Apg 7,36"] },
      { number: 4, text: "Und der Pharao wird nicht auf euch hören. Dann werde ich meine Hand an Ägypten* legen und meine Heerscharen, mein Volk, die Söhne Israel, durch große Gerichte aus dem Land Ägypten herausführen.", footnotes: ["o. die Ägypter"] },
      { number: 5, text: "Und die Ägypter sollen erkennen, dass ich der HERR bin, wenn ich meine Hand über Ägypten* ausstrecke und die Söhne Israel aus ihrer Mitte herausführe*.", footnotes: ["o. die Ägypter", "℘ Kap. 6,6.26"] },
      { number: 6, text: "Da handelten Mose und Aaron, wie ihnen der HERR befohlen hatte, so handelten sie*.", footnotes: ["℘ V. 20; Kap. 12,28"] },
      { number: 7, text: "Mose aber war 80 Jahre alt* und Aaron 83 Jahre*, als sie zum Pharao redeten.", footnotes: ["℘ 5Mo 31,2", "℘ 4Mo 33,39"] },
      { number: 8, text: "Und der HERR sprach zu Mose und Aaron:" },
      { number: 9, text: "Wenn der Pharao zu euch reden und sagen wird: Weist euch durch ein Wunder* aus*! — dann sollst du zu Aaron sagen: Nimm deinen Stab und wirf ihn vor dem Pharao hin! — er wird zu einer Schlange* werden.", footnotes: ["o. Wahrzeichen", "℘ Joh 2,18", "o. Drache(n); vgl. Jes 51,9"] },
      { number: 10, text: "Da gingen Mose und Aaron zum Pharao hinein und machten es so, wie der HERR geboten hatte*: Aaron warf seinen Stab vor dem Pharao und vor seinen Hofbeamten* hin, und er wurde zur Schlange*.", footnotes: ["℘ V. 20; Kap. 12,28", "w. Knechten", "o. Drache(n); vgl. Jes 51,9\n℘ Kap. 4,3"] },
      { number: 11, text: "Da rief auch der Pharao die Weisen und Zauberer*; und auch sie, die Wahrsagepriester* Ägyptens, machten es ebenso mit ihren Zauberkünsten*,", footnotes: ["℘ 1Mo 41,8; Dan 2,2; Offb 21,8", "o. die Geheimgelehrten. — Das sind Gelehrte, die zugleich Zauberer sind.", "℘ Kap. 8,3.14; 2Tim 3,8"] },
      { number: 12, text: "sie warfen jeder seinen Stab hin, und es wurden Schlangen* daraus. Aber Aarons Stab verschlang ihre Stäbe.", footnotes: ["o. Drache(n); vgl. Jes 51,9"] },
      { number: 13, text: "Doch das Herz des Pharao wurde* verstockt*, und er hörte nicht auf sie, wie der HERR geredet hatte.", footnotes: ["o. blieb", "℘ V. 22; Kap. 9,35; 2Chr 36,13; Sach 7,12; Hebr 4,7"] },
      { number: 14, text: "Und der HERR sprach zu Mose: Das Herz des Pharao ist verstockt*. Er weigert sich, das Volk ziehen zu lassen*.", heading: "Erste Plage: Wasser wird zu Blut", footnotes: ["w. schwer, stumpf\n℘ Kap. 8,11.28; 9,7.34; 10,1; 5Mo 2,30; 1Sam 6,6", "℘ Kap. 3,19"] },
      { number: 15, text: "Geh morgen früh zum Pharao — siehe, er wird ans Wasser hinausgehen —, tritt ihm entgegen am Ufer des Nil, nimm den Stab, der sich in eine Schlange verwandelt hat, in deine Hand" },
      { number: 16, text: "und sage zu ihm: »Der HERR, der Gott der Hebräer, hat mich zu dir gesandt und gesagt: Lass mein Volk ziehen, damit sie mir in der Wüste dienen*! Aber siehe, du hast bisher nicht gehört.", footnotes: ["℘ V. 26; Kap. 4,23; 5,1"] },
      { number: 17, text: "Darum, so spricht der HERR: Daran sollst du erkennen, dass ich der HERR bin*: Siehe, ich will mit dem Stab, der in meiner Hand ist, auf das Wasser im Nil schlagen, und es wird sich in Blut verwandeln.", footnotes: ["℘ Kap. 4,9; 6,7; 2Kö 19,19"] },
      { number: 18, text: "Dann werden die Fische im Nil sterben, und der Nil wird stinken, so dass es die Ägypter ekeln wird*, Wasser aus dem Nil zu trinken.«", footnotes: ["w. so dass sich die Ägypter vergeblich abmühen werden"] },
      { number: 19, text: "Und der HERR sprach zu Mose: Sage zu Aaron: Nimm deinen Stab und strecke deine Hand aus über die Gewässer Ägyptens, über seine Flüsse, Nilarme*, Sümpfe* und all seine Wasserstellen, so dass sie zu Blut werden! Und im ganzen Land Ägypten wird Blut sein, selbst in Gefäßen aus Holz und Stein.", footnotes: ["o. Kanäle (zur Bewässerung des Niltals und -deltas)", "Das sind die Lachen, die nach der Nilüberschwemmung zurückbleiben; darum auch: Tümpel mit Schilfrohr"] },
      { number: 20, text: "Da taten Mose und Aaron, wie der HERR geboten hatte; und er erhob den Stab und schlug vor den Augen des Pharao und vor den Augen seiner Hofbeamten auf das Wasser im Nil*. Da wurde alles Wasser, das im Nil war, in Blut verwandelt*.", footnotes: ["℘ Kap. 17,5", "℘ Kap. 4,9; Ps 78,44; Offb 8,8"] },
      { number: 21, text: "Die Fische im Nil starben*, und der Nil wurde stinkend, und die Ägypter konnten das Wasser aus dem Nil nicht trinken*; und das Blut war im ganzen Land Ägypten.", footnotes: ["℘ Ps 105,29", "℘ Jes 19,8"] },
      { number: 22, text: "Aber die Wahrsagepriester* Ägyptens machten es ebenso mit ihren Zauberkünsten*. Da blieb das Herz des Pharao verstockt, und er hörte nicht auf sie, wie der HERR geredet hatte.", footnotes: ["o. die Geheimgelehrten. — Das sind Gelehrte, die zugleich Zauberer sind.", "℘ V. 11; 2Thes 2,9"] },
      { number: 23, text: "Da wandte sich der Pharao um, ging in sein Haus und nahm auch dies nicht zu Herzen*.", footnotes: ["℘ Kap. 9,21; Spr 28,14; Jes 47,7; Jer 36,24"] },
      { number: 24, text: "Alle Ägypter aber gruben in der Umgebung des Nil nach Wasser zum Trinken, denn vom Wasser des Nil konnten sie nicht trinken." },
      { number: 25, text: "Und es wurden sieben Tage erfüllt, nachdem der HERR den Nil geschlagen hatte." },
      { number: 26, text: "Darauf sprach der HERR zu Mose: Geh zum Pharao hinein und sage zu ihm: »So spricht der HERR: Lass mein Volk ziehen, damit sie mir dienen!*", heading: "Zweite Plage: Frösche", footnotes: ["℘ V. 16; Kap. 5,1"] },
      { number: 27, text: "Wenn du dich aber weigerst, es ziehen zu lassen*, siehe, so will ich dein ganzes Gebiet mit Fröschen schlagen*.", footnotes: ["℘ Kap. 3,19; 4,23", "℘ Ps 78,45; Offb 16,13"] },
      { number: 28, text: "Und der Nil wird von Fröschen wimmeln, und sie werden heraufsteigen und in dein Haus kommen, in dein Schlafzimmer und auf dein Bett, in die Häuser deiner Hofbeamten* und unter dein Volk, in deine Backöfen und in deine Backtröge.", footnotes: ["w. Knechte(n)"] },
      { number: 29, text: "Und die Frösche werden heraufkommen über dich, über dein Volk und über all deine Hofbeamten*.«", footnotes: ["w. Knechte(n)"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und der HERR sprach zu Mose: Sage zu Aaron: Strecke deine Hand mit deinem Stab aus* über die Flüsse, die Nilarme* und die Sümpfe*, und lass die Frösche über das Land Ägypten heraufkommen*!", footnotes: ["℘ Jos 8,18", "o. Kanäle (zur Bewässerung des Niltals und -deltas)", "Das sind die Lachen, die nach der Nilüberschwemmung zurückbleiben; darum auch: Tümpel mit Schilfrohr", "℘ Kap. 7,27; Ps 105,30"] },
      { number: 2, text: "Da streckte Aaron seine Hand aus über die Gewässer in Ägypten, und die Frösche kamen herauf und bedeckten das Land Ägypten." },
      { number: 3, text: "Aber die Wahrsagepriester* machten es ebenso mit ihren Zauberkünsten* und ließen die Frösche über das Land Ägypten heraufkommen.", footnotes: ["o. die Geheimgelehrten. — Das sind Gelehrte, die zugleich Zauberer sind.", "℘ Kap. 7,11.22; Mt 24,24"] },
      { number: 4, text: "Da rief der Pharao Mose und Aaron zu sich und sagte: Betet zum HERRN*, dass er die Frösche von mir und meinem Volk wegschafft! Dann will ich das Volk ziehen lassen, und sie mögen dem HERRN opfern*.", footnotes: ["℘ V. 24; Kap. 9,28; 10,17; 4Mo 21,7; 1Kö 13,6; Apg 8,24", "w. zum Opfer schlachten"] },
      { number: 5, text: "Und Mose sagte zum Pharao: Verfüge über mich*, auf wann ich für dich, für deine Hofbeamten* und für dein Volk beten soll zur Ausrottung der Frösche von dir und aus deinen Häusern, so dass sie nur im Nil übrig bleiben!", footnotes: ["w. Verherrliche dich an mir", "w. Knechte(n)"] },
      { number: 6, text: "Er antwortete: Auf morgen. Da sagte er: Nach deinem Wort soll es geschehen, damit du erkennst, dass niemand ist wie der HERR, unser Gott*.", footnotes: ["℘ Kap. 9,14.29; 10,2; 15,11; 5Mo 4,35.39; 32,31; 33,26; 2Sam 7,22; 2Chr 6,14; Ps 83,19; 86,8; 90,2; Jes 43,10"] },
      { number: 7, text: "Und die Frösche werden von dir, aus deinen Häusern, von deinen Hofbeamten* und von deinem Volk weichen; nur im Nil sollen sie übrig bleiben.", footnotes: ["w. Knechte(n)"] },
      { number: 8, text: "Nachdem nun Mose und Aaron vom Pharao hinausgegangen waren, schrie Mose zum HERRN wegen der Frösche, die er über den Pharao gebracht hatte*.", footnotes: ["℘ V. 26; Kap. 9,33; 10,18; 32,11; Lk 6,28"] },
      { number: 9, text: "Und der HERR tat nach dem Wort des Mose*, und die Frösche starben weg aus den Häusern, aus den Gehöften und von den Feldern.", footnotes: ["℘ 4Mo 14,20"] },
      { number: 10, text: "Und man schüttete sie haufenweise zusammen, so dass das Land davon stank." },
      { number: 11, text: "Als aber der Pharao sah, dass die versprochene Erleichterung eingetreten war, da verstockte* er sein Herz*, und er hörte nicht auf sie, wie der HERR geredet hatte.", footnotes: ["w. machte . . . schwer o. stumpf", "℘ Kap. 4,21; 7,13"] },
      { number: 12, text: "Und der HERR sprach zu Mose: Sage zu Aaron: Strecke deinen Stab aus und schlage den Staub auf der Erde! Dann wird er im ganzen Land Ägypten zu Mücken werden.", heading: "Dritte Plage: Mücken" },
      { number: 13, text: "Sie machten es so*: Aaron streckte seine Hand mit seinem Stab aus und schlug den Staub auf der Erde. Da kamen die Mücken über die Menschen und über das Vieh; aller Staub der Erde wurde zu Mücken im ganzen Land Ägypten*.", footnotes: ["LXX lässt »Sie machten es so« weg.", "℘ Ps 105,31"] },
      { number: 14, text: "Die Wahrsagepriester* aber machten es ebenso mit ihren Zauberkünsten, um die Mücken hervorzubringen; aber sie konnten es nicht*. Und die Mücken kamen über die Menschen und über das Vieh.", footnotes: ["o. die Geheimgelehrten. — Das sind Gelehrte, die zugleich Zauberer sind.", "℘ Kap. 9,11; 1Kö 18,26.29; Jes 19,11; 2Tim 3,9"] },
      { number: 15, text: "Da sagten die Wahrsagepriester* zum Pharao: Das ist der Finger Gottes*! Aber das Herz des Pharao blieb verstockt, und er hörte nicht auf sie, wie der HERR geredet hatte*.", footnotes: ["o. die Geheimgelehrten. — Das sind Gelehrte, die zugleich Zauberer sind.", "o. eines Gottes\n℘ 1Sam 6,3.9; Lk 11,20", "℘ V. 28; Kap. 4,21"] },
      { number: 16, text: "Und der HERR sprach zu Mose: Mach dich morgen früh auf, tritt vor den Pharao — siehe, er wird ans Wasser hinausgehen — und sage zu ihm: »So spricht der HERR: Lass mein Volk ziehen, damit sie mir dienen*!", heading: "Vierte Plage: Stechfliegen", footnotes: ["℘ Kap. 4,23; 5,1"] },
      { number: 17, text: "Denn wenn du mein Volk nicht ziehen lässt*, siehe, so werde ich die Stechfliegen* ziehen lassen über dich, deine Hofbeamten*, dein Volk und deine Häuser. Und die Häuser der Ägypter werden voll von Stechfliegen sein, ja sogar der Erdboden, auf dem sie stehen.", footnotes: ["℘ Kap. 4,23; 5,1", "LXX üs.: Hundsfliegen; andere: allerlei Ungeziefer", "w. Knechte(n)"] },
      { number: 18, text: "Ich werde aber an jenem Tag das Land Goschen, in dem sich mein Volk aufhält, besonders behandeln, so dass dort keine Stechfliegen* sein werden, damit du erkennst, dass ich, der HERR, mitten im Land bin.", footnotes: ["LXX üs.: Hundsfliegen; andere: allerlei Ungeziefer"] },
      { number: 19, text: "Und ich werde einen Unterschied* setzen* zwischen meinem Volk und deinem Volk; morgen wird dieses Zeichen geschehen.«", footnotes: ["so mit LXX und Vulg.; Mas. T.: eine Erlösung", "℘ Kap. 9,4.26; 10,23; 11,7"] },
      { number: 20, text: "Und der HERR machte es so: Es kamen Stechfliegen* in Menge in das Haus des Pharao und in die Häuser* seiner Hofbeamten* und ins ganze Land Ägypten. So wurde das Land von den Stechfliegen* verheert*.", footnotes: ["LXX üs.: Hundsfliegen; andere: allerlei Ungeziefer", "so mit LXX; Mas. T.: in das Haus", "w. Knechte(n)", "w. Knechte(n)", "℘ Ps 78,45; 105,31"] },
      { number: 21, text: "Da rief der Pharao Mose und Aaron und sagte: Geht hin und opfert* eurem Gott hier im Land!", footnotes: ["w. schlachtet zum Opfer"] },
      { number: 22, text: "Mose erwiderte: Es ist nicht statthaft, es zu tun; denn wir würden dem HERRN, unserem Gott, opfern*, was den Ägyptern ein Gräuel ist. Siehe, wenn wir vor den Augen der Ägypter opferten, was ihnen ein Gräuel ist, würden sie uns dann nicht steinigen*?", footnotes: ["w. zum Opfer schlachten", "℘ 1Mo 46,34"] },
      { number: 23, text: "Drei Tagereisen weit wollen wir in die Wüste ziehen und dem HERRN, unserem Gott, opfern*, wie er uns befiehlt*.", footnotes: ["w. zum Opfer schlachten", "℘ Kap. 3,18"] },
      { number: 24, text: "Da sagte der Pharao: Ich will euch ziehen lassen, damit ihr dem HERRN, eurem Gott, in der Wüste opfert*. Nur entfernt euch nicht zu weit! Betet für mich!", footnotes: ["w. schlachtet zum Opfer"] },
      { number: 25, text: "Mose antwortete: Siehe, wenn ich von dir hinausgegangen bin, will ich zum HERRN beten, und morgen werden die Stechfliegen* vom Pharao, von seinen Hofbeamten* und von seinem Volk weichen. Nur möge der Pharao uns nicht noch einmal täuschen*, so dass er das Volk nicht ziehen lässt, damit es dem HERRN opfert*!", footnotes: ["LXX üs.: Hundsfliegen; andere: allerlei Ungeziefer", "w. Knechte(n)", "℘ Jes 28,22", "w. zum Opfer schlachtet"] },
      { number: 26, text: "Darauf ging Mose vom Pharao hinaus und betete zum HERRN." },
      { number: 27, text: "Und der HERR tat nach dem Wort des Mose und schaffte die Stechfliegen* weg vom Pharao, von seinen Hofbeamten* und von seinem Volk. Nicht eine blieb übrig.", footnotes: ["s. Anm. zu Kap. 8,17", "w. Knechte(n)"] },
      { number: 28, text: "Aber der Pharao verstockte* sein Herz auch diesmal* und ließ das Volk nicht ziehen*.", footnotes: ["w. machte . . . schwer o. stumpf", "℘ Kap. 7,13", "℘ V. 15; Kap. 3,19"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Da sprach der HERR zu Mose: Geh zum Pharao hinein und sage zu ihm: »So spricht der HERR, der Gott der Hebräer: Lass mein Volk ziehen, damit sie mir dienen*!", heading: "Fünfte Plage: Viehpest", footnotes: ["℘ V. 13; Kap. 4,23; 5,1"] },
      { number: 2, text: "Denn wenn du dich weigerst*, sie ziehen zu lassen, und sie noch länger festhältst*,", footnotes: ["℘ V. 13; Kap. 4,23; 5,1", "℘ Jes 1,20"] },
      { number: 3, text: "siehe, dann wird die Hand des HERRN über dein Vieh kommen, das auf dem Feld ist, über die Pferde, über die Esel, über die Kamele, über die Rinder und über die Schafe — eine sehr schwere Pest*.", footnotes: ["℘ Am 4,10"] },
      { number: 4, text: "Aber der HERR wird einen Unterschied machen zwischen dem Vieh Israels und dem Vieh der Ägypter, so dass von allem, was den Söhnen Israel gehört, nicht ein Stück sterben wird*.«", footnotes: ["℘ Kap. 8,19"] },
      { number: 5, text: "Auch setzte der HERR eine bestimmte Zeit fest, indem er sprach: Morgen wird der HERR dies im Lande tun." },
      { number: 6, text: "Und der HERR tat es am Tag darauf, da starb alles Vieh der Ägypter, aber von dem Vieh der Söhne Israel starb kein einziges Stück*.", footnotes: ["℘ V. 25.26; Kap. 12,12; Ps 78,50"] },
      { number: 7, text: "Und der Pharao sandte hin, und siehe, von dem Vieh Israels war auch nicht ein Stück gestorben. Aber das Herz des Pharao blieb verstockt*, und er ließ das Volk nicht ziehen*.", footnotes: ["w. blieb schwer o. stumpf\n℘ Kap. 7,13.22", "℘ Kap. 3,19"] },
      { number: 8, text: "Da sprach der HERR zu Mose und Aaron: Nehmt euch beide Hände voll Ofenruß, und Mose soll ihn vor den Augen des Pharao gegen den Himmel streuen.", heading: "Sechste Plage: Geschwüre" },
      { number: 9, text: "Dann wird er über dem ganzen Land Ägypten zu Staub werden, und es werden daraus an den Menschen und am Vieh im ganzen Land Ägypten Geschwüre entstehen, die in Blasen aufbrechen." },
      { number: 10, text: "Und sie nahmen den Ofenruß und traten vor den Pharao, und Mose streute ihn gegen den Himmel; so wurde er zu Geschwüren von Blasen, die an den Menschen und am Vieh aufbrachen*.", footnotes: ["℘ 5Mo 28,27; Offb 16,2.11"] },
      { number: 11, text: "Die Wahrsagepriester* aber konnten wegen der Geschwüre nicht vor Mose treten*; denn die Geschwüre waren an den Wahrsagepriestern wie an allen Ägyptern.", footnotes: ["s. Anm. zu Kap. 8,15", "℘ Kap. 8,14"] },
      { number: 12, text: "Doch der HERR verstockte das Herz des Pharao*, und er hörte nicht auf sie, wie der HERR zu Mose geredet hatte.", footnotes: ["℘ Kap. 4,21"] },
      { number: 13, text: "Da sprach der HERR zu Mose: Mach dich früh am Morgen auf, tritt vor den Pharao und sage zu ihm: »So spricht der HERR, der Gott der Hebräer: Lass mein Volk ziehen, damit sie mir dienen!", heading: "Siebte Plage: Hagel" },
      { number: 14, text: "Denn diesmal will ich all meine Plagen in dein Herz, unter deine Hofbeamten* und unter dein Volk senden*, damit du erkennst, dass niemand auf der ganzen Erde mir gleich ist*.", footnotes: ["w. Knechte(n)", "℘ 3Mo 26,18; 1Sam 4,8", "℘ Kap. 8,6"] },
      { number: 15, text: "Denn schon jetzt hätte ich meine Hand ausstrecken und dich und dein Volk mit der Pest schlagen können, so dass du von der Erde ausgetilgt worden wärst*.", footnotes: ["℘ 2Sam 7,23; 2Kö 19,35"] },
      { number: 16, text: "Aber eben deshalb habe ich dich bestehen lassen, um dir meine Macht zu zeigen, und damit man auf der ganzen Erde meinen Namen verkündigt.*", footnotes: ["℘ 4Mo 14,21; Jos 4,24; Röm 9,17"] },
      { number: 17, text: "Doch du verhältst dich noch immer hochmütig gegen mein Volk*, dass du sie nicht ziehen lässt*.", footnotes: ["o. widersetzt dich . . . meinem Volk", "℘ Hi 9,4"] },
      { number: 18, text: "Siehe, ich will morgen um diese Zeit einen sehr schweren Hagel regnen lassen*, wie es in Ägypten noch keinen gegeben hat vom Tag seiner Gründung* an bis jetzt*.", footnotes: ["℘ Offb 8,7", "w. Grundsteinlegung", "℘ Kap. 10,6.14; 11,6"] },
      { number: 19, text: "Und nun sende hin und bring dein Vieh in Sicherheit und alles, was du auf dem Feld hast! Alle Menschen und Tiere, die sich auf dem Feld befinden und nicht ins Haus gebracht* werden, auf die wird der Hagel fallen, und sie werden sterben.«", footnotes: ["w. versammelt"] },
      { number: 20, text: "Wer nun unter den Dienern des Pharao das Wort des HERRN fürchtete, der ließ seine Knechte und sein Vieh in die Häuser flüchten*.", footnotes: ["℘ Kap. 7,23; Spr 22,3"] },
      { number: 21, text: "Wer aber das Wort des HERRN nicht zu Herzen nahm, der ließ seine Knechte und sein Vieh auf dem Feld*.", footnotes: ["℘ Kap. 7,23; Spr 22,3"] },
      { number: 22, text: "Und der HERR sprach zu Mose: Strecke deine Hand gegen den Himmel aus, dann wird im ganzen Land Ägypten Hagel fallen* auf die Menschen und auf die Tiere und auf alles Gewächs des Feldes im Land Ägypten!", footnotes: ["w. entstehen"] },
      { number: 23, text: "Da streckte Mose seinen Stab gegen den Himmel aus, und der HERR sandte Donner* und Hagel*; und Feuer fuhr zur Erde nieder. So ließ der HERR Hagel auf das Land Ägypten regnen.", footnotes: ["w. gab Stimmen; vgl. V. 28", "℘ Offb 8,7"] },
      { number: 24, text: "Und mit dem Hagel kam Feuer, das mitten im Hagel hin und her zuckte*; und der Hagel war sehr schwer, wie es im ganzen Land Ägypten noch keinen gegeben hat, seitdem dieses Land eine Nation geworden ist.", footnotes: ["℘ Ps 18,13; 105,32; Jes 30,30; Hes 1,4; Offb 16,21"] },
      { number: 25, text: "Und der Hagel schlug im ganzen Land Ägypten alles, was auf dem Feld war, vom Menschen bis zum Vieh*; auch alles Gewächs des Feldes zerschlug der Hagel, und alle Bäume des Feldes zerbrach er*.", footnotes: ["℘ Ps 78,47.48", "℘ Jos 10,11"] },
      { number: 26, text: "Nur im Land Goschen, wo die Söhne Israel waren, fiel kein Hagel*.", footnotes: ["℘ V. 6; Kap. 8,19; Jes 32,18; Jer 23,6"] },
      { number: 27, text: "Da sandte der Pharao hin, ließ Mose und Aaron rufen und sagte zu ihnen: Diesmal habe ich gesündigt*. Der HERR ist der Gerechte*, ich aber und mein Volk sind die Schuldigen*.", footnotes: ["℘ Kap. 10,16; 4Mo 21,7; 22,34; Jos 7,20; 1Sam 15,24.30; 2Sam 12,13; Mt 27,4", "℘ 2Chr 12,6; Kla 1,18; Dan 9,14", "Das Wort bezeichnet das Gegenteil des Gerechten."] },
      { number: 28, text: "Betet zum HERRN, dass es nun genug sei mit dem Donner* Gottes und dem Hagel*! Dann will ich euch ziehen lassen, und ihr braucht nicht länger zu bleiben.", footnotes: ["w. mit den Stimmen", "℘ Kap. 8,4.24"] },
      { number: 29, text: "Da sagte Mose zu ihm: Sobald ich zur Stadt hinausgehe, will ich meine Hände zum HERRN ausbreiten*; der Donner wird* aufhören, und der Hagel wird nicht mehr fallen*, damit du erkennst, dass die Erde dem HERRN gehört*.", footnotes: ["℘ 1Kö 8,22; 2Chr 6,13; Esr 9,5; Hi 11,13; Ps 143,6", "w. die Stimmen werden", "w. entstehen", "℘ Kap. 8,6.18; 5Mo 10,14"] },
      { number: 30, text: "Du aber und deine Hofbeamten* — das habe ich erkannt, dass ihr euch immer noch nicht vor Gott, dem HERRN, fürchtet.", footnotes: ["w. Knechte"] },
      { number: 31, text: "Der Flachs und die Gerste zwar waren zerschlagen; denn die Gerste stand in Ähren und der Flachs in Blüte." },
      { number: 32, text: "Aber der Weizen und das Korn* waren nicht zerschlagen, weil sie später reif werden.", footnotes: ["unbekannte Kornart; vielleicht Emmer"] },
      { number: 33, text: "So ging nun Mose vom Pharao zur Stadt hinaus und breitete seine Hände zum HERRN aus; da hörte der Donner* und der Hagel auf, und der Regen ergoss sich nicht mehr auf die Erde*.", footnotes: ["w. die Stimmen", "℘ Kap. 8,8.9"] },
      { number: 34, text: "Als aber der Pharao sah, dass der Regen, der Hagel und der Donner* aufgehört hatten, da sündigte er weiter und verstockte* sein Herz*, er und seine Hofbeamten*.", footnotes: ["w. die Stimmen", "w. machte . . . schwer o. stumpf", "℘ Kap. 7,14", "w. Knechte"] },
      { number: 35, text: "So blieb das Herz des Pharao verstockt*, und er ließ die Söhne Israel nicht ziehen*, wie der HERR durch Mose geredet hatte*.", footnotes: ["w. blieb . . . schwer o. stumpf", "℘ Kap. 3,19; 4,21", "℘ Kap. 7,13"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Danach sprach der HERR zu Mose: Geh zum Pharao hinein, denn ich habe sein Herz und das Herz seiner Hofbeamten* verstockt*, um diese meine Zeichen mitten unter ihnen* zu tun*,", heading: "Achte Plage: Heuschrecken", footnotes: ["w. Knechte", "w. schwer gemacht, o. stumpf gemacht", "so mit LXX, der syr. und aram. Üs.; Mas. T.: in seinem Innern", "℘ Kap. 7,14"] },
      { number: 2, text: "und damit du vor den Ohren deiner Kinder und Kindeskinder* erzählst, wie ich den Ägyptern übel mitgespielt habe* und meine Zeichen, die ich unter ihnen getan habe. So werdet ihr erkennen, dass ich der HERR bin*.", footnotes: ["w. deines Sohnes und des Sohnes deines Sohnes", "℘ 5Mo 4,9; 6,20-22; Ps 44,2; 78,3-7; Joe 1,3", "℘ Kap. 8,6; 14,4.18; Jes 38,19"] },
      { number: 3, text: "Da gingen Mose und Aaron zum Pharao hinein und sagten zu ihm: So spricht der HERR, der Gott der Hebräer: Bis wann willst du dich noch weigern*, dich vor mir zu demütigen?* Lass mein Volk ziehen, damit sie mir dienen*!", footnotes: ["o. Wie lange hast du dich nun schon geweigert", "℘ 1Kö 21,29; 2Chr 33,12; 1Petr 5,6", "℘ Kap. 4,23; 5,1"] },
      { number: 4, text: "Denn wenn du dich weigerst, mein Volk ziehen zu lassen*, siehe, dann will ich morgen Heuschrecken in dein Gebiet bringen.", footnotes: ["℘ Kap. 4,23; 5,1"] },
      { number: 5, text: "Die werden den Boden* des Landes bedecken, so dass man das Land nicht mehr sehen kann. Und sie werden den Rest fressen, was gerettet und euch vom Hagel übrig gelassen worden ist*; auch werden sie alle Bäume fressen, die euch auf dem Feld wachsen.", footnotes: ["w. das Auge; d. h. die Oberfläche; das, was von der Erde sichtbar ist", "℘ Kap. 9,32"] },
      { number: 6, text: "Und sie werden deine Häuser füllen und die Häuser all deiner Hofbeamten* und die Häuser aller Ägypter, wie es deine Väter und die Väter deiner Väter nicht gesehen haben seit dem Tag, an dem sie auf dem Land sesshaft wurden*, bis auf den heutigen Tag*. Darauf wandte er sich um und ging vom Pharao hinaus.", footnotes: ["w. Knechte", "d. h. auf dem fruchtbaren Ackerland beiderseits des Nil; w. seit dem Tag ihres Seins auf der Erde", "℘ Kap. 9,18; Joe 2,9"] },
      { number: 7, text: "Da sagten die Hofbeamten* des Pharao zu ihm: Wie lange noch soll uns dieser Mann zur Falle* sein? Lass die Leute ziehen, damit sie dem HERRN, ihrem Gott, dienen! Erkennst du denn noch nicht, dass Ägypten verloren ist?*", footnotes: ["w. Knechte", "d. i. zu einem Stellholz des Vogelstellers", "℘ 1Sam 5,11"] },
      { number: 8, text: "Darauf wurden Mose und Aaron wieder zum Pharao gebracht, und er sagte zu ihnen: Zieht hin, dient dem HERRN, eurem Gott! Wer alles soll denn mitgehen*?", footnotes: ["w. Wer und wer sind die Gehenden; d. h. welche einzelnen Personen"] },
      { number: 9, text: "Mose antwortete: Mit unsern Jungen und mit unsern Alten wollen wir gehen, mit unsern Söhnen und mit unsern Töchtern, mit unsern Schafen und mit unsern Rindern wollen wir gehen; denn wir haben ein Fest des HERRN zu feiern*.", footnotes: ["℘ Kap. 5,1"] },
      { number: 10, text: "Er aber sagte zu ihnen: So gewiss möge der HERR mit euch sein, wie ich euch mit euren Kindern ziehen lasse! Seht doch selbst, dass ihr Böses vorhabt*!", footnotes: ["w. dass Böses vor eurem Gesicht ist"] },
      { number: 11, text: "So nicht! Zieht doch hin, ihr Männer, und dient dem HERRN! Denn das ist es, was ihr begehrt. Und man jagte sie vom Pharao hinaus." },
      { number: 12, text: "Da sprach der HERR zu Mose: Strecke deine Hand aus über das Land Ägypten wegen der Heuschrecken, damit sie über das Land Ägypten heraufkommen und alles Gewächs des Landes fressen, alles, was der Hagel übrig gelassen hat!*", footnotes: ["℘ Kap. 9,32"] },
      { number: 13, text: "Und Mose streckte seinen Stab über das Land Ägypten aus; da trieb der HERR jenen ganzen Tag und die ganze Nacht einen Ostwind* ins Land; und als es Morgen geworden war, hatte der Ostwind die Heuschrecken herbeigetragen.", footnotes: ["℘ Ps 78,26"] },
      { number: 14, text: "So kamen die Heuschrecken über das ganze Land Ägypten herauf* und ließen sich im ganzen Gebiet Ägyptens* in gewaltiger Menge nieder. Vor ihnen hat es keinen solchen Heuschreckenschwarm wie diesen gegeben, und nach ihnen wird es keinen solchen mehr geben*.", footnotes: ["℘ Offb 9,3", "℘ Ps 78,46; 105,34.35; Spr 30,27; Joe 1,4", "℘ Kap. 9,18; Joe 2,9"] },
      { number: 15, text: "Und sie bedeckten die Oberfläche des ganzen Landes, so dass es finster im Land wurde; und sie fraßen alles Gewächs des Landes und alle Früchte der Bäume, die der Hagel übrig gelassen hatte. So blieb im ganzen Land Ägypten an den Bäumen und Gewächsen des Feldes nichts Grünes übrig*.", footnotes: ["℘ Ps 78,46; 105,34.35; Spr 30,27; Joe 1,4"] },
      { number: 16, text: "Da rief der Pharao schnell Mose und Aaron herbei und sagte: Ich habe gesündigt gegen den HERRN, euren Gott, und gegen euch*!", footnotes: ["℘ Kap. 9,27; 2Sam 24,10"] },
      { number: 17, text: "Und nun vergib* doch meine Sünde nur noch diesmal und betet zum HERRN, eurem Gott*, dass er nur diesen Tod von mir wegnimmt*!", footnotes: ["Eine hebr. Handschr. und die alten Üs. lesen: vergebt", "℘ Kap. 8,4.24", "℘ 4Mo 21,7; 1Sam 15,25"] },
      { number: 18, text: "Darauf ging er von dem Pharao hinaus und betete zum HERRN*.", footnotes: ["℘ Kap. 8,8; 4Mo 11,2"] },
      { number: 19, text: "Und der HERR verwandelte den Ostwind in einen sehr starken Westwind; der hob die Heuschrecken auf und warf sie ins Schilfmeer. Es blieb nicht eine Heuschrecke übrig in dem ganzen Gebiet Ägyptens." },
      { number: 20, text: "Aber der HERR verstockte* das Herz des Pharao*, und er ließ die Söhne Israel nicht ziehen.", footnotes: ["w. machte . . . schwer o. stumpf", "℘ V. 1.27; Kap. 3,19; 4,21"] },
      { number: 21, text: "Da sprach der HERR zu Mose: Strecke deine Hand gegen den Himmel aus! Dann wird eine solche Finsternis über das Land Ägypten kommen, dass man die Finsternis greifen kann*.", heading: "Neunte Plage: Finsternis", footnotes: ["℘ Hi 5,14; Ps 105,28; Jes 8,22; Hes 32,7.8; Offb 8,12; 16,10"] },
      { number: 22, text: "Und Mose streckte seine Hand gegen den Himmel aus: Da entstand im ganzen Land Ägypten eine dichte Finsternis* drei Tage lang.", footnotes: ["℘ Hi 5,14; Ps 105,28; Jes 8,22; Hes 32,7.8; Offb 8,12; 16,10"] },
      { number: 23, text: "Man konnte einander nicht sehen*, und niemand stand von seinem Platz auf drei Tage lang; aber alle Söhne Israel hatten Licht in ihren Wohnsitzen*. —", footnotes: ["w. Und nicht sah ein Mensch seinen Bruder", "℘ Kap. 8,18.19"] },
      { number: 24, text: "Da rief der Pharao Mose herbei und sagte: Zieht hin, dient dem HERRN! Nur eure Schafe und Rinder sollen zurückbleiben; auch eure Kinder mögen mit euch ziehen!" },
      { number: 25, text: "Mose aber sagte: Gäbest du selber in unsere Hände Schlachtopfer und Brandopfer*, damit wir sie dem HERRN, unserem Gott, zubereiten —", footnotes: ["o. Du selbst wirst noch in unsere Hände Schlachtopfer und Brandopfer geben"] },
      { number: 26, text: "unser Vieh zieht dennoch mit uns, nicht eine Klaue darf zurückbleiben*; denn davon werden wir nehmen, um dem HERRN, unserm Gott, zu dienen. Wir wissen* ja nicht, womit wir dem HERRN dienen sollen, bis wir dorthin kommen.", footnotes: ["℘ Kap. 12,32", "o. erkennen"] },
      { number: 27, text: "Aber der HERR verstockte* das Herz des Pharao*, so dass er nicht bereit war, sie ziehen zu lassen.", footnotes: ["w. machte . . . schwer o. stumpf", "℘ V. 20"] },
      { number: 28, text: "Und der Pharao sagte zu ihm: Geh weg von mir! Hüte dich, mir nochmals unter die Augen zu treten*! Denn an dem Tag, an dem du mir wieder unter die Augen trittst*, musst du sterben*.", footnotes: ["w. Nicht sollst du fortfahren, mein Gesicht zu sehen", "w. mein Gesicht siehst", "℘ Kap. 18,4; 2Chr 25,16"] },
      { number: 29, text: "Darauf sagte Mose: Du hast recht geredet, ich werde dir nicht mehr unter die Augen treten*.*", footnotes: ["w. werde nicht mehr dein Gesicht sehen", "℘ Kap. 12,31; Hebr 11,27"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "*Und der HERR sprach zu Mose: Noch eine Plage will ich über den Pharao und über Ägypten bringen; danach wird er euch von hier wegziehen lassen. Wenn er euch endgültig ziehen lässt, wird er euch sogar völlig von hier fortjagen*.", heading: "Androhung der zehnten Plage", footnotes: ["℘ V. 1-8: Kap. 12,29-39", "℘ Kap. 3,20; 6,1"] },
      { number: 2, text: "Rede doch zu den Ohren des Volkes: Jeder soll sich* von seinem Nachbarn und jede von ihrer Nachbarin silberne Schmuckstücke* und goldene Schmuckstücke* erbitten*.", footnotes: ["o. Rede . . . in die Ohren des Volkes, sie sollen sich jeder", "w. Gegenstände, o. Gefäße", "w. Gegenstände, o. Gefäße", "o. fordern\n℘ Kap. 3,21.22"] },
      { number: 3, text: "Und der HERR gab dem Volk Gunst in den Augen der Ägypter*. Der Mann Mose war sogar sehr angesehen* im Land Ägypten, in den Augen der Hofbeamten* des Pharao und in den Augen des Volkes*.", footnotes: ["℘ Kap. 3,21.22", "w. groß", "w. Knechte", "℘ Jos 4,14; Est 9,4"] },
      { number: 4, text: "Mose nun sagte zum Pharao: So spricht der HERR: Um Mitternacht will ich ausgehen und mitten durch Ägypten schreiten*.", footnotes: ["℘ Kap. 12,12; Am 5,17"] },
      { number: 5, text: "Dann wird alle Erstgeburt im Land Ägypten sterben,* von dem Erstgeborenen des Pharao, der auf seinem Thron sitzt, bis zum Erstgeborenen der Sklavin hinter der Handmühle, sowie alle Erstgeburt des Viehs.", footnotes: ["℘ Kap. 4,23"] },
      { number: 6, text: "Da wird es ein großes Jammergeschrei im ganzen Land Ägypten geben, wie es noch keines gegeben hat und es auch keines mehr geben wird*.", footnotes: ["℘ Kap. 9,18; Jes 19,16"] },
      { number: 7, text: "Aber gegen keinen von den Söhnen Israel wird auch nur ein Hund seine Zunge spitzen*, vom Menschen bis zum Vieh, damit ihr erkennt, dass der HERR einen Unterschied macht zwischen den Ägyptern und den Israeliten*.", footnotes: ["℘ Jos 10,21", "℘ Kap. 8,19; Ps 58,12; Mal 3,18"] },
      { number: 8, text: "Dann werden diese deine Hofbeamten* alle zu mir herabkommen, sich vor mir niederbeugen und sagen: Zieh aus, du und das ganze Volk, das in deinem Gefolge ist*! Und danach werde ich ausziehen. — Und er ging in glühendem Zorn vom Pharao hinaus.", footnotes: ["w. Knechte", "w. das bei deinen Füßen ist"] },
      { number: 9, text: "Der HERR hatte nämlich zu Mose gesagt: Der Pharao wird nicht auf euch hören*, damit meine Wunder* im Land Ägypten zahlreich werden*.", footnotes: ["o. Da sagte der HERR zu Mose: Der Pharao hört nicht auf euch", "o. Wahrzeichen", "℘ Kap. 3,19.20"] },
      { number: 10, text: "Und Mose und Aaron haben alle diese Wunder* vor dem Pharao getan. Aber der HERR hatte das Herz des Pharao verstockt, so dass er die Söhne Israel nicht aus seinem Land ziehen ließ.*", footnotes: ["o. Wahrzeichen", "℘ Kap. 4,21"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und der HERR sprach zu Mose und Aaron im Land Ägypten:", heading: "Passah und Fest der ungesäuerten Brote" },
      { number: 2, text: "Dieser Monat soll für euch der Anfangsmonat* sein*, er sei euch der erste von den Monaten des Jahres!", footnotes: ["w. das Haupt der Monate", "℘ Kap. 13,4; 40,17"] },
      { number: 3, text: "Redet zur ganzen Gemeinde Israel und sagt: Am Zehnten dieses Monats*, da nehmt euch ein jeder ein Lamm* für ein Vaterhaus, je ein Lamm für das Haus!", footnotes: ["℘ Hes 40,1", "w. ein Stück Kleinvieh"] },
      { number: 4, text: "Wenn aber das Haus für ein Lamm* nicht zahlreich genug ist, dann nehme er es mit seinem Nachbarn, der seinem Haus am nächsten wohnt, nach der Zahl der Seelen; nach dem Maß dessen, was jeder isst, sollt ihr ihn auf das Lamm anrechnen.", footnotes: ["w. ein Stück Kleinvieh"] },
      { number: 5, text: "Ein Lamm ohne Fehler*, ein männliches, einjähriges, soll es für euch sein; von den Schafen oder von den Ziegen sollt ihr es nehmen.", footnotes: ["w. Ein vollständiges Stück Kleinvieh\n℘ 3Mo 1,3.10; 1Petr 1,19"] },
      { number: 6, text: "Und ihr sollt es bis zum vierzehnten Tag dieses Monats aufbewahren. Dann soll es die ganze Versammlung der Gemeinde Israel zwischen den zwei Abenden* schlachten*.", footnotes: ["d. h. entweder zwischen Sonnenuntergang und völliger Nacht oder zwischen Niedergang (15 Uhr) und Untergang der Sonne", "℘ Kap. 29,39; 2Chr 35,1; Esr 6,19"] },
      { number: 7, text: "Und sie sollen von dem Blut nehmen und es an die beiden Türpfosten und die Oberschwelle streichen an den Häusern, in denen sie es essen*.", footnotes: ["℘ V. 13.22"] },
      { number: 8, text: "Das Fleisch aber sollen sie noch in derselben Nacht essen, am Feuer gebraten, und dazu ungesäuertes Brot*; mit bitteren Kräutern* sollen sie es essen.", footnotes: ["℘ Kap. 13,3", "℘ 4Mo 9,11"] },
      { number: 9, text: "Ihr dürft nichts davon roh oder etwa im Wasser gekocht essen, sondern am Feuer gebraten* sollt ihr es essen: seinen Kopf samt seinen Unterschenkeln und Eingeweiden.", footnotes: ["℘ 2Chr 35,13"] },
      { number: 10, text: "Und ihr dürft nichts davon bis zum Morgen übrig lassen*! Was aber davon bis zum Morgen übrig bleibt, sollt ihr mit Feuer verbrennen*.", footnotes: ["℘ Kap. 16,19; 23,18; 34,25; 3Mo 7,15", "℘ Kap. 29,34; 3Mo 19,6"] },
      { number: 11, text: "So aber sollt ihr es essen: eure Lenden gegürtet*, eure Schuhe an euren Füßen und euren Stab in eurer Hand; und ihr sollt es essen in Hast. Ein Passah* für den HERRN ist es*.", footnotes: ["℘ Lk 12,35", "Dieses Wort wird normalerweise von einem Zeitwort abgeleitet, das eigentlich »lahm sein, hinken« bedeutet, in V. 13 und sonst im AT aber als »vorübergehen, überspringen« verstanden wird; daher vielleicht: Überspringung, o. Vorübergehen", "℘ 3Mo 23,5; 4Mo 9,1-5; 28,16; 5Mo 16,1-7; Jos 5,10; 2Kö 23,21; Hes 45,21; Mt 26,17; Joh 2,13"] },
      { number: 12, text: "Und ich werde in dieser Nacht durch das Land Ägypten gehen und alle Erstgeburt im Land Ägypten erschlagen vom Menschen bis zum Vieh*. Auch an allen Göttern Ägyptens werde ich ein Strafgericht vollstrecken*, ich, der HERR*.", footnotes: ["℘ Kap. 9,6; 11,4.5", "℘ 4Mo 33,4", "℘ Ps 95,3"] },
      { number: 13, text: "Aber das Blut soll für euch zum Zeichen an den Häusern werden, in denen ihr seid*. Und wenn ich das Blut sehe, dann werde ich an euch vorübergehen: So wird keine Plage, die Verderben bringt*, unter euch sein, wenn ich das Land Ägypten schlage*.", footnotes: ["℘ Jos 2,18", "w. kein Stoß zum Verderben o. eines Verderbers", "℘ V. 23; Hebr 11,28"] },
      { number: 14, text: "Und dieser Tag soll euch eine Erinnerung sein*, und ihr sollt ihn feiern als Fest für den HERRN*. Als ewige Ordnung* für all eure Generationen sollt ihr ihn feiern.", footnotes: ["℘ Jos 4,7", "℘ Lk 22,19", "℘ Kap. 27,21"] },
      { number: 15, text: "*Sieben Tage sollt ihr ungesäuertes Brot essen*; ja, gleich am ersten Tag sollt ihr den Sauerteig aus euren Häusern wegtun*; denn jeder, der Gesäuertes isst, diese Seele* soll aus Israel ausgerottet werden* — das gilt vom ersten Tag bis zum siebten Tag.", footnotes: ["℘ V. 15-20: Kap. 13,3-10; 23,15; 34,18; 3Mo 23,6-8; 4Mo 28,17-25; 5Mo 16,3.4.8", "℘ 2Chr 30,21; Apg 12,3; 20,6", "℘ 1Kor 5,7.8", "o. dieses Leben", "℘ Kap. 30,33.38"] },
      { number: 16, text: "Und am ersten Tag sollt ihr eine heilige Versammlung* halten und ebenso am siebten Tag eine heilige Versammlung. An diesen Tagen darf keinerlei Arbeit getan werden*; nur was von jeder Seele gegessen wird, das allein darf von euch zubereitet werden.", footnotes: ["w. Einberufung", "℘ 4Mo 28,26; Lk 23,56"] },
      { number: 17, text: "So haltet denn das Fest der ungesäuerten Brote! Denn an ebendiesem Tag habe ich eure Heerscharen aus dem Land Ägypten herausgeführt. Darum sollt ihr diesen Tag halten als ewige Ordnung für all eure Generationen." },
      { number: 18, text: "Im ersten Monat, am 14. Tag des Monats, am Abend, sollt ihr ungesäuertes Brot essen bis zum 21. Tag des Monats, am Abend." },
      { number: 19, text: "Sieben Tage darf kein Sauerteig in euren Häusern gefunden werden; denn jeder, der Gesäuertes isst, diese Seele* soll aus der Gemeinde Israel ausgerottet werden*, er sei ein Fremder oder Einheimischer des Landes.", footnotes: ["o. dieses Leben", "℘ Kap. 30,33.38"] },
      { number: 20, text: "Nichts Gesäuertes dürft ihr essen; in all euren Wohnsitzen sollt ihr ungesäuertes Brot essen!" },
      { number: 21, text: "Und Mose berief alle Ältesten Israels und sagte zu ihnen: Macht euch daran* und nehmt euch nach der Größe eurer Sippen Schafe und schlachtet das Passah*.", footnotes: ["o. zieht hin; o. erwerbt; w. zieht", "℘ 2Chr 35,6; Mt 26,18.19"] },
      { number: 22, text: "Dann nehmt ein Büschel Ysop und taucht es in das Blut im Becken und streicht etwas von dem Blut, das in dem Becken ist, an die Oberschwelle und an die beiden Türpfosten. Ihr aber — von euch darf bis zum Morgen keiner zur Tür seines Hauses hinausgehen*.", footnotes: ["℘ Jes 26,20"] },
      { number: 23, text: "Und der HERR wird durch das Land gehen, um die Ägypter zu schlagen*. Sieht er dann das Blut an der Oberschwelle und an den beiden Türpfosten, wird der HERR an der Tür vorübergehen und wird dem Verderber nicht erlauben, in eure Häuser zu kommen, euch zu schlagen*.", footnotes: ["℘ V. 13; Hi 14,13; Hes 9,4.6", "℘ Kap. 30,33.38"] },
      { number: 24, text: "Darum sollt ihr dieses Wort ewig halten als Ordnung für dich und deine Kinder." },
      { number: 25, text: "Und es soll geschehen, wenn ihr in das Land kommt, das euch der HERR geben wird, wie er geredet hat, dann sollt ihr diesen Dienst ausüben." },
      { number: 26, text: "Und es soll geschehen, wenn euch eure Kinder fragen: Was bedeutet dieser Dienst für euch*?,", footnotes: ["℘ Kap. 13,14; 5Mo 6,20; Jos 4,6.21"] },
      { number: 27, text: "dann sollt ihr sagen: Es ist ein Passahopfer für den HERRN, der an den Häusern der Söhne Israel in Ägypten vorüberging, als er die Ägypter schlug, unsere Häuser aber rettete*. Da warf sich das Volk nieder und betete an*.", footnotes: ["℘ Kap. 13,8; Ps 78,5-7", "℘ Kap. 4,31"] },
      { number: 28, text: "Und die Söhne Israel gingen hin und machten es, wie der HERR Mose und Aaron geboten hatte, so machten sie es.*", footnotes: ["℘ V. 35.50; Kap. 7,6; 14,4; 36,1; 39,32.42.43; 3Mo 24,23; 4Mo 1,54; 5,4; 5Mo 34,9; Jos 14,5; 2Sam 5,25; 1Kö 17,5"] },
      { number: 29, text: "*Und es geschah um Mitternacht, da erschlug der HERR alle Erstgeburt im Land Ägypten* vom Erstgeborenen des Pharao, der auf seinem Thron saß, bis zum Erstgeborenen des Gefangenen im Kerker, auch alle Erstgeburt des Viehs*.", heading: "Zehnte Plage: Tod der Erstgeburt", footnotes: ["℘ V. 29-39: Kap. 11,1-8", "℘ Hi 34,20", "℘ Kap. 4,23; 1Mo 15,14; 4Mo 3,13; 8,17; Ps 78,51; 105,36; Jes 41,11"] },
      { number: 30, text: "Da stand der Pharao nachts auf, er und alle seine Hofbeamten* und alle Ägypter, und es entstand ein großes Jammergeschrei in Ägypten, denn es gab kein Haus, in dem nicht ein Toter war.", footnotes: ["w. Knechte"] },
      { number: 31, text: "Und er rief Mose und Aaron nachts herbei* und sagte: Macht euch auf, zieht weg aus der Mitte meines Volkes, sowohl ihr als auch die Söhne Israel*, und geht hin, dient dem HERRN, wie ihr gesagt habt!", footnotes: ["℘ Kap. 10,29", "℘ Kap. 3,20; 6,1; 1Sam 6,6"] },
      { number: 32, text: "Auch eure Schafe und Rinder nehmt mit, wie ihr gesagt habt*, und geht hin und segnet auch mich*!", footnotes: ["℘ Kap. 10,9.26", "℘ Esr 6,10"] },
      { number: 33, text: "Und die Ägypter bedrängten das Volk, um sie möglichst schnell aus dem Land schicken zu können, denn sie sagten sich: Wir alle sind sonst des Todes*!", footnotes: ["℘ Kap. 6,1; Ps 105,38"] },
      { number: 34, text: "Das Volk nun hob seinen Teig auf, ehe er gesäuert war; ihre Backschüsseln trugen sie, in ihre Kleidung* gewickelt, auf ihren Schultern.", heading: "Israels Auszug aus Ägypten — Ordnung des Passah", footnotes: ["s. Anm. zu Kap. 3,22"] },
      { number: 35, text: "Und die Söhne Israel hatten nach dem Wort des Mose getan und sich von den Ägyptern silberne Schmuckstücke* und goldene Schmuckstücke und Kleidung erbeten*.", footnotes: ["w. Gegenstände, o. Gefäße", "o. gefordert\n℘ Kap. 3,21.22; Esr 1,6; Ps 105,37"] },
      { number: 36, text: "Dazu hatte der HERR dem Volk in den Augen der Ägypter Gunst gegeben, so dass sie auf ihre Bitte eingegangen waren.* So plünderten sie die Ägypter aus*.", footnotes: ["o. Die Söhne Israel taten nach dem Wort des Mose und erbaten sich . . . Kleidung. 36 Dazu gab der HERR dem Volk Gunst . . ., so dass sie auf ihre Bitte eingingen.", "℘ Kap. 3,21.22; Esr 1,6; Ps 105,37"] },
      { number: 37, text: "Nun brachen die Söhne Israel auf und zogen von Ramses* nach Sukkot*, etwa 600 000 Mann* zu Fuß, die Männer ohne die Kinder.", footnotes: ["℘ 1Mo 47,11", "℘ 4Mo 33,3.5", "℘ Kap. 38,26; 4Mo 1,46"] },
      { number: 38, text: "Es zog aber auch viel Mischvolk mit ihnen hinauf*, dazu Schafe und Rinder, sehr viel Vieh.", footnotes: ["℘ 3Mo 24,10; 4Mo 11,4; Neh 13,3"] },
      { number: 39, text: "Und sie backten den Teig, den sie aus Ägypten gebracht hatten, zu ungesäuerten Brotfladen; denn er war nicht gesäuert, weil sie aus Ägypten weggetrieben worden waren und nicht länger hatten warten können; so hatten sie sich auch keine Wegzehrung bereitet." },
      { number: 40, text: "Die Zeit des Aufenthaltes der Söhne Israel aber, die sie in Ägypten zugebracht hatten, betrug 430 Jahre*.", footnotes: ["℘ 1Mo 15,13; Gal 3,17"] },
      { number: 41, text: "Und es geschah am Ende der 430 Jahre, ja, es geschah an ebendiesem Tag, dass alle Heerscharen des HERRN aus dem Land Ägypten auszogen*.", footnotes: ["℘ Kap. 6,26; 1Mo 50,24; 3Mo 23,43; 4Mo 23,22; 33,1; 5Mo 4,37; 16,1; Jos 24,5; 1Kö 6,1; 2Chr 14,12; Ps 114,1; Apg 7,6.7; 13,17; Hebr 11,27; Jud 5"] },
      { number: 42, text: "Eine Nacht des Wachens war dies für den HERRN, damit er sie aus dem Land Ägypten herausführen konnte*; das ist diese dem HERRN geweihte Nacht, ein Wachen für alle Söhne Israel in all ihren Generationen.", footnotes: ["℘ Kap. 13,3.14.16; Ps 136,11"] },
      { number: 43, text: "Und der HERR sprach zu Mose und Aaron: Dies ist die Ordnung des Passah: Kein Fremder* soll davon essen*.", footnotes: ["w. Sohn der Fremde", "℘ 3Mo 22,10"] },
      { number: 44, text: "Jeder um Geld gekaufte Sklave eines Mannes aber — wenn du ihn beschneidest, dann darf er davon essen*.", footnotes: ["℘ 1Mo 17,12"] },
      { number: 45, text: "Ein Beisasse* oder Lohnarbeiter darf nicht davon essen.", footnotes: ["d. i. ein Ansässiger ohne Bürgerrecht"] },
      { number: 46, text: "In einem Haus soll es gegessen werden; du sollst nichts von dem Fleisch aus dem Haus hinausbringen, und ihr sollt kein Bein an ihm zerbrechen*.", footnotes: ["℘ 4Mo 9,12; Ps 34,21; Joh 19,36"] },
      { number: 47, text: "Die ganze Gemeinde Israel soll es feiern." },
      { number: 48, text: "Wenn sich aber ein Fremdling bei dir aufhält und dem HERRN das Passah feiern will, so soll bei ihm alles Männliche beschnitten werden, und dann komme er herbei, um es zu feiern; und er soll wie ein Einheimischer des Landes gelten. Es darf jedoch kein Unbeschnittener davon essen*.", footnotes: ["℘ Hes 44,9"] },
      { number: 49, text: "Ein Gesetz soll gelten für den Einheimischen und für den Fremdling, der sich mitten unter euch aufhält*.", footnotes: ["℘ 3Mo 19,34; 24,22; 4Mo 9,14"] },
      { number: 50, text: "Darauf machten es alle Söhne Israel, wie der HERR Mose und Aaron geboten hatte; so machten sie es.*", footnotes: ["℘ 4Mo 8,20.22; 9,5; 36,10"] },
      { number: 51, text: "Und es geschah an ebendiesem Tag, da führte der HERR die Söhne Israel, nach ihren Heerscharen geordnet, aus dem Land Ägypten heraus*.", footnotes: ["℘ Kap. 6,26; 1Mo 50,24; 3Mo 23,43; 4Mo 23,22; 33,1; 5Mo 4,37; 16,1; Jos 24,5; 1Kö 6,1; 2Chr 14,12; Ps 114,1; Apg 7,6.7; 13,17; Hebr 11,27; Jud 5"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Danach redete der HERR zu Mose und sprach:", heading: "Fest der ungesäuerten Brote — Heiligung der Erstgeburt" },
      { number: 2, text: "Heilige mir alle Erstgeburt! Alles bei den Söhnen Israel, was zuerst den Mutterschoß durchbricht unter den Menschen und unter dem Vieh, mir gehört es*.", footnotes: ["℘ Kap. 22,28.29; 34,19; 3Mo 27,26; 4Mo 3,13; 5Mo 15,19; Neh 10,37; Lk 2,23"] },
      { number: 3, text: "*Und Mose sagte zum Volk: Gedenkt dieses Tages, an dem ihr aus Ägypten gezogen seid, aus dem Sklavenhaus*! Denn mit starker Hand hat euch der HERR von dort herausgeführt*. Darum soll kein gesäuertes Brot gegessen werden*.", footnotes: ["℘ V. 3-10: Kap. 12,15-20", "℘ Kap. 6,7; 20,2; 5Mo 5,6; 6,12; Jos 24,17; Ri 6,8; 1Chr 16,12; Jer 34,13", "℘ Kap. 6,1.6; 12,41.42; 5Mo 5,15; 6,21; Ri 2,12; Neh 1,10; Ps 136,11.12; Dan 9,15", "℘ Kap. 12,8; Kap. 12,2; 23,15; 34,18; 1Mo 15,16; 5Mo 16,1-3"] },
      { number: 4, text: "Heute zieht ihr aus im Monat Abib*.", footnotes: ["d. h. Ährenmonat\n℘ Kap. 6,4"] },
      { number: 5, text: "Und es soll geschehen, wenn der HERR dich in das Land der Kanaaniter, Hetiter, Amoriter, Hewiter und Jebusiter bringt, das dir zu geben er deinen Vätern geschworen hat, ein Land, das von Milch und Honig überfließt*, dann sollst du diesen Dienst in diesem Monat ausüben.", footnotes: ["℘ Kap. 3,8.17"] },
      { number: 6, text: "Sieben Tage sollst du ungesäuertes Brot essen, und am siebten Tag ist ein Fest für den HERRN." },
      { number: 7, text: "Während der sieben Tage soll man ungesäuertes Brot essen, und kein gesäuertes Brot soll bei dir gesehen werden, noch soll Sauerteig in all deinen Grenzen bei dir gesehen werden*.", footnotes: ["℘ 5Mo 16,4; Jos 5,11"] },
      { number: 8, text: "Und du sollst dies deinem Sohn an jenem Tag so erklären*: Es geschieht um deswillen, was der HERR für mich getan hat, als ich aus Ägypten zog*.", footnotes: ["w. vorbringen, o. mitteilen, o. erzählen", "℘ Kap. 12,26.27"] },
      { number: 9, text: "Und es sei dir ein Zeichen auf deiner Hand und ein Zeichen der Erinnerung zwischen deinen Augen*, damit das Gesetz des HERRN in deinem Mund sei; denn mit starker Hand hat dich der HERR aus Ägypten herausgeführt*.", footnotes: ["℘ 5Mo 6,8; 11,18; Spr 6,21; Mt 23,5", "℘ Kap. 6,1.6; 12,41.42; 5Mo 5,15; 6,21; Ri 2,12; Neh 1,10; Ps 136,11.12; Dan 9,15"] },
      { number: 10, text: "So sollst du denn diese Ordnung zu ihrer bestimmten Zeit von Jahr zu Jahr* halten.", footnotes: ["w. von Tagen zu Tagen"] },
      { number: 11, text: "Und es soll geschehen, wenn dich der HERR in das Land der Kanaaniter bringt, wie er dir und deinen Vätern geschworen hat, und es dir gibt," },
      { number: 12, text: "dann sollst du dem HERRN alles darbringen, was zuerst den Mutterschoß durchbricht. Auch jeder erste Wurf des Viehs, der dir zuteil wird, gehört, soweit er männlich ist, dem HERRN*.", footnotes: ["℘ Kap. 22,28.29; 34,19; 3Mo 27,26; 4Mo 3,13; 5Mo 15,19; Neh 10,37; Lk 2,23"] },
      { number: 13, text: "Jede Erstgeburt vom Esel aber sollst du mit einem Lamm auslösen*! Wenn du sie jedoch nicht auslösen willst, dann brich ihr das Genick! Auch alle menschliche Erstgeburt unter deinen Söhnen sollst du auslösen.", footnotes: ["℘ Kap. 34,20; 4Mo 18,15"] },
      { number: 14, text: "Und es soll geschehen, wenn dich künftig dein Sohn fragt: Was bedeutet das*?, dann sollst du zu ihm sagen: Mit starker Hand hat uns der HERR aus Ägypten herausgeführt*, aus dem Sklavenhaus*.", footnotes: ["℘ Kap. 12,26", "℘ Kap. 6,7; 20,2; 5Mo 5,6; 6,12; Jos 24,17; Ri 6,8; 1Chr 16,12; Jer 34,13", "℘ Kap. 6,7; 20,2; 5Mo 5,6; 6,12; Jos 24,17; Ri 6,8; 1Chr 16,12; Jer 34,13"] },
      { number: 15, text: "Denn es geschah, als der Pharao sich hartnäckig weigerte, uns ziehen zu lassen*, da brachte der HERR alle Erstgeburt im Land Ägypten um, vom Erstgeborenen des Menschen bis zum Erstgeborenen des Viehs*. Darum opfere ich dem HERRN* alles, was zuerst den Mutterschoß durchbricht, soweit es männlich ist; aber jeden Erstgeborenen meiner Söhne löse ich aus*.", footnotes: ["℘ Kap. 3,19", "℘ Kap. 4,23", "w. schlachte ich dem HERRN zum Opfer", "℘ Kap. 34,20; 4Mo 18,15"] },
      { number: 16, text: "Das sei dir ein Zeichen auf deiner Hand und ein Merkzeichen zwischen deinen Augen*, denn mit starker Hand hat uns der HERR aus Ägypten herausgeführt*.", footnotes: ["℘ Kap. 6,1.6; 12,41.42; 5Mo 5,15; 6,21; Ri 2,12; Neh 1,10; Ps 136,11.12; Dan 9,15", "℘ Kap. 6,1.6; 12,41.42; 5Mo 5,15; 6,21; Ri 2,12; Neh 1,10; Ps 136,11.12; Dan 9,15"] },
      { number: 17, text: "Und es geschah, als der Pharao das Volk ziehen ließ, führte Gott sie nicht den Weg durch das Land* der Philister, obwohl er der nächste war. Denn Gott sagte: Damit es das Volk nicht gereut, wenn sie Kampf vor sich sehen*, und sie nicht nach Ägypten zurückkehren*.", heading: "Israels Zug zum Schilfmeer — Wolken- und Feuersäule", footnotes: ["o. zum Land; w. den Weg des Landes", "℘ Kap. 14,10-12", "℘ 5Mo 17,16; 28,68"] },
      { number: 18, text: "Daher ließ Gott das Volk einen Umweg machen, den Wüstenweg zum Schilfmeer*. Und die Söhne Israel zogen kampfgerüstet aus dem Land Ägypten herauf*.", footnotes: ["℘ Kap. 14,2; Ps 68,8", "℘ 1Mo 50,25"] },
      { number: 19, text: "Mose aber nahm die Gebeine Josefs mit sich. Denn dieser hatte die Söhne Israel ausdrücklich schwören lassen: Gott wird euch gewiss heimsuchen. Führt dann meine Gebeine mit euch von hier hinauf!*", footnotes: ["℘ 1Mo 50,25; Jos 24,32"] },
      { number: 20, text: "Und sie brachen auf von Sukkot und lagerten sich in Etam, am Rande der Wüste*.", footnotes: ["℘ 4Mo 33,6"] },
      { number: 21, text: "Der HERR aber zog vor ihnen her*, bei Tag in einer Wolkensäule*, um sie auf dem Weg zu führen, und bei Nacht in einer Feuersäule, um ihnen zu leuchten*, damit sie Tag und Nacht wandern könnten.", footnotes: ["℘ Kap. 32,1", "℘ 1Kor 10,1", "℘ 4Mo 9,15-23; 5Mo 1,33; Ps 78,14; 105,39; Jes 4,5"] },
      { number: 22, text: "Weder wich die Wolkensäule vor dem Volk bei Tag noch die Feuersäule bei Nacht*.", footnotes: ["℘ Kap. 40,38"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und sprach:", heading: "Israels Zug durch das Schilfmeer — Untergang der Ägypter" },
      { number: 2, text: "Befiehl den Söhnen Israel, sich zu wenden* und vor Pi-Hahirot zu lagern*, zwischen Migdol* und dem Meer. Vor Baal-Zefon, diesem gegenüber, sollt ihr euch am Meer lagern*!", footnotes: ["℘ Kap. 13,18", "℘ Jos 24,6", "℘ Jer 46,14", "℘ 4Mo 33,7"] },
      { number: 3, text: "Der Pharao aber wird von den Söhnen Israel denken: Sie irren ziellos im Land umher, die Wüste hat sie eingeschlossen." },
      { number: 4, text: "Dann will ich das Herz des Pharao verstocken*, so dass er ihnen nachjagt. Darauf will ich mich am Pharao und an seiner ganzen Heeresmacht verherrlichen*, und die Ägypter sollen erkennen, dass ich der HERR bin*. Und sie machten es so*.", footnotes: ["℘ Kap. 4,21; Jos 11,20; Ri 4,7", "℘ Hes 28,22", "℘ Kap. 6,7; 10,2; Hes 38,16.23", "℘ Kap. 12,28.35.50"] },
      { number: 5, text: "Als nun dem König von Ägypten berichtet wurde, dass das Volk geflohen sei, wandte sich das Herz des Pharao und seiner Hofbeamten* gegen das Volk, und sie sagten: Was haben wir da getan, dass wir Israel aus unserem Dienst haben ziehen lassen!", footnotes: ["w. Knechte"] },
      { number: 6, text: "So ließ er denn seine Streitwagen anspannen und nahm sein Kriegsvolk mit sich." },
      { number: 7, text: "Er nahm sechshundert auserlesene Streitwagen und alle übrigen Streitwagen Ägyptens und Wagenkämpfer* auf ihnen allen*.", footnotes: ["Das war vielleicht ein dritter Mann, der den Schild hielt.", "℘ Kap. 15,4"] },
      { number: 8, text: "Und der HERR verstockte das Herz des Pharao, des Königs von Ägypten*, so dass er den Söhnen Israel nachjagte, während die Söhne Israel mit erhobener Hand auszogen*.", footnotes: ["℘ Kap. 4,21; Jos 11,20; Ri 4,7", "℘ 3Mo 26,13; 4Mo 33,3; Ps 105,43"] },
      { number: 9, text: "So jagten ihnen denn die Ägypter nach, alle Pferde und Streitwagen* des Pharao, auch seine Reiter und seine Heeresmacht, und erreichten sie, als sie sich am Meer gelagert hatten*, bei Pi-Hahirot, vor Baal-Zefon*.", footnotes: ["o. alle Pferde der Streitwagen", "℘ 4Mo 33,7", "℘ 4Mo 33,7"] },
      { number: 10, text: "Als nun der Pharao sich näherte, erhoben die Söhne Israel ihre Augen, und siehe, die Ägypter zogen hinter ihnen her. Da fürchteten sich die Söhne Israel sehr und schrien zum HERRN*.", footnotes: ["℘ Jos 24,6.7; Neh 9,9"] },
      { number: 11, text: "Und sie sagten zu Mose: Hast du uns etwa deshalb weggeführt, damit wir in der Wüste sterben, weil es in Ägypten keine Gräber gab? Warum hast du uns das angetan, dass du uns aus Ägypten herausgeführt hast*?", footnotes: ["℘ Kap. 16,3; 17,3; 4Mo 14,2"] },
      { number: 12, text: "Ist dies nicht das Wort, das wir schon in Ägypten zu dir geredet haben: Lass ab von uns, wir wollen den Ägyptern dienen? Es wäre nämlich besser für uns, den Ägyptern zu dienen, als in der Wüste zu sterben*.", footnotes: ["℘ Ps 106,7"] },
      { number: 13, text: "Mose aber antwortete dem Volk: Fürchtet euch nicht*! Steht und seht die Rettung des HERRN, die er euch heute bringen wird*! Denn die Ägypter, die ihr heute seht, die werdet ihr weiterhin in Ewigkeit nicht mehr sehen*.", footnotes: ["℘ 4Mo 14,9; 5Mo 20,3; 2Kö 6,16; Ps 78,53; Jes 41,10-14", "℘ Ps 68,21; Hos 1,7", "℘ Ps 91,8"] },
      { number: 14, text: "Der HERR wird für euch kämpfen*, ihr aber werdet still sein*.", footnotes: ["℘ Kap. 15,3; 5Mo 1,30; 3,22; Jos 10,14.42; 1Sam 4,7.8; 2Chr 20,29; Neh 4,14; 9,11; Ps 35,1; Jes 31,4", "o. untätig bleiben\n℘ 2Chr 20,15.17; Jes 30,15; Kla 3,26"] },
      { number: 15, text: "Und der HERR sprach zu Mose: Was schreist du zu mir*? Befiehl den Söhnen Israel, dass sie aufbrechen!", footnotes: ["℘ Jos 7,10"] },
      { number: 16, text: "Du aber erhebe deinen Stab und strecke deine Hand über das Meer aus und spalte es, damit die Söhne Israel auf trockenem Land mitten in das Meer hineingehen!" },
      { number: 17, text: "Ich jedoch, siehe, ich will das Herz der Ägypter verstocken*, so dass sie hinter ihnen herkommen. Und ich will mich verherrlichen* am Pharao und an seiner ganzen Heeresmacht, an seinen Streitwagen und Reitern*.", footnotes: ["℘ Hes 28,22", "℘ Hes 28,22", "o. Pferde(n). — Das hebr. Wort kann beides bedeuten."] },
      { number: 18, text: "Dann sollen die Ägypter erkennen, dass ich der HERR bin*, wenn ich mich am Pharao, an seinen Wagen und Männern verherrlicht habe*.", footnotes: ["℘ Hes 28,22", "℘ Hes 28,22"] },
      { number: 19, text: "Und der Engel Gottes, der vor dem Heer Israels herzog, brach auf und trat hinter sie; und die Wolkensäule vor ihnen brach auf und stellte sich hinter sie*.", footnotes: ["℘ Jes 52,12; Mi 2,13"] },
      { number: 20, text: "So kam sie zwischen das Heer der Ägypter und das Heer Israels, und sie wurde dort Gewölk und Finsternis* und erleuchtete hier die Nacht, so kam jenes Heer diesem die ganze Nacht nicht näher.", footnotes: ["℘ Jos 24,7"] },
      { number: 21, text: "Und Mose streckte seine Hand über das Meer aus, und der HERR ließ das Meer die ganze Nacht durch einen starken Ostwind zurückweichen* und machte so das Meer zum trockenen Land, und das Wasser teilte sich*.", footnotes: ["w. gehen\n℘ Hi 38,24; Ps 148,8", "℘ Jos 2,10; Ps 74,13; 114,3.5; Jes 44,27"] },
      { number: 22, text: "Dann gingen die Söhne Israel auf trockenem Land mitten in das Meer hinein*, und das Wasser war ihnen eine Mauer zur Rechten und zur Linken*.", footnotes: ["℘ Kap. 15,19; 2Kö 2,8.14; Neh 9,11; Ps 66,6; 106,9; 136,13.15; Jes 51,10; Apg 7,36", "℘ Kap. 15,8; Jos 3,16.17; Ps 78,13; Jes 11,15.16; 1Kor 10,1"] },
      { number: 23, text: "Die Ägypter aber jagten ihnen nach und kamen hinter ihnen her, alle Pferde des Pharao, seine Streitwagen und Reiter*, mitten ins Meer hinein.", footnotes: ["o. Pferde(n). — Das hebr. Wort kann beides bedeuten."] },
      { number: 24, text: "Und es geschah: In der Zeit der Morgenwache, da schaute der HERR in der Feuer- und Wolkensäule auf das Heer der Ägypter herab* und brachte das Heer der Ägypter in Verwirrung.", footnotes: ["℘ Am 9,4.8"] },
      { number: 25, text: "Dann stieß er die Räder von ihren* Wagen ab* und ließ sie nur mühsam vorankommen*. Da sagten die Ägypter: Lasst uns vor Israel fliehen, denn der HERR kämpft für sie* gegen die Ägypter!", footnotes: ["w. seinen", "Eine hebr. Handschr. und die griech. und syr. Üs. lesen: Dann hemmte er die Räder ihrer Wagen", "w. ließ sie fahren mit Schwierigkeit", "℘ Kap. 15,3; 5Mo 1,30; 3,22; Jos 10,14.42; 1Sam 4,7.8; 2Chr 20,29; Neh 4,14; 9,11; Ps 35,1; Jes 31,4"] },
      { number: 26, text: "Der HERR aber sprach zu Mose: Strecke deine Hand über das Meer aus, damit das Wasser auf die Ägypter, auf ihre Wagen und über ihre Reiter* zurückkehrt!", footnotes: ["o. Pferde. — Das hebr. Wort kann beides bedeuten."] },
      { number: 27, text: "Da streckte Mose seine Hand über das Meer aus, und das Meer kehrte beim Anbruch des Morgens zu seiner Strömung* zurück. Und die Ägypter flohen ihm entgegen. Der HERR aber trieb* die Ägypter mitten ins Meer*.", footnotes: ["nach der aram. Üs.: mit all seiner Gewalt", "w. schüttelte . . . ab", "℘ Jos 24,7"] },
      { number: 28, text: "So kehrte das Wasser zurück und bedeckte die Wagen und Reiter* der ganzen Heeresmacht des Pharao, die ihnen ins Meer nachgekommen waren; es blieb auch nicht einer von ihnen übrig*.", footnotes: ["o. Pferde. — Das hebr. Wort kann beides bedeuten.", "℘ 5Mo 11,4; 2Chr 20,24; Ps 78,53; 106,22; Hebr 11,29"] },
      { number: 29, text: "Die Söhne Israel aber waren auf trockenem Land mitten durch das Meer gegangen*, und das Wasser war ihnen eine Mauer zur Rechten und zur Linken gewesen*.", footnotes: ["℘ Kap. 15,8; Jos 3,16.17; Ps 78,13; Jes 11,15.16; 1Kor 10,1", "℘ Kap. 15,8; Jos 3,16.17; Ps 78,13; Jes 11,15.16; 1Kor 10,1"] },
      { number: 30, text: "So rettete der HERR an jenem Tag* Israel aus der Hand der Ägypter*, und Israel sah die Ägypter tot am Ufer des Meeres liegen*.", footnotes: ["℘ 1Sam 14,23", "℘ Ri 10,11; Hos 1,7", "℘ Ps 91,8"] },
      { number: 31, text: "Als nun Israel die große Macht* sah, die der HERR an den Ägyptern ausgeübt hatte*, da fürchtete das Volk den HERRN*, und sie glaubten an den HERRN und an seinen Knecht Mose*.", footnotes: ["w. Hand", "℘ Jos 24,7", "℘ Jos 4,24", "℘ Kap. 4,31; 19,9; Jos 4,14; 1Sam 12,18"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Damals sangen Mose und die Söhne Israel dem HERRN dieses Lied*. Sie sagten*: Singen will ich dem HERRN, denn hoch erhaben ist er*; Pferd und Wagen warf er ins Meer*.", heading: "Das Schilfmeerlied", footnotes: ["℘ 4Mo 21,17; 2Sam 22,1; Hos 2,17; Offb 15,3", "℘ Ps 106,12; Ri 5,1.3", "o. hoch hat er sich erhoben", "℘ V. 21; Kap. 14,26.27; Ps 76,7"] },
      { number: 2, text: "Meine Stärke* und mein Loblied* ist Jah*, denn er ist mir zur Rettung geworden*. Er ist mein Gott*, und ich will ihn preisen, der Gott meines Vaters, und ich will ihn erheben*.", footnotes: ["℘ Ps 18,2.3", "o. Meine Zuflucht und meine Kraft", "s. Vorwort\n℘ 5Mo 10,21", "℘ 2Sam 22,3; Ps 68,20; 118,14", "℘ Kap. 6,7", "℘ Ps 118,28; Jes 25,1"] },
      { number: 3, text: "Der HERR ist ein Kriegsheld*, Jahwe* sein Name*.", footnotes: ["w. Mann des Kampfes\n℘ Ps 24,8", "d. i. der Eigenname Gottes im Alten Testament, sonst mit HERR wiedergegeben. Siehe Vorwort.", "℘ Kap. 3,14; Jer 33,2"] },
      { number: 4, text: "Die Wagen des Pharao und seine Streitmacht warf er ins Meer, die Auslese seiner Wagenkämpfer* versank im Schilfmeer*.", footnotes: ["℘ Kap. 14,7", "℘ V. 21; Kap. 14,26.27; Ps 76,7"] },
      { number: 5, text: "Die Fluten bedeckten sie, sie fuhren in die Tiefen wie ein Stein*.", footnotes: ["℘ Neh 9,11"] },
      { number: 6, text: "Deine Rechte, HERR, ist herrlich in Kraft*; deine Rechte, HERR, zerschmettert den Feind*.", footnotes: ["℘ Ps 89,14; 98,1; 118,15.16; Lk 1,51", "℘ Ps 44,4; Jes 63,12"] },
      { number: 7, text: "Und in der Fülle deiner Hoheit* wirfst du nieder, die sich gegen dich erheben*. Du lässt los deine Zornesglut: sie verzehrt sie wie Strohstoppeln*.", footnotes: ["℘ 5Mo 33,26", "℘ Hi 9,4", "℘ Jes 5,24; Nah 1,10"] },
      { number: 8, text: "Beim Schnauben deiner Nase* türmte sich das Wasser, die Strömungen standen wie ein Damm, die Fluten gerannen im Herzen des Meeres.*", footnotes: ["d. h. deines Zorns\n℘ 2Sam 22,16; Hi 4,9", "℘ Kap. 14,22.29"] },
      { number: 9, text: "Es sprach der Feind: Ich jage nach, ich hole ein, verteile Beute*; es sättige sich an ihnen meine Gier, ich zücke mein Schwert, meine Hand tilgt sie aus.", footnotes: ["℘ Ri 5,30"] },
      { number: 10, text: "Du bliesest mit deinem Atem — das Meer bedeckte sie; sie versanken wie Blei in gewaltigen Wassern*.", footnotes: ["℘ Neh 9,11"] },
      { number: 11, text: "Wer ist dir gleich unter den Göttern, HERR! Wer ist dir gleich*, so herrlich in Heiligkeit*, furchtbar an Ruhmestaten*, Wunder tuend!*", footnotes: ["℘ Kap. 18,11; 5Mo 3,24; 1Kö 8,23; Ps 113,5; Jes 46,9; Jer 10,6.7; Mi 7,18", "℘ 1Sam 2,2; Jes 6,3; Offb 15,3.4", "℘ 1Chr 16,25", "℘ 5Mo 4,34; Ps 60,2-6; 77,11.14; 86,10"] },
      { number: 12, text: "Du strecktest aus deine Rechte — die Erde verschlang sie." },
      { number: 13, text: "In deiner Gnade hast du geleitet das Volk, das du erlöst*, hast es durch deine Stärke geführt zu deiner heiligen Wohnung.", footnotes: ["℘ Ps 77,15.16; Jes 63,9"] },
      { number: 14, text: "Es hörten es die Völker, sie bebten*; Angst* ergriff Philistäas Bewohner*.", footnotes: ["℘ 5Mo 2,25; Jos 2,11; 9,9; Ps 48,7; Hes 32,9", "w. Sich-Winden vor Schmerzen o. vor Wehen o. vor Gebärschmerzen", "℘ 1Sam 4,7.8"] },
      { number: 15, text: "Da wurden bestürzt die Fürsten* Edoms*; die Gewaltigen Moabs, Zittern ergriff sie*; es verzagten alle Bewohner Kanaans.", footnotes: ["o. Anführer; w. Tausendmänner; ursprünglich für die edomitischen Stammesfürsten gebraucht", "℘ 1Mo 36,16; 5Mo 2,4", "℘ 4Mo 22,3; Hab 3,6"] },
      { number: 16, text: "Es überfiel sie Schrecken und Furcht*; vor der Größe deines Arms* wurden sie stumm* wie ein Stein, während hindurchzog dein Volk, HERR, während hindurchzog das Volk, das du erworben*.", footnotes: ["℘ Kap. 23,22.27; Jos 2,9.11.24", "℘ Ps 89,14", "o. starr", "℘ Kap. 6,7; Ps 74,2; Jes 43,1"] },
      { number: 17, text: "Du wirst sie bringen und pflanzen auf den Berg deines Erbteils*, die Stätte, die du, HERR, zu deiner Wohnung gemacht hast, das Heiligtum, Herr, das deine Hände bereitet haben*.", footnotes: ["℘ Ps 78,54.55", "℘ Kap. 25,8; Jos 22,19; Hes 37,26"] },
      { number: 18, text: "Der HERR ist König auf immer und ewig*!", footnotes: ["℘ Ps 10,16; 146,10; Dan 3,33; Offb 11,15"] },
      { number: 19, text: "Denn als die Pferde des Pharao mit seinen Wagen und mit seinen Reitern* ins Meer gezogen waren, hat der HERR das Wasser des Meeres über sie zurückkehren lassen; aber die Söhne Israel sind auf trockenem Land mitten durchs Meer gegangen*.", footnotes: ["o. Pferden. — Das hebr. Wort kann beides bedeuten.", "℘ Kap. 14,22; Jos 4,23"] },
      { number: 20, text: "Und die Prophetin Mirjam, Aarons Schwester*, nahm das Tamburin in ihre Hand, und alle Frauen zogen aus, hinter ihr her, mit Tamburinen und in Reigentänzen*.", footnotes: ["℘ Kap. 2,4; 4Mo 26,59; Ri 4,4; 2Kö 22,14; Neh 6,14", "℘ Ri 11,34; 1Sam 18,6; 2Sam 6,14; Ps 68,26"] },
      { number: 21, text: "Und Mirjam sang ihnen* zu: Singt dem HERRN, denn hoch erhaben ist er*; Pferd und Wagen warf er ins Meer!", footnotes: ["d. h. den anderen", "o. hoch hat er sich erhoben"] },
      { number: 22, text: "Und Mose ließ Israel vom Schilfmeer aufbrechen, und sie zogen hinaus in die Wüste Schur* und wanderten drei Tage in der Wüste und fanden kein Wasser*.", heading: "Israel in Mara und Elim", footnotes: ["℘ 1Mo 25,18", "℘ Kap. 17,1"] },
      { number: 23, text: "Da kamen sie nach Mara*, aber sie konnten das Wasser von Mara nicht trinken, denn es war bitter. Darum gab man dem Ort den Namen Mara*.", footnotes: ["℘ 4Mo 33,8", "d. h. Bitterkeit\n℘ Rt 1,20; Offb 8,11"] },
      { number: 24, text: "Und das Volk murrte gegen Mose: Was sollen wir trinken*?", footnotes: ["℘ Kap. 16,2.3; 17,3; Mt 6,31"] },
      { number: 25, text: "Da schrie er zum HERRN*, und der HERR zeigte ihm ein Stück Holz; das warf er ins Wasser, und das Wasser wurde süß*. Dort legte er Ordnung und Recht für es fest*, und dort prüfte er es*,", footnotes: ["℘ Kap. 17,4", "℘ 2Kö 2,21.22; Hes 47,8", "℘ Jos 24,25", "℘ Kap. 16,4; 5Mo 8,2; Ri 2,22; 1Petr 1,6.7"] },
      { number: 26, text: "und er sprach: Wenn du willig auf die Stimme des HERRN, deines Gottes, hörst* und tust, was in seinen Augen recht ist, seinen Geboten gehorchst und all seine Ordnungen hältst, dann werde ich dir keine der Krankheiten auferlegen, die ich den Ägyptern auferlegt habe*; denn ich bin der HERR, der dich heilt*.", footnotes: ["℘ Kap. 19,5; 5Mo 5,1; 28,1; Ps 81,9; Jer 11,7", "℘ 5Mo 7,12.15; Jes 55,3", "℘ Kap. 23,25; 4Mo 12,13; Ps 103,3; Hos 11,3"] },
      { number: 27, text: "Dann kamen sie nach Elim, und dort waren zwölf Wasserquellen und siebzig Palmbäume; und sie lagerten sich dort am Wasser*.", footnotes: ["℘ 4Mo 33,9; Ps 23,2"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und sie brachen von Elim auf, und die ganze Gemeinde der Söhne Israel kam in die Wüste Sin, die zwischen Elim und Sinai liegt*, am fünfzehnten Tag des zweiten Monats nach ihrem Auszug aus dem Land Ägypten.", heading: "Wachteln und Manna", footnotes: ["℘ 4Mo 33,11"] },
      { number: 2, text: "Da murrte die ganze Gemeinde der Söhne Israel gegen Mose und Aaron in der Wüste*.", footnotes: ["℘ Kap. 15,24; Ps 106,25"] },
      { number: 3, text: "Und die Söhne Israel sagten zu ihnen: Wären wir doch durch die Hand des HERRN im Land Ägypten gestorben*, als wir bei den Fleischtöpfen saßen, als wir Brot aßen bis zur Sättigung*! Denn ihr habt uns in diese Wüste herausgeführt, um diese ganze Versammlung an Hunger sterben zu lassen*.", footnotes: ["℘ Kap. 14,11", "℘ 4Mo 11,4.5", "℘ Kap. 17,3; 4Mo 11,20; 5Mo 8,3; Ps 107,5"] },
      { number: 4, text: "Da sprach der HERR zu Mose: Siehe, ich will euch Brot vom Himmel regnen lassen. Dann soll das Volk hinausgehen und den Tagesbedarf täglich* sammeln, damit ich es prüfe*, ob es nach meinem Gesetz* leben will oder nicht.", footnotes: ["w. an seinem Tag", "℘ Kap. 15,25", "o. meiner Weisung"] },
      { number: 5, text: "Am sechsten Tag aber, wenn sie zubereiten, was sie einbringen, wird es geschehen, dass es das Doppelte von dem sein wird, was sie tagtäglich sammeln*.", footnotes: ["℘ 3Mo 25,21.22"] },
      { number: 6, text: "Und Mose und Aaron sagten zu allen Söhnen Israel: Am Abend werdet ihr erkennen, dass euch der HERR aus dem Land Ägypten herausgeführt hat*,", footnotes: ["℘ Ps 81,11"] },
      { number: 7, text: "und am Morgen werdet ihr die Herrlichkeit des HERRN sehen, der euer Murren gegen den HERRN gehört hat*. Denn was sind wir, dass ihr gegen uns murrt*?", footnotes: ["o. wenn er . . . hören wird; w. in seinem Hören", "℘ 4Mo 16,11; Lk 10,16"] },
      { number: 8, text: "Und Mose sagte: Dadurch werdet ihr es erkennen, dass euch der HERR am Abend Fleisch zu essen geben wird* und am Morgen Brot bis zur Sättigung*, weil der HERR euer Murren gehört hat, mit dem ihr gegen ihn murrt. Denn was sind wir? Nicht gegen uns richtet sich euer Murren, sondern gegen den HERRN*.", footnotes: ["o. Dies wird geschehen, wenn (o. weil) der HERR . . . geben wird", "℘ 4Mo 11,18-20", "℘ 1Sam 8,7"] },
      { number: 9, text: "Und Mose sagte zu Aaron: Befiehl der ganzen Gemeinde der Söhne Israel: Tretet vor den HERRN, denn er hat euer Murren gehört*!", footnotes: ["℘ 4Mo 14,27"] },
      { number: 10, text: "Da geschah es, als Aaron zur ganzen Gemeinde der Söhne Israel redete und sie sich zur Wüste hinwandten, siehe, da erschien die Herrlichkeit des HERRN in der Wolke*.", footnotes: ["℘ Kap. 24,16.17; 40,34; 3Mo 9,23; 4Mo 14,10"] },
      { number: 11, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 12, text: "Ich habe das Murren der Söhne Israel gehört*. Rede zu ihnen und sprich: Zwischen den zwei Abenden* werdet ihr Fleisch essen, und am Morgen werdet ihr von Brot satt werden! So werdet ihr erkennen, dass ich der HERR, euer Gott bin*.", footnotes: ["℘ 4Mo 11,4.18", "s. Anm. zu Kap. 12,6", "℘ Kap. 6,7"] },
      { number: 13, text: "Und es geschah am Abend, da kamen Wachteln herauf und bedeckten das Lager*. Und am Morgen war eine Schicht von Tau rings um das Lager.", footnotes: ["℘ 4Mo 11,31.32"] },
      { number: 14, text: "Und als die Tauschicht aufgestiegen war, siehe, da lag auf der Fläche der Wüste etwas Feines*, Körniges, fein, wie der Reif auf der Erde*.", footnotes: ["o. Zartes, Schuppiges", "℘ 4Mo 11,7-9; Ps 105,40"] },
      { number: 15, text: "Das sahen die Söhne Israel, und sie sagten einer zum andern: Was ist das*? Denn sie wussten nicht, was es war. Mose aber sagte zu ihnen: Dies ist das Brot, das euch der HERR zur Nahrung gegeben hat*.", footnotes: ["hebr. man hu. Damit wird bereits der Name des Brotes »Manna« angedeutet.", "℘ 5Mo 8,3.16; Neh 9,15; 1Kor 10,3; Offb 2,17"] },
      { number: 16, text: "Dies ist das Wort, das der HERR geboten hat: Sammelt davon, jeder nach dem Maß seines Essens! Einen Gomer je Kopf sollt ihr nehmen, nach der Zahl eurer Seelen, jeder für die, die in seinem Zelt sind!" },
      { number: 17, text: "Und die Söhne Israel machten es so und sammelten, der eine viel, der andere wenig." },
      { number: 18, text: "Als sie aber mit dem Gomer maßen, da hatte der, der viel gesammelt hatte, keinen Überschuss, und wer wenig gesammelt hatte, der hatte keinen Mangel*. Jeder hatte gesammelt nach dem Maß seines Essens.", footnotes: ["℘ 2Kor 8,15"] },
      { number: 19, text: "Und Mose sagte zu ihnen: Niemand lasse etwas davon übrig bis zum Morgen*!", footnotes: ["℘ Kap. 12,10; Mt 6,34"] },
      { number: 20, text: "Aber sie hörten nicht auf Mose, sondern einige ließen etwas davon bis zum Morgen übrig; da verfaulte es durch Würmer* und stank. Da wurde Mose zornig über sie.", footnotes: ["o. da wuchsen (w. erhoben sich) Würmer darin"] },
      { number: 21, text: "Und sie sammelten es Morgen für Morgen, jeder nach dem Maß seines Essens. Wenn aber die Sonne heiß wurde, dann zerschmolz es." },
      { number: 22, text: "Und es geschah am sechsten Tag, da sammelten sie das Doppelte an Brot, zwei Gomer für jeden Einzelnen. Da kamen alle Fürsten der Gemeinde und berichteten es Mose." },
      { number: 23, text: "*Er sagte nun zu ihnen: Dies ist es, was der HERR geredet hat: Morgen ist eine Sabbatfeier, ein heiliger Sabbat* für den HERRN. Was ihr backen wollt, backt, und was ihr kochen wollt, kocht! Alles aber, was übrig bleibt, legt für euch zurück zur Aufbewahrung bis zum nächsten Morgen!", footnotes: ["℘ V. 23-30: Kap. 20,8-11", "»Sabbat« heißt wahrscheinlich »Ruhetag«."] },
      { number: 24, text: "Da legten sie es zurück bis zum nächsten Morgen, wie Mose geboten hatte, und es wurde nicht stinkend, und es kam kein Wurm hinein." },
      { number: 25, text: "Mose sagte: Esst es heute, denn heute ist ein Sabbat für den HERRN! Heute werdet ihr auf dem Feld nichts finden." },
      { number: 26, text: "Sechs Tage sollt ihr es sammeln, aber am siebten Tag ist Sabbat, da gibt es nichts." },
      { number: 27, text: "Aber am siebten Tag geschah es, dass dennoch einige vom Volk hinausgingen, um zu sammeln, doch sie fanden nichts." },
      { number: 28, text: "Da sprach der HERR zu Mose: Wie lange habt ihr euch nun schon geweigert, meine Gebote und Gesetze* zu halten*!", footnotes: ["o. Weisungen", "℘ 4Mo 14,11; 2Kö 17,14.15; Ps 78,10; Hes 5,6"] },
      { number: 29, text: "Seht, weil* euch der HERR den Sabbat gegeben hat*, darum gibt er euch am sechsten Tag Brot für zwei Tage*. So bleibe nun jeder von euch daheim*, niemand verlasse am siebten Tag seinen Lagerplatz!", footnotes: ["o. dass", "℘ Mt 12,8", "℘ 3Mo 25,21", "w. an seiner Stelle"] },
      { number: 30, text: "So ruhte denn das Volk am siebten Tag." },
      { number: 31, text: "Und das Haus* Israel gab ihm den Namen Man*, und es war weiß wie Koriandersamen und sein Geschmack wie Kuchen mit Honig*.", footnotes: ["Gemeint ist die Volksgemeinschaft.", "griech. Manna", "℘ 4Mo 11,7.8"] },
      { number: 32, text: "Mose nun sagte: Das ist es, was* der HERR geboten hat: Ein Gomer voll davon sei* zur Aufbewahrung für eure künftigen Generationen, damit sie das Brot sehen, das ich euch in der Wüste zu essen gegeben habe, als ich euch aus dem Land Ägypten herausgeführt hatte.", footnotes: ["w. die Sache, die, o. das Wort, das", "Eine hebr. Handschr. und LXX lesen: Füllt den Gomer damit"] },
      { number: 33, text: "Und Mose sagte zu Aaron: Nimm einen Behälter und tu Man* hinein, einen Gomer voll, und stelle ihn hin vor den HERRN zur Aufbewahrung für eure künftigen Generationen*!", footnotes: ["griech. Manna", "℘ Hebr 9,4"] },
      { number: 34, text: "Wie der HERR dem Mose geboten hatte, so stellte ihn Aaron vor das Zeugnis* zur Aufbewahrung*. —", footnotes: ["o. die Bezeugung. — Gemeint ist ein mahnendes Zeichen der Gegenwart Gottes, viell. die Bundeslade.", "℘ 4Mo 17,25"] },
      { number: 35, text: "Und die Söhne Israel aßen das Man* vierzig Jahre*, bis sie in bewohntes Land kamen; sie aßen das Man*, bis sie an die Grenze des Landes Kanaan kamen.", footnotes: ["griech. Manna", "℘ 4Mo 32,13; 5Mo 2,7; Jos 5,12; Joh 6,31.49; Apg 13,18", "griech. Manna"] },
      { number: 36, text: "Der Gomer aber ist ein Zehntel vom Efa*.", footnotes: ["℘ Rt 2,17; Hes 45,11"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und die ganze Gemeinde der Söhne Israel brach nach ihrer Aufbruchsordnung* aus der Wüste Sin* auf nach dem Befehl des HERRN*, und sie lagerten sich in Refidim*. Aber da war kein Wasser zum Trinken für das Volk*.", heading: "Wasser aus dem Felsen", footnotes: ["w. nach ihren Aufbrüchen; das kann auch heißen: von Aufbruchsort zu Aufbruchsort", "℘ Kap. 16,1", "℘ 4Mo 9,17-23", "℘ 4Mo 33,12-14", "℘ Kap. 15,22"] },
      { number: 2, text: "Da geriet das Volk mit Mose in Streit*, und sie sagten: Gib* uns Wasser, damit wir zu trinken haben! Mose aber erwiderte ihnen: Was streitet ihr mit mir? Was prüft ihr den HERRN*?", footnotes: ["o. machte . . . Vorwürfe\n℘ 4Mo 20,2.3", "so mit einer hebr. Handschr. und allen alten Üs.; Mas. T.: Gebt", "℘ Ps 78,18.41; Hebr 3,8.9"] },
      { number: 3, text: "Als nun das Volk dort nach Wasser dürstete, murrte das Volk gegen Mose und sagte: Wozu hast du uns überhaupt aus Ägypten heraufgeführt? Um mich und meine Kinder und mein Vieh vor Durst sterben zu lassen*?", footnotes: ["℘ Kap. 14,11; 16,3; Ps 107,5"] },
      { number: 4, text: "Da schrie Mose zum HERRN* und sagte: Was soll ich mit diesem Volk tun? Noch ein wenig, so steinigen sie mich*.", footnotes: ["℘ Kap. 15,25; Ps 99,6", "℘ 4Mo 14,10; 1Sam 30,6; Joh 8,59; Apg 14,19"] },
      { number: 5, text: "Und der HERR antwortete Mose: Geh dem Volk voran und nimm einige von den Ältesten Israels mit dir. Auch deinen Stab, mit dem du auf den Nil geschlagen hast, nimm in deine Hand und geh hin*!", footnotes: ["℘ Kap. 7,20; 4Mo 20,8"] },
      { number: 6, text: "Siehe, ich will dort vor dich auf den Felsen am Horeb treten*. Dann sollst du auf den Felsen schlagen, und es wird Wasser aus ihm hervorströmen, so dass das Volk zu trinken hat*. Und Mose machte es so vor den Augen der Ältesten Israels.", footnotes: ["o. vor dir auf dem Felsen stehen", "℘ 5Mo 8,15; Neh 9,15; Ps 74,15; 78,15.16; 114,8; Jes 48,21; 1Kor 10,4"] },
      { number: 7, text: "Und er gab dem Ort den Namen Massa* und Meriba* wegen des Streitens der Söhne Israel und weil sie den HERRN geprüft hatten*, indem sie sagten: Ist der HERR in unserer Mitte oder nicht*?", footnotes: ["d. h. Prüfung, o. Versuchung", "d. h. Streit\n℘ 4Mo 20,13; Ps 95,8.9; 106,32", "℘ 5Mo 33,8; Ps 78,18", "℘ 5Mo 6,16"] },
      { number: 8, text: "Danach kam Amalek* und kämpfte in Refidim* gegen Israel.", heading: "Kampf gegen Amalek", footnotes: ["℘ 1Mo 14,7; 4Mo 13,29; Ri 6,3; 1Sam 14,48", "℘ 5Mo 25,17.18"] },
      { number: 9, text: "Und Mose sagte zu Josua*: Wähle uns Männer aus* und zieh aus, kämpfe gegen Amalek! Morgen will ich mich* auf den Gipfel des Hügels stellen mit dem Stab Gottes in meiner Hand*.", footnotes: ["hebr. Jehoschua; d. h. der HERR ist Rettung (griech. Jesus)\n℘ Kap. 24,13; 33,11; 4Mo 13,8.16", "℘ Kap. 18,21; Jos 8,3", "LXX: Kämpfe morgen gegen Amalek! Ich will mich", "℘ Kap. 4,20"] },
      { number: 10, text: "Da tat Josua, wie Mose ihm gesagt hatte, um gegen Amalek zu kämpfen. Und Mose, Aaron und Hur* stiegen auf den Gipfel des Hügels.", footnotes: ["℘ Kap. 24,14; 1Chr 2,19"] },
      { number: 11, text: "Und es geschah, wenn Mose seine Hand* erhob, dann hatte Israel die Oberhand*, wenn er aber seine Hand* sinken ließ, dann hatte Amalek die Oberhand.", footnotes: ["Eine hebr. Handschr. und die alten Üs. lesen: seine Hände", "℘ Ps 44,6", "Eine hebr. Handschr. und die alten Üs. lesen: seine Hände"] },
      { number: 12, text: "Da jedoch Moses Hände schwer wurden, nahmen sie einen Stein und legten den unter ihn, und er setzte sich darauf. Dann stützten Aaron und Hur seine Hände, der eine auf dieser, der andere auf jener Seite. So blieben seine Hände fest, bis die Sonne unterging." },
      { number: 13, text: "Und Josua besiegte Amalek und sein Kriegsvolk mit der Schärfe des Schwertes*.", footnotes: ["℘ Jos 8,26"] },
      { number: 14, text: "Danach sprach der HERR zu Mose: Schreib dies zur Erinnerung in ein Buch* und lege in die Ohren Josuas, dass ich die Erwähnung von Amalek vollständig unter dem Himmel auslöschen werde*!", footnotes: ["o. das Buch; o. auf das Schriftstück; o. in die Inschrift\n℘ Jer 30,2", "℘ 4Mo 24,20; 5Mo 25,19; 1Sam 15,2.3; 1Chr 4,42.43"] },
      { number: 15, text: "Und Mose baute einen Altar* und gab ihm den Namen: »Der HERR ist mein Feldzeichen«,", footnotes: ["℘ Kap. 24,4; 27,1; 32,5; 1Mo 12,7.8"] },
      { number: 16, text: "indem er sagte: Fürwahr, die Hand ist am Thron Jahs*: Krieg hat der HERR mit Amalek von Generation zu Generation!", footnotes: ["So mit SamPent u. a. Die Bedeutung des hebr. Wortes ist unbekannt. Viele üs.: die Hand an das Feldzeichen des HERRN\n℘ Hebr 6,13"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Jitro aber, der Priester von Midian, der Schwiegervater des Mose*, hatte alles gehört, was Gott an Mose und an seinem Volk Israel getan hatte, dass der HERR Israel aus Ägypten herausgeführt hatte.", heading: "Jitros Besuch bei Mose", footnotes: ["℘ Kap. 2,16-21; 3,1; Ri 1,16"] },
      { number: 2, text: "Da nahm Jitro, der Schwiegervater des Mose, Zippora, die Frau des Mose mit sich, nachdem dieser sie zurückgeschickt hatte*,", footnotes: ["w. nach ihrer Entlassung"] },
      { number: 3, text: "mit ihren beiden Söhnen. Der eine von ihnen hieß Gerschom*, weil er* gesagt hatte: Ein Fremder bin ich geworden im fremden Land*.", footnotes: ["s. Anm. zu Kap. 2,22", "d. i. Mose", "℘ Kap. 2,22"] },
      { number: 4, text: "Der andere aber hieß Eliëser*, denn er hatte gesagt: Der Gott meines Vaters ist meine Hilfe gewesen und hat mich vom Schwert des Pharao gerettet*.", footnotes: ["d. h. mein Gott ist Hilfe\n℘ 1Chr 23,15", "℘ Kap. 2,15; 10,28"] },
      { number: 5, text: "So kam Jitro, der Schwiegervater des Mose, mit dessen Söhnen und dessen Frau zu Mose in die Wüste, wo er am Berg Gottes* lagerte.", footnotes: ["℘ Kap. 3,1.12"] },
      { number: 6, text: "Und er ließ dem Mose sagen: Ich, dein Schwiegervater Jitro, komme zu dir und deine Frau und ihre beiden Söhne mit ihr*.", footnotes: ["℘ Kap. 4,20"] },
      { number: 7, text: "Da ging Mose hinaus, seinem Schwiegervater entgegen, verneigte sich und küsste ihn*, und sie fragten einer den andern nach ihrem Wohlergehen* und gingen ins Zelt.", footnotes: ["o. und er (d. i. Jitro) küsste ihn", "℘ 1Mo 43,27; 1Sam 17,22; 2Sam 11,7"] },
      { number: 8, text: "Und Mose erzählte seinem Schwiegervater alles, was der HERR am Pharao und an den Ägyptern um Israels willen getan hatte, all die Mühsal*, die ihnen auf dem Weg begegnet war, und dass der HERR sie gerettet hatte*.", footnotes: ["℘ Kap. 23,23-25", "℘ Ps 106,8-11"] },
      { number: 9, text: "Da freute sich Jitro über all das Gute, das der HERR an Israel getan hatte, dass* er es aus der Hand der Ägypter gerettet hatte*.", footnotes: ["o. als; o. wie", "℘ Jes 44,23"] },
      { number: 10, text: "Und Jitro sagte: Gepriesen sei der HERR, der euch gerettet hat aus der Hand der Ägypter und aus der Hand des Pharao, der das Volk gerettet hat unter der Hand der Ägypter hinweg*!", footnotes: ["℘ Lk 1,68"] },
      { number: 11, text: "Nun habe ich erkannt, dass der HERR größer ist als alle Götter*; denn worin* sie vermessen handelten*, das kam über sie*.", footnotes: ["℘ Kap. 15,11; Ps 95,3", "w. in der Sache, in der", "℘ Neh 9,10", "℘ 4Mo 33,4"] },
      { number: 12, text: "Darauf nahm Jitro, der Schwiegervater des Mose, ein Brandopfer und Schlachtopfer für Gott. Und Aaron und alle Ältesten Israels kamen, um mit Moses Schwiegervater vor Gott ein Mahl zu halten*.", footnotes: ["℘ 1Mo 26,30; 1Chr 29,22"] },
      { number: 13, text: "Und es geschah am Tag darauf, da setzte Mose sich nieder, um dem Volk Recht zu sprechen. Und das Volk stand bei Mose vom Morgen bis zum Abend.", heading: "Einsetzung von Richtern" },
      { number: 14, text: "Als aber der Schwiegervater des Mose alles sah, was er mit dem Volk tat, sagte er: Was ist das, das du mit dem Volk tust? Warum sitzt du allein da, während alles Volk vom Morgen bis zum Abend bei dir steht?" },
      { number: 15, text: "Mose antwortete seinem Schwiegervater: Weil das Volk zu mir kommt, um Gott zu befragen*.", footnotes: ["℘ 3Mo 24,12.13; 4Mo 15,34; Ri 1,1"] },
      { number: 16, text: "Wenn sie eine Rechtssache haben, dann kommt es zu mir, und ich richte zwischen dem einen und dem andern und gebe ihnen die Ordnungen Gottes und seine Weisungen* bekannt*.", footnotes: ["o. Gesetze", "℘ 5Mo 17,9; 2Chr 19,10"] },
      { number: 17, text: "Da sagte Moses Schwiegervater zu ihm: Die Sache ist nicht gut, die du tust." },
      { number: 18, text: "Du reibst dich auf*, sowohl du als auch dieses Volk, das bei dir ist. Die Aufgabe ist zu schwer für dich, du kannst sie nicht allein bewältigen*.", footnotes: ["w. wirst welk; o. wirst erschöpft sein", "℘ 4Mo 11,14; 5Mo 1,9-13"] },
      { number: 19, text: "Höre nun auf meine Stimme, ich will dir raten, und Gott wird mit dir sein*: Vertritt du das Volk vor Gott*, und bringe du die Sachen vor Gott.", footnotes: ["w. sei mit dir", "w. Sei du für das Volk Gott gegenüber"] },
      { number: 20, text: "Belehre* sie über die Ordnungen und Weisungen, und zeige ihnen* den Weg, den sie gehen, und das Werk, das sie tun sollen*.", footnotes: ["w. Warne", "w. lass sie erkennen", "℘ 5Mo 5,27"] },
      { number: 21, text: "Du aber suche dir aus dem ganzen Volk tüchtige, gottesfürchtige Männer aus, zuverlässige* Männer*, die ungerechten Gewinn hassen*, und setze sie über sie: Oberste von Tausend, Oberste von Hundert, Oberste von Fünfzig und Oberste von Zehn*,", footnotes: ["o. treue, wahrhaftige", "℘ Kap. 17,9; Neh 7,2", "℘ 5Mo 16,18-20; 2Chr 19,7; Tit 1,5-7", "℘ 5Mo 1,13-15; 2Sam 18,1"] },
      { number: 22, text: "damit sie dem Volk jederzeit Recht sprechen*! Und es soll geschehen, dass sie jede große Sache vor dich bringen*, jede kleine Sache aber selbst richten. Auf diese Weise entlaste dich*, und sie mögen es mit dir tragen!*", footnotes: ["℘ Esr 7,25", "℘ 4Mo 15,33; 27,2-7", "o. So entlaste dich; o. (so verschiedene Üs.) Und sie werden es dir erleichtern", "℘ 4Mo 11,17"] },
      { number: 23, text: "Wenn du dies tust und Gott es dir gebietet, dann wirst du bestehen können, und auch dieses ganze Volk wird in Frieden an seinen Ort* kommen.", footnotes: ["d. h. entweder »nach Hause« oder »in das verheißene Land«"] },
      { number: 24, text: "Und Mose hörte auf die Stimme seines Schwiegervaters und tat alles, was er gesagt hatte." },
      { number: 25, text: "So wählte Mose denn aus ganz Israel tüchtige Männer aus und machte sie zu Oberhäuptern über das Volk: Oberste von Tausend, Oberste von Hundert, Oberste von Fünfzig und Oberste von Zehn." },
      { number: 26, text: "Diese sprachen dem Volk jederzeit Recht: Jede schwierige Sache brachten sie vor Mose*, jede kleine Sache aber richteten sie selbst.*", footnotes: ["℘ 3Mo 24,11; 5Mo 1,17", "o. damit sie . . . Recht sprächen. Jede schwierige Sache sollten sie vor Mose bringen, jede kleine Sache aber selbst entscheiden."] },
      { number: 27, text: "Darauf ließ Mose seinen Schwiegervater ziehen, und dieser ging wieder in sein Land*.", footnotes: ["℘ 4Mo 10,30"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Im dritten Monat nach dem Auszug der Söhne Israel aus dem Land Ägypten, an ebendiesem Tag kamen sie in die Wüste Sinai*.", heading: "Israel am Sinai — Vorbereitung auf die Gesetzgebung", footnotes: ["℘ 4Mo 1,1; 33,15"] },
      { number: 2, text: "Sie brachen auf von Refidim* und kamen in die Wüste Sinai und lagerten sich in der Wüste*; und Israel lagerte sich dort dem Berg gegenüber*.", footnotes: ["℘ Kap. 17,1.8", "℘ 4Mo 1,1; 33,15", "℘ Kap. 3,1"] },
      { number: 3, text: "Mose aber stieg hinauf zu Gott*. Und der HERR rief ihm vom Berg aus zu*: So sollst du zum Haus Jakob sagen und den Söhnen Israel mitteilen:", footnotes: ["℘ V. 20; Kap. 20,21; 24,12.13.18; 34,4", "℘ Kap. 3,4"] },
      { number: 4, text: "Ihr habt gesehen, was ich den Ägyptern angetan* und wie ich euch auf Adlerflügeln* getragen und euch zu mir gebracht habe*.", footnotes: ["℘ 5Mo 4,34.35; 29,1; Jos 23,3", "℘ 5Mo 1,31; 32,11", "℘ Hos 11,1.3"] },
      { number: 5, text: "Und nun, wenn ihr willig auf meine Stimme hören und meinen Bund halten werdet*, dann sollt ihr aus allen Völkern mein Eigentum sein*; denn mir gehört die ganze Erde*.", footnotes: ["℘ Kap. 15,26", "℘ Kap. 6,7; 34,9; 1Kö 8,53; Ps 135,4; Jer 13,11; Tit 2,14", "℘ 5Mo 10,14; Hi 41,3"] },
      { number: 6, text: "Und ihr sollt mir ein Königreich von Priestern* und eine heilige Nation sein*. Das sind die Worte*, die du zu den Söhnen Israel reden sollst.", footnotes: ["℘ Jes 61,6", "℘ Kap. 28,36; 3Mo 11,44.45; 20,24.26; 5Mo 26,19; Ps 114,2; Jer 7,23; 2Kor 7,1; 1Petr 2,5.9", "℘ Hag 2,5"] },
      { number: 7, text: "Darauf ging Mose hin, rief die Ältesten des Volkes zusammen und legte ihnen all diese Worte vor, die ihm der HERR geboten hatte*.", footnotes: ["℘ Kap. 4,29.30"] },
      { number: 8, text: "Da antwortete das ganze Volk gemeinsam und sagte: Alles, was der HERR geredet hat, wollen wir tun*! Und Mose brachte dem HERRN die Worte des Volkes zurück.", footnotes: ["℘ Kap. 24,3.7; 5Mo 5,27; 26,17; Jos 24,21.24"] },
      { number: 9, text: "Da sprach der HERR zu Mose: Siehe, ich werde im Dunkel des Gewölks* zu dir kommen, damit es das Volk hört, wenn ich mit dir rede, und auch dir ewig glaubt*. Und Mose teilte dem HERRN die Worte des Volkes mit.", footnotes: ["℘ 5Mo 4,11; Ps 18,12; 97,2; Hebr 12,18", "℘ Kap. 14,31"] },
      { number: 10, text: "Und der HERR sprach zu Mose: Geh zum Volk und heilige sie* heute und morgen! Und sie sollen ihre Kleider waschen*,", footnotes: ["d. h. hier wohl: veranlasse sie, sich heilig zu halten\n℘ 4Mo 11,18; Jos 3,5", "℘ 1Mo 35,2; 4Mo 31,23.24"] },
      { number: 11, text: "damit sie für den dritten Tag bereit sind; denn am dritten Tag wird der HERR vor den Augen des ganzen Volkes auf den Berg Sinai herabsteigen*.", footnotes: ["℘ Kap. 24,16.17; 5Mo 4,10"] },
      { number: 12, text: "Darum zieh eine Grenze rings um das Volk und sage: Hütet euch, auf den Berg zu steigen* oder auch nur sein Ende* zu berühren! Jeder, der den Berg berührt, muss getötet werden.", footnotes: ["℘ Kap. 24,2", "d. h. den Fuß des Berges, o. sein Äußerstes"] },
      { number: 13, text: "Keine Hand darf ihn berühren, denn sonst muss er gesteinigt oder erschossen* werden; ob Tier oder Mensch, er darf nicht am Leben bleiben*. Erst wenn das Widderhorn* anhaltend ertönt, sollen sie zum Berg hinaufsteigen.", footnotes: ["d. h. mit einem Pfeil oder Wurfgeschoss", "℘ Kap. 34,3; Hebr 12,20", "w. der Widder"] },
      { number: 14, text: "Darauf stieg Mose vom Berg zu dem Volk hinab; und er heiligte das Volk, und sie wuschen ihre Kleider*.", footnotes: ["℘ 1Mo 35,2; 4Mo 31,23.24"] },
      { number: 15, text: "Dann sagte er zum Volk: Haltet euch für den dritten Tag bereit! Nähert euch keiner Frau*!", footnotes: ["d. h. geschlechtlich\n℘ 3Mo 15,18; 1Sam 21,5.6"] },
      { number: 16, text: "Und es geschah am dritten Tag, als es Morgen wurde, da brachen Donner und Blitze los, und eine schwere Wolke* lagerte auf dem Berg, und ein sehr starker Hörnerschall* ertönte, so dass das ganze Volk, das im Lager war, bebte*.", footnotes: ["℘ Ps 81,8; Offb 4,5", "℘ 1Thes 4,16; Hebr 12,19; Offb 1,10", "℘ Kap. 20,18; 5Mo 5,5"] },
      { number: 17, text: "Mose aber führte das Volk aus dem Lager hinaus, Gott entgegen, und sie stellten sich am Fuß des Berges auf*.", footnotes: ["℘ 5Mo 4,11"] },
      { number: 18, text: "Und der ganze Berg Sinai rauchte, weil der HERR im Feuer auf ihn herabkam*. Und sein Rauch stieg auf wie der Rauch eines Schmelzofens*, und der ganze Berg erbebte heftig*.", footnotes: ["℘ 5Mo 4,36; 33,2; Neh 9,13; Ps 18,9; 104,32", "℘ 1Mo 19,28", "℘ Ps 68,9; 77,19; 114,4; Hab 3,6; Hebr 12,26; Offb 8,5"] },
      { number: 19, text: "Und der Hörnerschall wurde immer stärker. Mose redete, und Gott antwortete ihm* mit einer lauten Stimme*.", footnotes: ["℘ 4Mo 12,8; Apg 7,38", "o. im Donner; o. im Schall\n℘ 5Mo 5,22"] },
      { number: 20, text: "Und der HERR stieg auf den Berg Sinai herab, auf den Gipfel des Berges, und der HERR rief Mose auf den Gipfel des Berges, und Mose stieg hinauf*.", footnotes: ["℘ V. 3; Kap. 24,15; Offb 4,1"] },
      { number: 21, text: "Und der HERR sprach zu Mose: Steig hinab, warne das Volk*, dass sie nicht zum HERRN durchbrechen, um zu schauen; sonst müssten viele von ihnen fallen*.", footnotes: ["w. schärfe dem Volk ein", "℘ 4Mo 4,15.20; 1Sam 6,19"] },
      { number: 22, text: "Ja, auch die Priester, die zum HERRN herantreten*, sollen sich heiligen, damit der HERR nicht in sie einbricht*.", footnotes: ["w. sich nähern", "d. i. um zu verheeren\n℘ 3Mo 10,3; 1Chr 13,9-11"] },
      { number: 23, text: "Mose aber sagte zum HERRN: Das Volk wird den Berg Sinai nicht ersteigen können, denn du hast uns ja gewarnt und gesagt: Zieh eine Grenze um den Berg und erkläre ihn für heilig!" },
      { number: 24, text: "Da sprach der HERR zu ihm: Geh, steig hinab, und komm dann wieder herauf, du und Aaron mit dir! Aber die Priester und das Volk sollen nicht durchbrechen, um zum HERRN hinaufzusteigen, damit er nicht in sie einbricht*.", footnotes: ["d. i. um zu verheeren\n℘ 3Mo 10,3; 1Chr 13,9-11"] },
      { number: 25, text: "Da stieg Mose zum Volk hinab und sagte es ihnen*.", footnotes: ["℘ 5Mo 5,5"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "*Und Gott redete alle diese Worte und sprach:", heading: "Die Zehn Gebote", footnotes: ["℘ V. 1-17: 5Mo 5,4-21"] },
      { number: 2, text: "Ich bin der HERR, dein Gott*, der ich dich aus dem Land Ägypten, aus dem Sklavenhaus, herausgeführt habe*.", footnotes: ["℘ 1Kö 18,39", "℘ Kap. 13,3.14; 29,46; 3Mo 25,38.42.55; 5Mo 20,1; Ps 81,7"] },
      { number: 3, text: "Du sollst* keine andern Götter haben neben mir*. —", footnotes: ["Die Befehlsform »du sollst nicht« kann auch wiedergegeben werden: du wirst nicht, d. h. es ist undenkbar, dass du . . . tun wirst.", "w. zu meinem Angesicht hinzu; o. gegen mein Angesicht, d. h. mir zum Trotz\n℘ Kap. 22,19; 5Mo 6,14; Ri 6,10; 1Kö 11,4-6"] },
      { number: 4, text: "Du sollst dir kein Götterbild* machen, auch keinerlei Abbild dessen, was oben im Himmel oder was unten auf der Erde oder was im Wasser unter der Erde ist*.", footnotes: ["d. i. ein aus Stein gehauenes oder aus Holz geschnitztes Bild", "℘ V. 23; Kap. 32,4; 34,17; 3Mo 19,4; 2Chr 33,7; Apg 17,29"] },
      { number: 5, text: "Du sollst dich vor ihnen nicht niederwerfen* und ihnen nicht dienen*. Denn ich, der HERR, dein Gott, bin ein eifersüchtiger Gott*, der die Schuld der Väter heimsucht an den Kindern, an der dritten und vierten Generation* von denen, die mich hassen*,", footnotes: ["d. i. um deine Ehrfurcht zu bezeugen; dasselbe Wort wie »anbeten«", "℘ Kap. 23,24; Jos 23,7; Dan 3,18", "℘ Kap. 34,14", "d. h. an Enkeln und Urenkeln", "℘ 4Mo 14,18; Mt 27,25; Joh 9,2"] },
      { number: 6, text: "der aber Gnade erweist an Tausenden von Generationen von denen, die mich lieben und meine Gebote halten*. —", footnotes: ["℘ Kap. 34,7; Dan 9,4"] },
      { number: 7, text: "Du sollst den Namen des HERRN, deines Gottes, nicht zu Nichtigem* aussprechen*, denn der HERR wird den nicht ungestraft lassen, der seinen Namen zu Nichtigem* ausspricht*.", footnotes: ["o. zu Falschem; o. zu Lügenhaftem", "℘ 1Mo 27,20; 3Mo 19,12", "o. zu Falschem; o. zu Lügenhaftem", "℘ Mal 3,5"] },
      { number: 8, text: "*Denke an den Sabbattag, um ihn heilig zu halten*.", footnotes: ["℘ V. 8-11: Kap. 16,23-30; 31,12-17; 35,1-3; 3Mo 23,3; Jer 17,21.22; Hes 20,20", "℘ 3Mo 19,3.30; 26,2; Lk 23,56"] },
      { number: 9, text: "Sechs Tage sollst du arbeiten und all deine Arbeit tun*,", footnotes: ["℘ Lk 13,14-16"] },
      { number: 10, text: "aber der siebte Tag ist Sabbat* für den HERRN, deinen Gott*. Du sollst an ihm keinerlei Arbeit tun, du und dein Sohn und deine Tochter, dein Knecht und deine Magd und dein Vieh und der Fremde bei dir, der innerhalb deiner Tore wohnt*.", footnotes: ["»Sabbat« heißt wahrscheinlich »Ruhetag«.", "o. des HERRN, deines Gottes", "℘ Kap. 23,12; 34,21"] },
      { number: 11, text: "Denn in sechs Tagen hat der HERR den Himmel und die Erde gemacht, das Meer und alles, was in ihnen ist*, und er ruhte am siebten Tag; darum segnete der HERR den Sabbattag und heiligte ihn*.", footnotes: ["℘ 1Mo 1,31; Apg 4,24", "℘ 1Mo 2,2.3; Hebr 4,11"] },
      { number: 12, text: "*Ehre deinen Vater und deine Mutter*, damit deine Tage lange währen in dem Land, das der HERR, dein Gott, dir gibt*. —", footnotes: ["℘ V. 12-17: Mt 19,18.19; Röm 13,9", "℘ Kap. 21,17; 3Mo 19,3; Eph 6,2.3", "℘ 5Mo 4,40"] },
      { number: 13, text: "Du sollst nicht töten*. —", footnotes: ["℘ Kap. 21,12; Mt 5,21"] },
      { number: 14, text: "Du sollst nicht ehebrechen*. —", footnotes: ["℘ 1Mo 39,9; 3Mo 18,20; 20,10; 4Mo 5,12; Mt 19,3-9"] },
      { number: 15, text: "Du sollst nicht stehlen*. —", footnotes: ["℘ 3Mo 19,11; Röm 2,21.22"] },
      { number: 16, text: "Du sollst gegen deinen Nächsten nicht als falscher Zeuge aussagen*. —", footnotes: ["℘ Kap. 23,1; Spr 19,5.9; 1Petr 2,1"] },
      { number: 17, text: "Du sollst nicht das Haus deines Nächsten begehren*. Du sollst nicht begehren die Frau deines Nächsten*, noch seinen Knecht, noch seine Magd, weder sein Rind noch seinen Esel, noch irgendetwas, was deinem Nächsten gehört*.", footnotes: ["℘ Mi 2,2", "℘ Mt 5,27.28", "℘ Apg 20,33; Röm 7,7"] },
      { number: 18, text: "Und das ganze Volk nahm den Donner wahr, die Flammen*, den Hörnerschall und den rauchenden Berg. Als nun das Volk das wahrnahm, zitterten sie*, blieben von ferne stehen*", footnotes: ["w. Fackeln; wie 1Mo 15,17\n℘ 1Mo 15,17", "Eine alte Handschr., LXX und Vulg. lesen: Da fürchtete sich das Volk, und sie zitterten", "℘ Kap. 19,16"] },
      { number: 19, text: "und sagten zu Mose: Rede du mit uns, dann wollen wir hören*! Aber Gott soll nicht mit uns reden, damit wir nicht sterben*.", footnotes: ["℘ 5Mo 5,23-27; Hebr 12,19", "℘ 3Mo 10,3; 1Chr 13,9-11"] },
      { number: 20, text: "Da sagte Mose zum Volk: Fürchtet euch nicht! Denn nur um euch zu prüfen, ist Gott gekommen, und damit die Furcht vor ihm euch vor Augen* sei*, damit ihr nicht sündigt.", footnotes: ["w. auf eurem Gesicht", "℘ 5Mo 4,10; 8,2"] },
      { number: 21, text: "So blieb denn das Volk von ferne stehen*. Mose aber näherte sich dem Dunkel*, wo Gott war*.", footnotes: ["℘ Kap. 19,16", "℘ 1Kö 8,12; Hebr 12,18", "℘ Kap. 19,3.20"] },
      { number: 22, text: "Da sprach der HERR zu Mose: So sollst du zu den Söhnen Israel sprechen: Ihr habt selbst gesehen, dass ich vom Himmel her mit euch geredet habe*.", heading: "Das Altargesetz", footnotes: ["℘ 5Mo 4,36; Neh 9,13"] },
      { number: 23, text: "Ihr sollt neben mir keine Götter aus Silber machen, auch Götter aus Gold sollt ihr euch nicht machen." },
      { number: 24, text: "Einen Altar aus Erde sollst du mir machen und darauf deine Brandopfer und Heilsopfer*, deine Schafe und deine Rinder darbringen. An jedem Ort, wo ich meines Namens werde gedenken lassen, werde ich zu dir kommen* und dich segnen.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Ps 101,2; Joh 14,23"] },
      { number: 25, text: "Wenn du mir aber einen Altar aus Steinen machst*, dann darfst du sie nicht als behauene Steine aufbauen, denn du hättest deinen Meißel darüber geschwungen und ihn entweiht*.", footnotes: ["℘ Kap. 24,4", "℘ 5Mo 27,5; Jos 8,31"] },
      { number: 26, text: "Du sollst auch nicht auf Stufen zu meinem Altar hinaufsteigen, damit nicht deine Blöße an ihm aufgedeckt wird.*", footnotes: ["℘ Kap. 28,42.43"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "*Und dies sind die Rechtsbestimmungen, die du ihnen vorlegen sollst*:", heading: "Rechte hebräischer Sklaven", footnotes: ["℘ 5Mo 15,12-18", "℘ 5Mo 4,14"] },
      { number: 2, text: "Wenn du einen hebräischen Sklaven kaufst*, soll er sechs Jahre dienen, im siebten aber soll er umsonst* frei ausziehen*.", footnotes: ["℘ 3Mo 25,39", "w. ohne Entschädigung; o. unentgeltlich, d. h. ohne dass ein Loskauf erforderlich ist", "℘ Jer 34,14; Joh 8,35"] },
      { number: 3, text: "Falls er allein gekommen ist, soll er auch allein ausziehen. Falls er Ehemann* einer Frau war, soll seine Frau mit ihm ausziehen.", footnotes: ["o. Eheherr; w. Herr, Besitzer"] },
      { number: 4, text: "Falls ihm sein Herr eine Frau gegeben und sie ihm Söhne oder Töchter geboren hat, sollen die Frau und ihre Kinder ihrem Herrn gehören, und er soll allein ausziehen." },
      { number: 5, text: "Falls aber der Sklave sagt: Ich liebe meinen Herrn, meine Frau und meine Kinder, ich will nicht als Freier ausziehen!," },
      { number: 6, text: "so soll ihn sein Herr vor Gott bringen* und ihn an die Tür oder an den Türpfosten stellen, und sein Herr soll ihm das Ohr mit einem Pfriem durchbohren; dann soll er ihm für ewig* dienen.", footnotes: ["℘ 5Mo 19,17", "o. auf Dauer"] },
      { number: 7, text: "Wenn jedoch jemand seine Tochter als Sklavin verkauft*, soll sie nicht ausziehen, wie die Sklaven ausziehen.", footnotes: ["℘ Neh 5,5"] },
      { number: 8, text: "Falls sie ihrem Herrn missfällt*, der sie für sich vorgesehen hatte*, lasse er sie loskaufen: er soll nicht Macht haben, sie an einen Ausländer* zu verkaufen, indem er sie treulos entlässt*.", footnotes: ["w. sie in den Augen ihres Herrn schlecht ist", "So lesen 6 hebr. Handschr. sowie einige alte Üs.; Mas. T.: die er nicht bestimmt hat, o. der sie nicht", "w. an ein fremdes Volk", "w. weil er treulos an ihr gehandelt hat, o. weil sein Kleid auf ihr ist, o. in seinem Kleid auf ihr\n℘ 5Mo 21,14"] },
      { number: 9, text: "Und falls er sie seinem Sohn bestimmt, soll er nach dem Töchterrecht an ihr handeln." },
      { number: 10, text: "Falls er sich noch eine andere nimmt, soll er ihre Nahrung, ihre Kleidung und den ehelichen Verkehr mit ihr nicht verkürzen*.", footnotes: ["℘ 1Kor 7,3"] },
      { number: 11, text: "Falls er aber diese drei Dinge nicht an ihr tut, soll sie umsonst* ausziehen, ohne Geld.", footnotes: ["w. ohne Entschädigung; o. unentgeltlich, d. h. ohne dass ein Loskauf erforderlich ist"] },
      { number: 12, text: "Wer einen Menschen so schlägt, dass er stirbt, muss getötet werden*.", heading: "Vergehen, die nicht gesühnt werden können", footnotes: ["℘ Kap. 20,13; 1Mo 9,5.6; 4Mo 35,30; Mt 5,21"] },
      { number: 13, text: "Hat er ihm aber nicht nachgestellt, sondern Gott hat es seiner Hand widerfahren lassen, dann werde ich dir einen Ort bestimmen, wohin er fliehen soll*.", footnotes: ["℘ 4Mo 35,6-15; 5Mo 19,1-10; Jos 20,1-9"] },
      { number: 14, text: "Doch wenn jemand an seinem Nächsten vermessen handelt, indem er ihn hinterlistig umbringt — von meinem Altar sollst du ihn wegnehmen, damit er stirbt*.", footnotes: ["℘ 5Mo 19,11-13; 1Kö 2,28-34; 2Kö 11,15; Spr 28,17"] },
      { number: 15, text: "Wer seinen Vater oder seine Mutter schlägt, muss getötet werden." },
      { number: 16, text: "Wer einen Menschen raubt, sei es, dass er ihn verkauft*, sei es, dass er in seiner Gewalt* gefunden wird, der muss getötet werden*.", footnotes: ["℘ 1Mo 37,28", "w. Hand", "℘ 5Mo 24,7"] },
      { number: 17, text: "Wer seinem Vater oder seiner Mutter flucht, muss getötet werden*.", footnotes: ["℘ 3Mo 20,9; 5Mo 21,18.21; Spr 20,20; Mt 15,4"] },
      { number: 18, text: "Wenn Männer miteinander streiten und einer den andern mit einem Stein oder mit einer Hacke* schlägt, so dass er zwar nicht stirbt, aber bettlägerig wird:", heading: "Entschädigung nach Körperverletzungen durch Mensch und Vieh", footnotes: ["o. Faust; o. Erdklumpen"] },
      { number: 19, text: "Falls er aufsteht und draußen an seinem Stab umhergeht, soll der Schläger straffrei bleiben. Nur muss er ihn für die Zeit seines Daheimsitzens* entschädigen und für seine völlige Heilung sorgen.", footnotes: ["o. für sein Untätigsein o. Versäumnis"] },
      { number: 20, text: "Wenn jemand seinen Sklaven oder seine Sklavin mit dem Stock schlägt, so dass er ihm unter der Hand stirbt, muss er gerächt werden." },
      { number: 21, text: "Nur falls er einen Tag oder zwei Tage am Leben bleibt, soll er nicht gerächt werden, denn er ist sein Geld." },
      { number: 22, text: "Wenn Männer sich raufen und dabei eine schwangere Frau stoßen, so dass ihr die Leibesfrucht abgeht, aber kein weiterer Schaden entsteht, so muss dem Schuldigen* eine Geldbuße auferlegt werden, je nachdem, wie viel ihm der Eheherr der Frau auferlegt, und er soll nach dem Ermessen von Schiedsrichtern* geben*.", footnotes: ["w. ihm", "w. durch Schiedsrichter", "℘ 5Mo 16,18"] },
      { number: 23, text: "Falls aber ein weiterer Schaden entsteht, so sollst du geben Leben um Leben," },
      { number: 24, text: "Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß," },
      { number: 25, text: "Brandmal um Brandmal, Wunde um Wunde, Strieme um Strieme*.", footnotes: ["℘ 3Mo 24,19.20; 5Mo 19,21; Mt 5,38; 7,2"] },
      { number: 26, text: "Wenn jemand in das Auge seines Sklaven oder in das Auge seiner Sklavin schlägt und es zerstört, soll er ihn zur Entschädigung für sein Auge als Freien entlassen." },
      { number: 27, text: "Auch falls er den Zahn seines Sklaven oder den Zahn seiner Sklavin ausschlägt, soll er ihn zur Entschädigung für seinen Zahn als Freien entlassen." },
      { number: 28, text: "Wenn ein Rind einen Mann oder eine Frau stößt, so dass sie sterben*, dann muss das Rind gesteinigt werden*, und sein Fleisch darf nicht gegessen werden; aber der Besitzer des Rindes soll straffrei bleiben.", footnotes: ["w. so dass er stirbt", "℘ 1Mo 9,5"] },
      { number: 29, text: "Falls jedoch das Rind schon vorher* stößig war, und sein Besitzer ist gewarnt worden, hat es aber nicht verwahrt: Falls es dann einen Mann oder eine Frau tötet, soll das Rind gesteinigt und auch sein Besitzer getötet werden.", footnotes: ["w. seit gestern und vorgestern"] },
      { number: 30, text: "Falls ihm aber ein Sühngeld* auferlegt wird, so soll er als Lösegeld für sein Leben alles geben, was ihm auferlegt wird.", footnotes: ["o. Lösegeld"] },
      { number: 31, text: "Auch falls es einen Sohn oder eine Tochter stößt, soll mit ihm nach dieser Rechtsordnung verfahren werden." },
      { number: 32, text: "Falls das Rind einen Sklaven oder eine Sklavin stößt, soll sein Besitzer* ihrem Herrn dreißig Schekel Silber geben*, das Rind aber soll gesteinigt werden.", footnotes: ["w. er", "℘ Mt 26,15"] },
      { number: 33, text: "Wenn jemand eine Zisterne öffnet* oder wenn jemand eine Zisterne gräbt und sie nicht zudeckt, und es fällt ein Rind oder ein Esel hinein,", heading: "Wiedergutmachung nach Schädigung von Besitz und Ehre", footnotes: ["Gemeint ist wohl: öffnet und offen lässt"] },
      { number: 34, text: "dann soll es der Besitzer der Zisterne erstatten*: Geld soll er seinem Besitzer zahlen*, aber das tote Tier soll ihm gehören.", footnotes: ["w. unversehrt machen\n℘ Kap. 22,3; 2Sam 12,6; Spr 6,31; Hes 33,15; Lk 19,8", "w. zurückgeben"] },
      { number: 35, text: "Wenn jemandes Rind das Rind seines Nächsten stößt, so dass es stirbt, dann sollen sie das lebende Rind verkaufen und den Erlös* teilen, und auch das tote sollen sie teilen.", footnotes: ["w. sein Geld"] },
      { number: 36, text: "War es aber bekannt, dass das Rind schon vorher* stößig war, und sein Besitzer hat es nicht verwahrt, so muss er ein Rind für das andere Rind erstatten*, das tote aber soll ihm gehören*.", footnotes: ["w. seit gestern und vorgestern", "w. unversehrt machen", "℘ 3Mo 24,18"] },
      { number: 37, text: "Wenn jemand ein Rind oder ein Schaf stiehlt und es schlachtet oder verkauft, soll er fünf Rinder erstatten für das eine Rind und vier Schafe für das eine Schaf.* —", footnotes: ["℘ Kap. 22,3; 2Sam 12,6; Spr 6,31; Hes 33,15; Lk 19,8"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Falls der Dieb beim Einbruch ertappt und geschlagen wird*, so dass er stirbt, so ist es ihm* keine Blutschuld.", footnotes: ["℘ Jer 2,34", "d. h. dem Schläger des Diebes"] },
      { number: 2, text: "Falls aber die Sonne über ihm aufgegangen ist, ist es ihm* Blutschuld. Er* muss zurückerstatten. Falls er nichts hat, soll er für den Wert des von ihm Gestohlenen verkauft werden.", footnotes: ["d. h. dem Schläger des Diebes", "d. i. der Dieb"] },
      { number: 3, text: "Falls das Gestohlene lebend in seiner Hand gefunden wird, es sei ein Rind oder ein Esel oder ein Schaf, so soll er das Doppelte erstatten*.", footnotes: ["w. unversehrt machen\n℘ Kap. 21,34.37; Jes 40,2"] },
      { number: 4, text: "Wenn jemand ein Feld oder einen Weinberg abweiden lässt* und seinem Vieh dabei freien Lauf lässt, so dass es auf dem Feld eines anderen weidet, dann soll er vom Besten seines Feldes und vom Besten seines Weinbergs erstatten*.", footnotes: ["o. anzündet", "w. unversehrt machen"] },
      { number: 5, text: "Wenn Feuer ausbricht und Dorngestrüpp erreicht, so dass ein Garbenhaufen oder das stehende Getreide oder das Feld verzehrt wird, so muss der zurückerstatten, der den Brand angezündet hat. *", footnotes: ["℘ V. 6-14: 3Mo 5,20-24"] },
      { number: 6, text: "Wenn jemand seinem Nächsten Geld oder Gegenstände in Verwahrung gibt, und es wird aus dem Haus dieses Mannes gestohlen — falls der Dieb gefunden wird, soll er das Doppelte erstatten*.", footnotes: ["w. unversehrt machen"] },
      { number: 7, text: "Falls jedoch der Dieb nicht gefunden wird, so soll der Besitzer des Hauses vor Gott treten, damit man erfährt, ob er nicht seine Hand nach der Habe seines Nächsten ausgestreckt hat." },
      { number: 8, text: "Bei jedem Fall von Veruntreuung* an Rind, Esel, Schaf oder Kleidung, bei allem Verlorenen, von dem er* sagt: Das ist es!, soll die Sache der beiden vor Gott kommen. Wen Gott schuldig erklärt, der soll seinem Nächsten das Doppelte erstatten*.", footnotes: ["w. bei jeder Sache eines Vergehens", "d. i. der Eigentümer", "w. unversehrt machen"] },
      { number: 9, text: "Wenn jemand seinem Nächsten einen Esel oder ein Rind oder ein Schaf oder irgendein Tier in Verwahrung gibt, und es stirbt oder bricht sich einen Knochen oder wird weggeführt, und niemand sieht es," },
      { number: 10, text: "dann soll ein Schwur beim HERRN zwischen ihnen beiden sein*, ob er nicht seine Hand nach der Habe seines Nächsten ausgestreckt hat. Dann soll sein Besitzer* es annehmen, und jener braucht nichts zu erstatten*.", footnotes: ["w. geschehen\n℘ Hebr 6,16", "d. i. der Besitzer des Tieres", "w. unversehrt machen"] },
      { number: 11, text: "Falls es ihm jedoch wirklich gestohlen worden ist, soll er es seinem Besitzer erstatten." },
      { number: 12, text: "Falls es aber zerrissen worden ist, soll er es als Beweis herbeibringen; er braucht das Zerrissene nicht zu erstatten*.", footnotes: ["w. unversehrt machen\n℘ 1Mo 31,39"] },
      { number: 13, text: "Wenn jemand von seinem Nächsten ein Stück Vieh leiht, und es bricht sich einen Knochen oder stirbt — falls sein Besitzer nicht dabei war, muss er es erstatten*;", footnotes: ["w. unversehrt machen"] },
      { number: 14, text: "falls sein Besitzer dabei war, braucht er es nicht zu erstatten*. Falls es gemietet war, geht es auf den Mietpreis*.", footnotes: ["w. unversehrt machen", "o. Falls er ein Lohnarbeiter war, geht es auf seinen Lohn"] },
      { number: 15, text: "Wenn jemand eine Jungfrau betört, die nicht verlobt* ist, und liegt bei ihr, muss er sie sich gegen das Heiratsgeld zur Frau erwerben*.", footnotes: ["d. h. die noch nicht zur Ehefrau erworben ist", "℘ 1Mo 34,12; 5Mo 22,29"] },
      { number: 16, text: "Falls sich ihr Vater hartnäckig weigert, sie ihm zu geben, soll er Geld abwiegen nach dem Heiratsgeld für Jungfrauen." },
      { number: 17, text: "Eine Zauberin sollst du nicht am Leben lassen*. —", heading: "Todeswürdige Vergehen", footnotes: ["℘ 3Mo 20,6.27; 5Mo 18,10-14; 1Sam 28,3.7.9"] },
      { number: 18, text: "Jeder, der bei einem Tier liegt, muss getötet werden*. —", footnotes: ["℘ 3Mo 18,23; 5Mo 27,21"] },
      { number: 19, text: "Wer den Göttern opfert*, außer dem HERRN allein, soll mit dem Bann belegt werden*.", footnotes: ["w. zum Opfer schlachtet", "℘ Kap. 20,3; 34,15.16; 3Mo 17,7; 4Mo 25,1-5; 5Mo 13,2-16; 17,2-7; 2Kö 23,20; 2Chr 15,13"] },
      { number: 20, text: "Den Fremden sollst du weder unterdrücken noch bedrängen, denn Fremde seid ihr im Land Ägypten gewesen*.", heading: "Schutz der Schwachen", footnotes: ["℘ Kap. 23,9; 5Mo 10,18; Mal 3,5"] },
      { number: 21, text: "Keine Witwe oder Waise dürft ihr bedrücken*.", footnotes: ["℘ 5Mo 10,18; 24,17-22; Hi 6,27; Ps 146,9; Jes 1,17.23; Sach 7,10"] },
      { number: 22, text: "Falls du sie in irgendeiner Weise bedrückst, dann werde ich, wenn sie wirklich zu mir schreien muss*, ihr Geschrei gewiss erhören*,", footnotes: ["℘ Jak 5,4; 5Mo 15,9", "℘ Hi 34,28; Ps 10,14; 34,7"] },
      { number: 23, text: "und mein Zorn wird entbrennen, und ich werde euch mit dem Schwert umbringen, so dass eure Frauen Witwen und eure Kinder Waisen werden*. —", footnotes: ["℘ Spr 22,23; Kla 5,3"] },
      { number: 24, text: "Falls du einem aus meinem Volk, dem Elenden bei dir, Geld leihst, dann sei gegen ihn nicht wie ein Gläubiger*; ihr sollt ihm keinen Zins auferlegen*. —", footnotes: ["w. wie einer, der um Zins Geld ausleiht", "℘ 3Mo 25,35-37; 5Mo 23,21; Neh 5,7"] },
      { number: 25, text: "Falls du wirklich den Mantel* deines Nächsten zum Pfand nimmst, sollst du ihm diesen zurückgeben, ehe die Sonne untergeht*;", footnotes: ["w. das Obergewand; es wurde als Decke benutzt; vgl. die Anm. zu Kap. 3,22", "℘ Hes 18,7"] },
      { number: 26, text: "denn er ist seine einzige Decke, seine Umhüllung für seine Haut. Worin soll er sonst liegen? Wenn er dann zu mir schreit, wird es geschehen, dass ich ihn erhören werde*, denn ich bin gnädig*. —", footnotes: ["℘ Hi 34,28; Ps 10,14; 34,7", "℘ 5Mo 24,10-15; Am 2,8"] },
      { number: 27, text: "Gott sollst du nicht lästern, und einem Fürsten in deinem Volk sollst du nicht fluchen*.", heading: "Pflege der Gottesgemeinschaft", footnotes: ["℘ 2Sam 16,5; 1Kö 2,8.9; Pred 10,20; Apg 23,5"] },
      { number: 28, text: "Mit der Fülle deines Getreides und dem Ausfluss deiner Kelter* sollst du nicht zögern*. — Den Erstgeborenen unter deinen Söhnen sollst du mir geben.", footnotes: ["o. Mit deiner Fülle an Wein und deinem Überfluss an Öl; w. Mit deiner Fülle und deinem Ausfluss. — Gemeint ist wohl die rechtzeitige Abgabe der ersten Erzeugnisse aus der Landwirtschaft und dem Weinbau.", "℘ Kap. 23,16.19"] },
      { number: 29, text: "Ebenso sollst du es mit deinem Rind und deinen Schafen halten*; sieben Tage mag es bei seiner Mutter bleiben, am achten Tag sollst du es mir geben*. —", footnotes: ["℘ Kap. 13,2.11-16; 5Mo 15,19", "℘ 3Mo 22,27"] },
      { number: 30, text: "Heilige Menschen sollt ihr mir sein*: so dürft ihr Fleisch, das auf dem Feld zerrissen worden ist, nicht essen; den Hunden sollt ihr es vorwerfen*.", footnotes: ["℘ 3Mo 11,44", "℘ 3Mo 7,24; 17,15; 22,8; 5Mo 14,21; Hes 4,14"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Du sollst kein falsches Gerücht aufnehmen*. Du sollst deine Hand nicht dem Schuldigen reichen, um als falscher Zeuge aufzutreten*.", heading: "Gemeinschaftsgemäßes Verhalten und Feindesliebe", footnotes: ["℘ 1Mo 39,17", "w. um Zeuge der Gewalttat zu sein\n℘ Kap. 20,16; 3Mo 19,16; 5Mo 19,16-20"] },
      { number: 2, text: "Du sollst der Menge nicht folgen zum Bösen*. Und du sollst bei einem Rechtsstreit nicht antworten, indem du dich nach der Mehrheit richtest* und so das Recht beugst*.", footnotes: ["℘ Jos 24,15; 1Sam 15,24; Lk 23,24", "Die Wendung »sich richten nach« bedeutet eigentlich »jemandem auf einem Abweg folgen«.", "℘ 5Mo 1,17; Mk 15,15"] },
      { number: 3, text: "Auch den Geringen sollst du in seinem Rechtsstreit nicht begünstigen*. —", footnotes: ["w. ehren, o. auszeichnen; wie 3Mo 19,15\n℘ 3Mo 19,15; Ps 82,3.4; Spr 18,5; 22,22; Jes 10,1.2; Am 5,12"] },
      { number: 4, text: "Wenn du das Rind deines Feindes oder seinen Esel umherirrend antriffst, sollst du sie ihm auf jeden Fall zurückbringen*.", footnotes: ["℘ 5Mo 22,1; Lk 6,27"] },
      { number: 5, text: "Wenn du den Esel deines Hassers unter seiner Last zusammengebrochen siehst, dann lass ihn nicht ohne Beistand; du sollst ihn mit ihm zusammen aufrichten*. —", footnotes: ["so mit LXX; Mas. T.: Du musst ihn auf jeden Fall bei ihm lassen. Nimmt man ein geringes Abschreibversehen an, so könnte es ursprünglich geheißen haben: Du musst ihm auf jeden Fall helfen."] },
      { number: 6, text: "Du sollst das Recht eines Armen deines Volkes* in seinem Rechtsstreit nicht beugen*.", footnotes: ["w. das Recht deines Armen", "℘ 3Mo 19,15; Ps 82,3.4; Spr 18,5; 22,22; Jes 10,1.2; Am 5,12"] },
      { number: 7, text: "Von einer betrügerischen Angelegenheit* halte dich fern*. Und den Unschuldigen und Gerechten sollst du nicht umbringen*, denn ich werde dem Schuldigen nicht recht geben*.", footnotes: ["o. Von einem Lügenwort", "℘ Spr 17,15; Jes 5,20-23", "℘ Ps 94,21", "℘ Spr 11,21"] },
      { number: 8, text: "Ein Bestechungsgeschenk nimm nicht an; denn das Bestechungsgeschenk macht Sehende blind und verdreht die Sache* der Gerechten*.", footnotes: ["o. die Worte", "℘ 5Mo 16,19; 1Sam 8,3; Spr 17,23; Pred 7,7; Jes 33,15; Mt 28,12-15"] },
      { number: 9, text: "Und den Fremden sollst du nicht bedrücken. Ihr wisst ja selbst, wie es dem Fremden zumute ist, denn Fremde seid ihr im Land Ägypten gewesen*.", footnotes: ["℘ Kap. 22,20; Hes 22,29"] },
      { number: 10, text: "Sechs Jahre sollst du dein Land besäen und seinen Ertrag einsammeln.", heading: "Sabbatjahr und Sabbat" },
      { number: 11, text: "Aber im siebten sollst du es brachliegen lassen* und nicht bestellen*, damit die Armen deines Volkes davon essen*. Und was sie übrig lassen*, mögen die Tiere des Feldes fressen*. Ebenso sollst du es mit deinem Weinberg und mit deinem Ölbaumgarten halten.", footnotes: ["℘ Neh 10,32", "o. ruhen lassen", "℘ 5Mo 15,11", "w. Und ihren Rest", "℘ 3Mo 25,3-7"] },
      { number: 12, text: "Sechs Tage sollst du deine Arbeiten verrichten. Aber am siebten Tag sollst du ruhen, damit dein Rind und dein Esel ausruhen und der Sohn deiner Magd und der Fremde Atem schöpfen*.", footnotes: ["℘ Kap. 20,8-11; Mk 2,27"] },
      { number: 13, text: "Habt acht auf euch in allem*, was ich euch gesagt habe! Den Namen anderer Götter aber dürft ihr nicht bekennen; er soll in deinem Mund nicht gehört werden*.", footnotes: ["℘ 5Mo 6,1-3; Jos 22,5; 1Chr 28,8", "℘ Jos 23,7; Sach 13,2"] },
      { number: 14, text: "*Dreimal im Jahr sollst du mir ein Fest feiern*.", heading: "Die drei großen Jahresfeste", footnotes: ["℘ V. 14-19: Kap. 34,18-26; 5Mo 16,1-17", "℘ 1Kö 9,25; Hes 46,9"] },
      { number: 15, text: "Das Fest der ungesäuerten Brote sollst du halten*: Sieben Tage sollst du ungesäuertes Brot essen, wie ich dir geboten habe*, zur festgesetzten Zeit im Monat Abib*, denn in diesem bist du aus Ägypten gezogen*. Und man soll nicht mit leeren Händen vor meinem Angesicht erscheinen*.", footnotes: ["℘ 3Mo 23,6", "℘ Kap. 12,15; Lk 2,41", "d. h. Ährenmonat", "℘ Kap. 13,4", "℘ Mi 6,6"] },
      { number: 16, text: "Ferner das Fest der Ernte, der Erstlinge vom Ertrag deiner Arbeit*, dessen, was du auf dem Feld säen wirst*; und das Fest des Einsammelns am Ende des Jahres*, wenn du deinen Arbeitsertrag vom Feld einsammelst*.", footnotes: ["℘ 4Mo 28,26", "℘ 3Mo 23,9-21", "d. h. das Fest der Trauben-, Oliven- und Obsternte, die von Juli bis September stattfand", "℘ 3Mo 23,39-43"] },
      { number: 17, text: "Dreimal im Jahr soll alles unter euch, was männlich ist, vor dem Angesicht des Herrn, HERRN, erscheinen*.", footnotes: ["℘ Ps 42,3"] },
      { number: 18, text: "Du darfst das Blut meines Schlachtopfers nicht zusammen mit Gesäuertem darbringen; und das Fett meines Festopfers soll nicht über Nacht bleiben bis zum nächsten Morgen*.", heading: "Opferregelungen", footnotes: ["℘ Kap. 12,10"] },
      { number: 19, text: "Das Erste* von den Erstlingen deines Ackers sollst du in das Haus des HERRN, deines Gottes, bringen.* Du sollst ein Böckchen nicht in der Milch seiner Mutter kochen*.", footnotes: ["d. h. Das Beste", "℘ Kap. 22,28; 3Mo 23,10; 4Mo 15,21; 18,13; 5Mo 26,10; Neh 10,36; Spr 3,9; Hes 44,30; 48,13.14", "℘ 5Mo 14,21"] },
      { number: 20, text: "Siehe, ich sende einen Engel vor dir her*, damit er dich auf dem Weg bewahrt und dich an den Ort bringt, den ich für dich bereitet habe*.", heading: "Schlusswort: Warnung und Verheißung", footnotes: ["℘ Kap. 32,34; 33,2; Sach 12,8", "℘ 4Mo 20,16; Ps 91,11.12; Jes 63,9"] },
      { number: 21, text: "Hüte dich vor ihm, höre auf seine Stimme und widersetze dich ihm nicht*! Denn er wird euer Vergehen nicht vergeben*, denn mein Name ist in ihm*.", footnotes: ["so mit geringfügiger Änderung; Mas. T.: verbittere ihn nicht; LXX: sei ihm nicht ungehorsam\n℘ 4Mo 14,11", "℘ 4Mo 14,35; Jos 24,19; Mal 3,1-3", "℘ Ri 13,18; Jes 9,5"] },
      { number: 22, text: "Doch wenn du willig auf seine Stimme hörst und alles tust, was ich sage, dann werde ich Feind deiner Feinde sein und deine Bedränger bedrängen*.", footnotes: ["℘ 1Mo 12,3; 4Mo 24,8; Ps 35,1"] },
      { number: 23, text: "Denn mein Engel wird vor dir hergehen* und wird dich bringen zu den Amoritern, Hetitern, Perisitern, Kanaanitern, Hewitern und Jebusitern*; und ich werde sie austilgen*.", footnotes: ["℘ 1Mo 24,7; Jos 5,13-15", "℘ 1Mo 15,21", "℘ 5Mo 9,3; Jos 24,8"] },
      { number: 24, text: "Du sollst* dich vor ihren Göttern nicht niederwerfen* und ihnen nicht dienen*, und du sollst nicht nach ihren Taten tun*, sondern du sollst sie* ganz und gar niederreißen und ihre Gedenksteine* völlig zertrümmern*.", footnotes: ["o. Wenn mein Engel vor dir hergehen wird . . . und ich sie austilgen werde, 24 dann sollst du", "d. i. um deine Ehrfurcht zu bezeugen; dasselbe Wort wie »anbeten«", "℘ Kap. 20,3.5; 4Mo 25,2; 2Chr 25,14", "℘ 3Mo 18,3; 5Mo 12,30; 2Kö 17,8.11.15.35", "d. h. die Gottesbilder", "hebr. mazzebot; das sind aufrecht hingestellte Steine, die kultisch verehrt wurden", "℘ Kap. 34,13; 5Mo 7,5; 2Kö 18,4; 2Chr 14,2; Hos 10,2"] },
      { number: 25, text: "Und ihr sollt dem HERRN, eurem Gott, dienen*: So wird er dein Brot und dein Wasser segnen, und ich werde alle Krankheit aus deiner Mitte entfernen*.", footnotes: ["℘ 5Mo 6,13", "℘ Kap. 15,26"] },
      { number: 26, text: "Keine Frau in deinem Land wird eine Fehlgeburt haben oder unfruchtbar sein*; die Zahl deiner Tage werde ich erfüllen*.", footnotes: ["℘ 5Mo 7,14", "℘ Hi 5,26"] },
      { number: 27, text: "Meinen Schrecken werde ich vor dir hersenden* und alle Völker, zu denen du kommst, in Verwirrung bringen, und ich werde dir den Rücken all deiner Feinde zukehren*.", footnotes: ["℘ 1Mo 35,5", "℘ 5Mo 2,25"] },
      { number: 28, text: "Auch werde ich Angst* vor dir hersenden*, damit sie die Hewiter, Kanaaniter und Hetiter vor dir vertreibt*.", footnotes: ["o. Hornissen; o. Wespen", "℘ 5Mo 7,20; 33,27; Jos 24,12", "℘ 3Mo 19,15; Ps 82,3.4; Spr 18,5; 22,22; Jes 10,1.2; Am 5,12"] },
      { number: 29, text: "Nicht in einem Jahr werde ich sie vor dir vertreiben*, damit das Land nicht eine Öde wird und die wilden Tiere zu deinem Schaden überhandnehmen*.", footnotes: ["℘ Kap. 34,24", "w. die Tiere des Feldes viel werden gegen dich\n℘ 5Mo 7,22"] },
      { number: 30, text: "Nach und nach werde ich sie vor dir vertreiben, bis du so fruchtbar geworden bist*, dass du das Land in Besitz nehmen kannst.", footnotes: ["d. h. zahlreich bist"] },
      { number: 31, text: "Und ich werde deine Grenze festsetzen: Sie soll reichen vom Schilfmeer bis an das Meer der Philister und von der Wüste bis an den Strom*, denn ich werde die Bewohner des Landes in deine Hand geben, so dass du sie vor dir vertreiben wirst*.", footnotes: ["d. h. den Euphrat\n℘ 1Mo 15,18; 4Mo 34,2-12; 5Mo 11,24; 2Chr 9,26; Ps 72,8.11", "℘ 5Mo 6,19; Jos 2,24; 13,6"] },
      { number: 32, text: "Du sollst mit ihnen und mit ihren Göttern keinen Bund schließen*.", footnotes: ["℘ Kap. 34,12.15; 5Mo 7,1-4; Jos 9,7"] },
      { number: 33, text: "Sie sollen nicht in deinem Land wohnen bleiben, damit sie dich nicht zur Sünde gegen mich verführen; denn dann würdest du ihren Göttern dienen, und es würde dir zu einer Falle sein*.", footnotes: ["o. damit sie dich nicht . . . verführen, dass du ihren Göttern dienst. Denn es würde dir zu einem Stellholz sein (d. i. eine Vogelfalle)\n℘ 5Mo 20,18; Jos 10,40; 23,13; Ri 2,2.3; Ps 106,36"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Und der HERR sprach zu Mose: Steig zum HERRN herauf, du und Aaron, Nadab und Abihu* und siebzig von den Ältesten Israels*, und betet an* von ferne!", heading: "Bundesschließung am Sinai", footnotes: ["℘ Kap. 6,23", "℘ V. 9; 4Mo 11,16; Hes 8,11", "w. werft euch nieder"] },
      { number: 2, text: "Aber Mose allein soll zum HERRN herantreten, sie aber dürfen nicht herantreten, und das Volk soll nicht mit ihm heraufsteigen*.", footnotes: ["℘ Kap. 19,12.21.24"] },
      { number: 3, text: "Darauf kam Mose und erzählte dem Volk alle Worte des HERRN und alle Rechtsbestimmungen. Und das ganze Volk antwortete mit einer Stimme und sagte*: Alle Worte, die der HERR geredet hat, wollen wir tun*.", footnotes: ["w. und sie sagten", "℘ Kap. 19,8; 2Chr 15,14.15"] },
      { number: 4, text: "Da schrieb Mose alle Worte des HERRN auf*. Am nächsten Morgen aber machte er sich früh auf und errichtete einen Altar* unten am Berg und zwölf Denksteine nach den zwölf Stämmen Israels*.", footnotes: ["℘ Kap. 34,27; 5Mo 31,9.24; Jos 24,26; Neh 10,1", "℘ Kap. 20,24.25; 1Mo 12,7.8", "℘ Kap. 28,21; Jos 4,5.8; 1Kö 18,31"] },
      { number: 5, text: "Dann sandte er junge Männer aus den Söhnen Israel hin; die brachten Brandopfer dar und schlachteten Stiere als Heilsopfer* für den HERRN*.", footnotes: ["o. Friedensopfer; o. Gemeinschaftsopfer; o. Abschlussopfer", "℘ Ps 50,5"] },
      { number: 6, text: "Und Mose nahm die Hälfte des Blutes und tat es in Schalen, die andere Hälfte des Blutes aber sprengte er an den Altar." },
      { number: 7, text: "Und er nahm das Buch des Bundes und las es vor den Ohren des Volkes. Und sie sagten: Alles, was der HERR geredet hat, wollen wir tun und gehorchen*.", footnotes: ["℘ Kap. 19,8; 2Chr 15,14.15"] },
      { number: 8, text: "Darauf nahm Mose das Blut, besprengte damit das Volk und sagte: Siehe, das Blut des Bundes, den der HERR auf all diese Worte mit euch geschlossen hat!*", footnotes: ["℘ 5Mo 5,2; 1Kö 8,21; Hes 16,8; Hag 2,5; Mt 26,28; Gal 4,24; Hebr 9,20"] },
      { number: 9, text: "Da stiegen Mose und Aaron, Nadab und Abihu und siebzig von den Ältesten Israels* hinauf,", heading: "Priester und Älteste auf dem Sinai vor Gott", footnotes: ["℘ Ri 13,22; 1Kö 22,19; Jes 6,1"] },
      { number: 10, text: "und sie sahen den Gott Israels. Und unter seinen Füßen war es wie Arbeit in Saphirplatten und wie der Himmel selbst an Klarheit*.", footnotes: ["℘ Hes 1,26-28"] },
      { number: 11, text: "Gegen die Edlen der Söhne Israel aber streckte er seine Hand nicht aus*, sondern sie schauten Gott und aßen und tranken.", footnotes: ["℘ 1Mo 32,31"] },
      { number: 12, text: "Und der HERR sprach zu Mose: Steig zu mir herauf auf den Berg und sei dort, damit ich dir die steinernen Tafeln*, das Gesetz und das Gebot gebe, das ich geschrieben habe, um sie zu unterweisen!*", heading: "Mose auf dem Berg zum Empfang der Gesetzestafeln", footnotes: ["℘ Kap. 31,18; 32,1.15; 5Mo 5,22; 2Kor 3,3", "℘ Neh 9,14; Ps 19,12"] },
      { number: 13, text: "Da machte Mose sich mit seinem Diener Josua* auf, und Mose stieg auf den Berg Gottes*.", footnotes: ["℘ Kap. 17,9; 4Mo 11,28", "℘ Kap. 19,3"] },
      { number: 14, text: "Zu den Ältesten aber sagte er: Wartet hier auf uns, bis wir zu euch zurückkehren! Siehe, Aaron und Hur* sind ja bei euch; wer eine Rechtssache hat, trete zu ihnen!", footnotes: ["℘ Kap. 17,12"] },
      { number: 15, text: "Als nun Mose auf den Berg stieg, bedeckte die Wolke den Berg*.", footnotes: ["℘ Kap. 19,20"] },
      { number: 16, text: "Und die Herrlichkeit des HERRN ließ sich auf dem Berg Sinai nieder, und die Wolke* bedeckte ihn sechs Tage; und am siebten Tag rief er Mose mitten aus der Wolke heraus zu.", footnotes: ["℘ Kap. 16,10; Mt 17,5"] },
      { number: 17, text: "Die Erscheinung der Herrlichkeit des HERRN aber war vor den Augen der Söhne Israel wie ein verzehrendes Feuer auf dem Gipfel des Berges*.", footnotes: ["℘ Kap. 19,11; 5Mo 4,24.36; 2Sam 22,9; Hes 1,27; Hebr 12,18.29"] },
      { number: 18, text: "Mose jedoch ging mitten in die Wolke hinein und stieg auf den Berg; und Mose war vierzig Tage und vierzig Nächte auf dem Berg*.", footnotes: ["℘ Kap. 32,1; 34,28; 5Mo 5,31; 1Kö 19,8"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "*Und der HERR redete zu Mose und sprach:", heading: "Heiligtum: Freiwillige Gaben", footnotes: ["℘ Kap. 35,4-29"] },
      { number: 2, text: "Rede zu den Söhnen Israel und sage ihnen, sie sollen ein Hebopfer für mich nehmen! Von jedem, dessen Herz ihn antreibt, sollt ihr mein Hebopfer nehmen*.", footnotes: ["℘ 1Chr 29,5; 2Kor 8,12"] },
      { number: 3, text: "Dies aber ist das Hebopfer, das ihr von ihnen nehmen sollt: Gold, Silber und Bronze," },
      { number: 4, text: "violetter und roter Purpur, Karmesinstoff, Byssus* und Ziegenhaar,", footnotes: ["d. i. ein feines Gewebe aus Ägypten; wohl feines Leinen"] },
      { number: 5, text: "rot gefärbte Widderfelle, Häute von Delfinen* und Akazienholz;", footnotes: ["w. Tachaschhäute. — Wahrscheinlich Häute des großen Tümmlers, einer Delfinart; nach anderen: Dachsfelle, o. Seekuhhäute, o. weich gegerbtes Leder"] },
      { number: 6, text: "Öl für den Leuchter, Balsamöle* für das Salböl und für das wohlriechende Räucherwerk;", footnotes: ["o. Olivenöl für den Leuchter, wohlriechende Stoffe"] },
      { number: 7, text: "Onyxsteine* und andere Edelsteine zum Einsetzen für das Efod und die Brusttasche*.", footnotes: ["o. Karneolsteine\n℘ Kap. 28,9; 1Mo 2,12", "o. den Brustschild"] },
      { number: 8, text: "Und sie sollen mir ein Heiligtum machen*, damit ich in ihrer Mitte wohne*.", footnotes: ["℘ Kap. 15,17; 1Chr 22,19; Hebr 9,1", "℘ Kap. 29,45.46; 1Kö 6,13; Hes 37,26-28; 43,7-9"] },
      { number: 9, text: "Nach allem, was ich dir zeige, nämlich dem Urbild der Wohnung und dem Urbild all ihrer Geräte, danach sollt ihr es machen*.", footnotes: ["℘ V. 40; 1Chr 28,11-19"] },
      { number: 10, text: "*So sollen sie nun* eine Lade* aus Akazienholz machen*: zweieinhalb Ellen sei ihre Länge, anderthalb Ellen ihre Breite und anderthalb Ellen ihre Höhe.", heading: "Heiligtum: Bundeslade mit Deckplatte", footnotes: ["℘ Kap. 37,1-9", "Eine alte hebr. Handschr. und LXX lesen: So sollst du nun", "w. einen Kasten; wohl als eine Art Thronsockel zu verstehen", "℘ Kap. 31,7; 5Mo 10,1.3; Offb 11,19"] },
      { number: 11, text: "Die sollst du mit reinem Gold überziehen — von innen und außen sollst du sie überziehen — und auf ihr ringsum eine goldene Kante anbringen*.", footnotes: ["℘ Kap. 30,3; Hebr 9,4"] },
      { number: 12, text: "Gieße für sie auch vier goldene Ringe und befestige sie an ihren vier Füßen, und zwar zwei Ringe an ihrer einen Längsseite und zwei Ringe an ihrer anderen Längsseite!" },
      { number: 13, text: "Und du sollst Stangen aus Akazienholz anfertigen und sie mit Gold überziehen." },
      { number: 14, text: "Diese Stangen stecke in die Ringe an den Seiten der Lade, damit man die Lade mit ihnen tragen kann*!", footnotes: ["w. um . . . zu tragen\n℘ 1Chr 15,15"] },
      { number: 15, text: "Die Stangen sollen in den Ringen der Lade bleiben, sie dürfen nicht von ihr* entfernt werden*.", footnotes: ["Die syr. Üs. liest: aus ihnen", "℘ 1Kö 8,8"] },
      { number: 16, text: "In die Lade aber lege das Zeugnis*, das ich dir geben werde*.", footnotes: ["o. Mahnzeichen; vgl. die Anm. zu Kap. 16,34", "℘ 5Mo 10,5; 1Kö 8,9"] },
      { number: 17, text: "Dann sollst du eine Deckplatte* aus reinem Gold herstellen; zweieinhalb Ellen sei ihre Länge und anderthalb Ellen ihre Breite.", footnotes: ["o. Sühneplatte. — Das hebr. Wort ist von einem Zeitwort abgeleitet, das ursprünglich »zudecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, versöhnen« bedeutet.\n℘ Kap. 35,12; Röm 3,25"] },
      { number: 18, text: "Und mache zwei goldene Cherubim*; in getriebener Arbeit sollst du sie machen an den beiden Enden der Deckplatte*,", footnotes: ["℘ 2Chr 3,10; Hes 10,2.3", "℘ Hebr 9,5"] },
      { number: 19, text: "und zwar sollst du einen Cherub am Ende hier und einen Cherub am Ende dort machen. Aus einem Stück mit der Deckplatte* sollt ihr die Cherubim machen an ihren beiden Enden.", footnotes: ["o. Sühneplatte. — Das hebr. Wort ist von einem Zeitwort abgeleitet, das ursprünglich »zudecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, versöhnen« bedeutet."] },
      { number: 20, text: "Und die Cherubim sollen die Flügel nach oben ausbreiten, die Deckplatte* mit ihren Flügeln überdeckend, während ihre Gesichter einander zugewandt* sind. Der Deckplatte* sollen die Gesichter der Cherubim zugewandt sein*.", footnotes: ["o. Sühneplatte. — Das hebr. Wort ist von einem Zeitwort abgeleitet, das ursprünglich »zudecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, versöhnen« bedeutet.", "w. während ihre Gesichter jedes zu seinem Bruder gewandt", "w. während ihre Gesichter jedes zu seinem Bruder gewandt", "℘ 1Kö 6,23-27; 1Chr 28,18; 2Chr 3,10-13"] },
      { number: 21, text: "Lege die Deckplatte* oben auf die Lade*! In die Lade aber sollst du das Zeugnis* legen, das ich dir geben werde*.", footnotes: ["o. Sühneplatte. — Das hebr. Wort ist von einem Zeitwort abgeleitet, das ursprünglich »zudecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, versöhnen« bedeutet.", "℘ Kap. 26,34; 3Mo 16,13; 1Kö 8,9", "o. Mahnzeichen; vgl. die Anm. zu Kap. 16,34", "℘ 5Mo 10,5; 1Kö 8,9"] },
      { number: 22, text: "Und dort werde ich dir begegnen* und von der Deckplatte* herab, zwischen den beiden Cherubim hervor*, die auf der Lade des Zeugnisses* sind, alles zu dir reden, was ich dir für die Söhne Israel auftragen werde*.", footnotes: ["℘ Kap. 29,42; 4Mo 17,19", "o. Sühneplatte. — Das hebr. Wort ist von einem Zeitwort abgeleitet, das ursprünglich »zudecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, versöhnen« bedeutet.", "℘ 1Sam 4,4; 2Sam 6,2; 2Kö 19,15; Ps 80,2", "o. Mahnzeichen; vgl. die Anm. zu Kap. 16,34", "℘ Kap. 30,6.36; 3Mo 1,1; 16,2; 4Mo 7,89; Hes 43,6"] },
      { number: 23, text: "*Und du sollst einen Tisch aus Akazienholz machen*; zwei Ellen sei seine Länge, eine Elle seine Breite und anderthalb Ellen seine Höhe.", heading: "Heiligtum: Schaubrottisch", footnotes: ["℘ Kap. 37,10-16", "℘ Kap. 31,8; 1Kö 7,48; Hebr 9,2"] },
      { number: 24, text: "Den überzieh mit reinem Gold und bringe an ihm ringsum eine goldene Kante an*!", footnotes: ["℘ Kap. 30,3"] },
      { number: 25, text: "Mache an ihm ringsum eine Leiste von einer Handbreit und bringe an seiner Leiste ringsum eine goldene Kante an!" },
      { number: 26, text: "Mache für ihn auch vier goldene Ringe und befestige die Ringe an den vier Seiten seiner vier Füße*!", footnotes: ["o. über den vier Ecken, die an seinen vier Füßen sind"] },
      { number: 27, text: "Dicht an der Leiste sollen die Ringe sein als Ösen* für die Stangen, damit man den Tisch tragen kann*.", footnotes: ["w. als Häuser", "w. um den Tisch zu tragen"] },
      { number: 28, text: "Die Stangen aber sollst du aus Akazienholz machen und sie mit Gold überziehen, und der Tisch soll daran getragen werden." },
      { number: 29, text: "Fertige auch seine Schüsseln, seine Schalen, seine Kannen* und seine Opferschalen an, mit denen man Trankopfer ausgießt! Aus reinem Gold sollst du sie herstellen*.", footnotes: ["o. Trinkschalen", "℘ 1Kö 7,50"] },
      { number: 30, text: "Auf den Tisch aber sollst du beständig vor mein Angesicht Schaubrote* legen*.", footnotes: ["w. Brot des Angesichts. — D. h. Brot, das immer wieder vor dem Angesicht des HERRN im Heiligtum niedergelegt wurde.", "℘ Kap. 35,13; 39,36; 3Mo 24,5-8; 1Sam 21,5.7; 2Chr 2,3"] },
      { number: 31, text: "*Und du sollst einen Leuchter aus reinem Gold machen*. In getriebener Arbeit soll der Leuchter gemacht werden, sein Fuß* und seine Schaftröhre. Seine Kelche, Knäufe und Blüten sollen aus einem Stück mit ihm sein.", heading: "Heiligtum: Leuchter", footnotes: ["℘ Kap. 37,17-24; 4Mo 8,1-4", "℘ Kap. 31,8; 1Kö 7,49; Sach 4,2", "w. sein Schenkel. — Eine Handschr. liest: seine Schenkel und seine Schaftröhren"] },
      { number: 32, text: "Sechs Arme sollen von seinen beiden Seiten ausgehen; drei Arme des Leuchters aus seiner einen Seite und drei Arme des Leuchters aus seiner andern Seite." },
      { number: 33, text: "Drei Kelche in der Form von Mandelblüten seien an dem einen Arm, aus Knauf und Blüte bestehend, und drei Kelche in der Form von Mandelblüten am nächsten Arm, aus Knauf und Blüte bestehend; so sei es an den sechs Armen, die vom* Leuchter ausgehen.", footnotes: ["d. h. vom Schaft des Leuchters"] },
      { number: 34, text: "Am Leuchter aber sollen vier Kelche sein in der Form von Mandelblüten, aus seinen Knäufen und Blüten bestehend;" },
      { number: 35, text: "und zwar ein Knauf unter den ersten zwei von ihm ausgehenden Armen, ein Knauf unter den nächsten zwei von ihm ausgehenden Armen und wieder ein Knauf unter den dritten zwei von ihm ausgehenden Armen; so sei es an den sechs Armen, die vom Leuchter ausgehen." },
      { number: 36, text: "Ihre Knäufe und Arme sollen aus einem Stück mit ihm sein. Der ganze Leuchter sei eine getriebene Arbeit, aus reinem Gold." },
      { number: 37, text: "Und fertige seine sieben Lampen an*, und man soll seine Lampen daraufsetzen, so dass jede auf die ihm gegenüberliegende Seite* leuchtet*.", footnotes: ["℘ Offb 4,5", "w. das Gegenüberliegende seines Gesichtes", "℘ Kap. 30,8; 3Mo 24,4; 2Chr 4,20"] },
      { number: 38, text: "Auch ihre Dochtscheren und Feuerbecken* sollst du aus reinem Gold herstellen.", footnotes: ["Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen."] },
      { number: 39, text: "Aus einem Talent reinen Goldes soll man ihn machen mit all diesen Geräten." },
      { number: 40, text: "Und sieh zu, dass du alles nach ihrem Urbild machst, das dir auf dem Berg gezeigt worden ist!*", footnotes: ["℘ V. 9; Kap. 26,30; 27,8; 31,11; 36,2; 2Chr 4,7; Apg 7,44; Hebr 8,5"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "*Die Wohnung aber sollst du aus zehn Zeltdecken machen*. Aus gezwirntem Byssus*, violettem und rotem Purpur und Karmesinstoff sollst du sie machen, mit Cherubim, als Kunststickerarbeit.", heading: "Heiligtum: Zeltdecken zur Wohnung", footnotes: ["℘ V. 1-30: Kap. 36,8-34", "℘ Kap. 31,7; 1Kö 6,29; 1Chr 17,1; Hebr 9,2.11.24; Offb 21,3", "d. i. ein feines Gewebe aus Ägypten; wohl feines Leinen"] },
      { number: 2, text: "Die Länge einer Zeltdecke sei achtundzwanzig Ellen und vier Ellen die Breite einer Zeltdecke: ein Maß für alle Zeltdecken." },
      { number: 3, text: "Fünf Zeltdecken sollen miteinander verbunden sein, und auch die übrigen fünf Zeltdecken sollen miteinander verbunden sein." },
      { number: 4, text: "Am Saum der einen Zeltdecke, am Ende der einen Verbindungsstelle, bringe Schleifen aus violettem Purpur an! Und ebenso sollst du es machen an dem Saum der äußersten Zeltdecke an der andern Verbindungsstelle:" },
      { number: 5, text: "fünfzig Schleifen sollst du an der einen Zeltdecke anbringen, und fünfzig Schleifen sollst du am Ende der Zeltdecke anbringen, die sich an der andern Verbindungsstelle befindet; die Schleifen sollen einander gegenüberstehen." },
      { number: 6, text: "Stelle fünfzig goldene Haken her und verbinde die Zeltdecken durch die Haken miteinander, so dass die Wohnung ein Ganzes wird!" },
      { number: 7, text: "Und du sollst Zeltdecken aus Ziegenhaar machen als Zeltdach über der Wohnung; elf solcher Zeltdecken sollst du machen." },
      { number: 8, text: "Die Länge einer Zeltdecke sei dreißig Ellen und vier Ellen die Breite einer Zeltdecke: ein Maß für die elf Zeltdecken." },
      { number: 9, text: "Verbinde fünf Zeltdecken für sich und ebenso die übrigen sechs Zeltdecken für sich, und die sechste Zeltdecke an der Vorderseite des Zeltes lege doppelt!" },
      { number: 10, text: "Bringe auch fünfzig Schleifen am Saum der einen Zeltdecke an, der äußersten, an der einen Verbindungsstelle, und fünfzig Schleifen am Saum der äußersten Zeltdecke der anderen Verbindungsstelle!" },
      { number: 11, text: "Dann stelle fünfzig bronzene Haken her, führe die Haken in die Schleifen ein und füge das Zeltdach zusammen, so dass es ein Ganzes wird!" },
      { number: 12, text: "Das Überhängende aber, das an den Decken des Zeltes übrig ist, die halbe Zeltdecke, die übrig ist, soll über der Rückseite der Wohnung hängen." },
      { number: 13, text: "Und von dem, was an der Länge der Decken des Zeltes übrig ist, sollen die Elle auf der einen und die Elle auf der anderen Seite an beiden Seiten der Wohnung überhängen*, um sie zu bedecken.", footnotes: ["w. Und die Elle hier und die Elle dort vom Überschuss an Länge . . . soll hier und dort über die Seiten . . . herabhängen"] },
      { number: 14, text: "Und fertige für das Zelt eine Decke aus rot gefärbten Widderfellen an und oben darüber eine Decke aus Häuten von Delfinen*!", footnotes: ["s. Anm. zu Kap. 25,5"] },
      { number: 15, text: "Die Bretter für die Wohnung sollst du aus Akazienholz herstellen — aufrecht stehend;", heading: "Heiligtum: Bretter und Riegel" },
      { number: 16, text: "zehn Ellen sei die Länge eines Brettes und anderthalb Ellen die Breite eines Brettes;" },
      { number: 17, text: "ein Brett soll zwei Zapfen haben, einer dem andern gegenüber eingefügt. So sollst du es an allen Brettern der Wohnung machen." },
      { number: 18, text: "Und zwar sollst du an Brettern für die Wohnung zwanzig Bretter für die Südseite machen, nach Süden zu," },
      { number: 19, text: "und unter den zwanzig Brettern vierzig silberne Fußgestelle anbringen: zwei Fußgestelle unter einem Brett für seine zwei Zapfen und wieder zwei Fußgestelle unter einem Brett für seine zwei Zapfen." },
      { number: 20, text: "Auch für die andere Längsseite der Wohnung, für die Nordseite, sollst du zwanzig Bretter" },
      { number: 21, text: "und ihre vierzig silbernen Fußgestelle anfertigen: zwei Fußgestelle unter einem Brett und wieder zwei Fußgestelle unter einem Brett." },
      { number: 22, text: "Für die Rückseite der Wohnung aber, nach Westen zu, sollst du sechs Bretter machen." },
      { number: 23, text: "Stelle auch zwei Bretter für die Ecken der Wohnung an der Rückseite her!" },
      { number: 24, text: "Sie sollen von unten herauf doppelt und an ihrem Oberteil ganz beieinander sein bis zu einem Ring; so soll es mit ihnen beiden sein, für die beiden Ecken sollen sie sein." },
      { number: 25, text: "Es sollen also acht Bretter sein und ihre silbernen Fußgestelle, sechzehn Fußgestelle: zwei Fußgestelle seien unter einem Brett und wieder zwei Fußgestelle unter einem Brett." },
      { number: 26, text: "Und fertige Riegel aus Akazienholz an: fünf für die Bretter der einen Längsseite der Wohnung," },
      { number: 27, text: "fünf Riegel für die Bretter der anderen Längsseite der Wohnung und fünf Riegel für die Bretter der Seite der Wohnung, die die Rückseite bildet, nach Westen zu!" },
      { number: 28, text: "Und der mittlere Riegel in der Mitte der Bretter soll von einem Ende zum andern durchlaufen." },
      { number: 29, text: "Die Bretter aber sollst du mit Gold überziehen. Und ihre Ringe, die Ösen* für die Riegel, sollst du aus Gold machen, auch die Riegel überziehe mit Gold*!", footnotes: ["w. Häuser", "℘ 1Kö 6,20.22"] },
      { number: 30, text: "So errichte denn die Wohnung nach ihrem Bauplan*, wie er dir auf dem Berg gezeigt worden ist*!", footnotes: ["o. ihrer Bestimmung; w. ihrem Recht", "℘ Kap. 25,40; 1Chr 28,19"] },
      { number: 31, text: "*Und du sollst einen Vorhang* anfertigen aus violettem und rotem Purpur und Karmesinstoff und gezwirntem Byssus; in Kunststickerarbeit soll man ihn machen, mit Cherubim*.", heading: "Heiligtum: Vorhänge", footnotes: ["℘ Kap. 36,35-38", "w. ein Absperrendes", "℘ Kap. 35,12; 2Chr 3,14; Mt 27,51; Hebr 9,3"] },
      { number: 32, text: "Den hänge an vier Säulen aus Akazienholz auf, die mit Gold überzogen sind — auch ihre Nägel sollen aus Gold sein — und die auf vier silbernen Fußgestellen stehen." },
      { number: 33, text: "Und zwar sollst du den Vorhang unter den Haken anbringen. Und bringe dorthin, auf die Innenseite hinter dem Vorhang, die Lade des Zeugnisses*! So soll der Vorhang* für euch das Heilige und das Allerheiligste* voneinander scheiden*.", footnotes: ["o. des Mahnzeichens; vgl. Anm. zu Kap. 16,34\n℘ Kap. 40,21", "w. Absperrendes", "w. das Heilige der Heiligkeiten", "℘ 1Kö 6,16; 8,6; Hebr 9,3.8"] },
      { number: 34, text: "Und die Deckplatte* sollst du auf die Lade des Zeugnisses im Allerheiligsten legen*.", footnotes: ["s. Anm. zu Kap. 25,17", "℘ Kap. 25,21"] },
      { number: 35, text: "Den Tisch aber stelle außerhalb des Vorhangs* und den Leuchter dem Tisch gegenüber an die Seite der Wohnung, die nach Süden zu liegt; und den Tisch sollst du an die Nordseite stellen*.", footnotes: ["w. Absperrendes", "℘ Kap. 40,22.24"] },
      { number: 36, text: "Dann mache für den Eingang des Zeltes einen Vorhang* aus violettem und rotem Purpur, Karmesinstoff und gezwirntem Byssus in Buntwirkerarbeit*.", footnotes: ["w. eine Decke\n℘ Kap. 40,28", "℘ Kap. 27,16; 28,15"] },
      { number: 37, text: "Für diesen Vorhang stelle fünf Säulen aus Akazienholz her und überzieh sie mit Gold — auch ihre Nägel sollen aus Gold sein — und gieße für sie fünf bronzene Fußgestelle!" },
    ]},
    { number: 27, verses: [
      { number: 1, text: "*Den Altar sollst du aus Akazienholz machen*, fünf Ellen lang und fünf Ellen breit — viereckig* soll der Altar sein — und drei Ellen hoch.", heading: "Heiligtum: Brandopferaltar", footnotes: ["℘ Kap. 38,1-7", "℘ Kap. 31,9; 2Chr 4,1; Esr 3,2; Hes 43,13-17", "o. quadratisch"] },
      { number: 2, text: "Seine Hörner mache an seinen vier Ecken — seine Hörner sollen aus einem Stück mit ihm sein* — und überziehe ihn mit Bronze!", footnotes: ["℘ Kap. 29,12; 1Kö 1,50; Ps 118,27"] },
      { number: 3, text: "Fertige auch seine Töpfe an, die man braucht, um ihn von der Fettasche zu reinigen, und seine Schaufeln, seine Sprengschalen, seine Fleischgabeln und seine Feuerbecken*! Für all seine Geräte sollst du Bronze verwenden*.", footnotes: ["Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen.", "℘ V. 19; 1Kö 7,45"] },
      { number: 4, text: "Und mache für ihn ein bronzenes Gitter wie ein Netz*, befestige an dem Netzgitter vier bronzene Ringe an seinen vier Ecken", footnotes: ["w. ein Gitter, Netzarbeit aus Bronze"] },
      { number: 5, text: "und setze es unter die Einfassung des Altars, von unten her, dass das Netz bis zur halben Höhe des Altars reicht!" },
      { number: 6, text: "Mache auch Stangen für den Altar, Stangen aus Akazienholz, und überzieh sie mit Bronze!" },
      { number: 7, text: "Diese seine Stangen sollen in die Ringe gesteckt werden, so dass die Stangen an beiden Seiten des Altars sind, wenn man ihn trägt." },
      { number: 8, text: "Aus Brettern sollst du ihn anfertigen — innen hohl. Wie es dir auf dem Berg gezeigt worden ist, so soll man ihn machen*.", footnotes: ["℘ Kap. 25,40"] },
      { number: 9, text: "*Und du sollst den Vorhof der Wohnung machen*: an der Südseite, nach Süden zu, für den Vorhof Behänge aus gezwirntem Byssus, auf der einen Seite hundert Ellen lang.", heading: "Heiligtum: Vorhof", footnotes: ["℘ Kap. 38,9-20", "℘ Kap. 35,17; 2Chr 4,9; Hes 40,17.28"] },
      { number: 10, text: "Seine zwanzig Säulen und ihre zwanzig Fußgestelle mache aus Bronze, die Nägel der Säulen und ihre Bindestäbe* aus Silber!", footnotes: ["o. Ringe. — Mit ihnen waren die Säulen verziert und verbunden."] },
      { number: 11, text: "Und ebenso sollen an der Nordseite der Länge nach Behänge sein, hundert Ellen lang; seine zwanzig Säulen und ihre zwanzig Fußgestelle aus Bronze, die Nägel der Säulen und ihre Bindestäbe* aus Silber.", footnotes: ["o. Ringe. — Mit ihnen waren die Säulen verziert und verbunden."] },
      { number: 12, text: "Und die Breite des Vorhofs an der Westseite soll an Behängen fünfzig Ellen betragen, mit ihren zehn Säulen und ihren zehn Fußgestellen." },
      { number: 13, text: "Auch die Breite des Vorhofs an der östlichen, dem Sonnenaufgang zugekehrten Seite soll fünfzig Ellen betragen:" },
      { number: 14, text: "fünfzehn Ellen Behänge seien auf der einen Seite mit ihren drei Säulen und ihren drei Fußgestellen," },
      { number: 15, text: "und auch auf der anderen Seite* fünfzehn Ellen Behänge, ihre drei Säulen und ihre drei Füße.", footnotes: ["w. Schulter. — Gemeint sind die beiden Seitenstücke neben dem Eingang."] },
      { number: 16, text: "Das Tor des Vorhofs aber soll einen Vorhang* von zwanzig Ellen haben, aus violettem und rotem Purpur, Karmesinstoff und gezwirntem Byssus, in Buntwirkerarbeit*, ihre vier Säulen und ihre vier Füße.", footnotes: ["w. eine Decke", "℘ Kap. 26,36"] },
      { number: 17, text: "Alle Säulen des Vorhofs ringsum sollen mit silbernen Bindestäben* versehen sein, ihre Nägel seien aus Silber und ihre Fußgestelle aus Bronze.", footnotes: ["o. Ringe. — Mit ihnen waren die Säulen verziert und verbunden."] },
      { number: 18, text: "Die Länge des Vorhofs betrage hundert Ellen, die Breite fünfzig gegen fünfzig und die Höhe fünf Ellen: alle Behänge seien aus gezwirntem Byssus, ihre Fußgestelle aber aus Bronze." },
      { number: 19, text: "Alle Geräte der Wohnung für den ganzen Dienst in ihr*, auch all ihre Pflöcke und alle Pflöcke des Vorhofs sollen aus Bronze sein*.", footnotes: ["o. für ihre ganze Herstellung; w. in ihrem ganzen Dienst", "℘ V. 3"] },
      { number: 20, text: "*Du nun gebiete den Söhnen Israel, dass sie dir reines Öl aus zerstoßenen Oliven* für den Leuchter bringen, damit man beständig* eine Lampe daraufsetzen kann!", heading: "Heiligtum: Öl für den Leuchter", footnotes: ["℘ 3Mo 24,2-4", "w. zerstoßenes Olivenöl", "℘ 1Sam 3,3"] },
      { number: 21, text: "Im Zelt der Begegnung, außerhalb des Vorhangs*, der vor dem Zeugnis* ist, sollen Aaron und seine Söhne sie herrichten, damit sie vom Abend bis zum Morgen vor dem HERRN brennt*. Das ist bei den Söhnen Israel eine ewige Ordnung für all ihre Generationen.*", footnotes: ["w. des Absperrenden", "o. dem Mahnzeichen; vgl. Anm. zu Kap. 16,34; w. über dem Zeugnis; d. h. abschirmend schützend", "℘ 1Sam 3,3", "℘ Kap. 12,14; 28,43; 29,9; 30,21"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "*Du aber lass deinen Bruder Aaron* und seine Söhne mit ihm aus der Mitte der Söhne Israel zu dir herantreten, damit er mir den Priesterdienst ausübt, Aaron und mit ihm Nadab und Abihu*, Eleasar und Itamar, die Söhne Aarons*.", heading: "Heiligtum: Aaron und seine Söhne — Ihre Kleidung", footnotes: ["℘ V. 1-4: 3Mo 8,1-13", "℘ Hebr 5,4; 7,16", "℘ Kap. 6,23; 29,1; 4Mo 18,7; 5Mo 18,5; 1Chr 6,34; 23,13; 2Chr 26,18", "℘ 1Sam 2,28"] },
      { number: 2, text: "Und fertige heilige Kleider* für deinen Bruder Aaron an, ihm zur Ehre und zum Schmuck*!", footnotes: ["℘ Kap. 29,29; 39,1", "℘ V. 40; Jes 61,10"] },
      { number: 3, text: "Du sollst zu allen reden, die ein verständiges Herz haben*, das ich mit dem Geist der Weisheit erfüllt habe*, und ihnen sagen, dass sie die Kleider Aarons machen sollen, um ihn zu heiligen, damit er mir den Priesterdienst ausübt.", footnotes: ["℘ Kap. 31,6; 35,10; 36,1.8", "℘ 5Mo 34,9"] },
      { number: 4, text: "Dies aber sind die Kleider, die sie anfertigen sollen: eine Brusttasche* und ein Efod und ein Oberkleid, einen Leibrock aus gewirktem Stoff, einen Kopfbund und einen Gürtel*. Diese heiligen Kleider sollen sie für deinen Bruder Aaron und für seine Söhne anfertigen, damit er mir den Priesterdienst ausübt.", footnotes: ["o. Brustschild", "o. eine Schärpe"] },
      { number: 5, text: "*Und dazu sollen sie das Gold, den violetten und roten Purpur, den Karmesinstoff und den Byssus nehmen.", footnotes: ["℘ V. 5-14: Kap. 39,1-7"] },
      { number: 6, text: "So sollen sie nun das Efod* aus Gold, violettem und rotem Purpur, Karmesinstoff und gezwirntem Byssus, in Kunststickerarbeit machen.", footnotes: ["℘ 1Sam 23,6.9; 30,7; Hos 3,4"] },
      { number: 7, text: "Es soll an seinen beiden Rändern zwei zusammenfügbare* Schulterstücke haben, und man füge es mit ihnen zusammen.", footnotes: ["o. zwei mit ihm verbundene; o. zwei zusammengefügte"] },
      { number: 8, text: "Und der Gurt, mit dem es angelegt wird, der sich oben befindet, soll von gleicher Arbeit und aus einem Stück mit ihm sein: aus Gold, violettem und rotem Purpur, Karmesinstoff und gezwirntem Byssus." },
      { number: 9, text: "Und du sollst zwei Onyxsteine* nehmen und die Namen der Söhne Israel darauf eingravieren:", footnotes: ["℘ Kap. 25,7; 1Chr 29,2"] },
      { number: 10, text: "sechs ihrer Namen auf dem einen Stein und die sechs übrigen Namen auf dem andern Stein nach der Reihenfolge ihrer Geburt*.", footnotes: ["o. nach ihrer Generationenfolge, o. Entstehung; vgl. Anm. zu 1Mo 5,1"] },
      { number: 11, text: "In Steinschneidearbeit, als Siegelgravur sollst du die beiden Steine stechen nach den Namen der Söhne Israel. Mit goldenen Einfassungen umgeben sollst du sie anfertigen." },
      { number: 12, text: "Dann setze die beiden Steine oben auf die Schulterstücke des Efods, als Steine der Erinnerung für die Söhne Israel! Und Aaron soll ihre Namen auf seinen beiden Schultern tragen vor dem HERRN zur Erinnerung*.", footnotes: ["℘ V. 29"] },
      { number: 13, text: "Weiter stelle goldene Einfassungen" },
      { number: 14, text: "und zwei Ketten aus reinem Gold her! Als Schnüre sollst du sie herstellen, in Seilerarbeit, und die seilförmigen Ketten an den Einfassungen befestigen." },
      { number: 15, text: "*Und mache die Brusttasche* für den Rechtsspruch* in Kunststickerarbeit! Wie die Arbeit des Efods sollst du sie anfertigen: aus Gold, violettem und rotem Purpur, Karmesinstoff und gezwirntem Byssus sollst du sie machen*.", footnotes: ["℘ V. 15-30: Kap. 39,8-21", "o. Brustschild\n℘ 3Mo 8,8", "hier vielleicht: Losentscheid", "℘ Kap. 26,36"] },
      { number: 16, text: "Viereckig* soll sie sein, doppelt gelegt, eine Spanne ihre Länge und eine Spanne ihre Breite.", footnotes: ["o. Quadratisch"] },
      { number: 17, text: "Und besetze sie mit eingesetzten Steinen, vier Reihen von Steinen*: eine Reihe Karneol, Topas und Smaragd, die erste Reihe;", footnotes: ["℘ Offb 21,19.20"] },
      { number: 18, text: "die zweite Reihe: Rubin, Saphir und Jaspis;" },
      { number: 19, text: "und die dritte Reihe: Hyazinth, Achat und Amethyst;" },
      { number: 20, text: "und die vierte Reihe: Türkis und Onyx und Nephrit! Mit Gold sollen sie eingefasst sein in ihren Einsetzungen." },
      { number: 21, text: "Die Steine sollen also den Namen der Söhne Israel entsprechen, zwölf an der Zahl, entsprechend ihren Namen; in Siegelgravur sollen sie hergestellt werden, jeder seinem Namen entsprechend für die zwölf Stämme*.", footnotes: ["℘ Kap. 24,4; Sach 9,16; Offb 21,12"] },
      { number: 22, text: "Mache an der Brusttasche* gedrehte Ketten in Seilerarbeit, aus reinem Gold;", footnotes: ["o. Brustschild"] },
      { number: 23, text: "und zwar sollst du an der Brusttasche* zwei goldene Ringe anbringen, indem du die beiden Ringe an den beiden oberen Enden der Brusttasche* befestigst", footnotes: ["o. Brustschild", "o. Brustschild"] },
      { number: 24, text: "und die zwei goldenen Schnüre an den beiden Ringen an den Enden der Brusttasche* befestigst.", footnotes: ["o. Brustschild"] },
      { number: 25, text: "Die beiden anderen Enden der zwei Schnüre aber sollst du an den beiden Einfassungen befestigen und sie so an den Schulterstücken des Efods befestigen, an seiner Vorderseite." },
      { number: 26, text: "Und stelle zwei andere goldene Ringe her und befestige sie an den beiden unteren Enden der Brusttasche*, an ihrem Rand, der dem Efod zugekehrt ist, auf der Innenseite!", footnotes: ["o. Brustschild"] },
      { number: 27, text: "Dann mache noch zwei goldene Ringe und befestige sie unten an den beiden Schulterstücken* des Efods, an seiner Vorderseite, dicht an seiner Zusammenfügung mit den Schulterstücken oberhalb des Gurtes vom Efod.", footnotes: ["o. zwei mit ihm verbundene Schulterstücke; o. zwei zusammengefügte . . ."] },
      { number: 28, text: "Und man soll die Brusttasche* von ihren Ringen aus mit einer Schnur von violettem Purpur an den Ringen des Efods festbinden, damit sie über dem Gurt des Efods sitzt und die Brusttasche* sich nicht von der Stelle über dem Efod verschiebt.", footnotes: ["o. Brustschild", "o. Brustschild"] },
      { number: 29, text: "So soll Aaron an der Brusttasche* für den Rechtsspruch* die Namen der Söhne Israel auf seinem Herzen tragen, wenn er ins Heiligtum hineingeht, um sie beständig vor dem HERRN in Erinnerung zu bringen*.", footnotes: ["o. Brustschild", "hier vielleicht: Losentscheid", "w. zum Gedenken vor dem HERRN beständig\n℘ V. 12"] },
      { number: 30, text: "In die Brusttasche* für den Rechtsspruch* aber lege die Urim und die Tummim*, damit sie auf dem Herzen Aarons sind, wenn er vor den HERRN hineingeht! So soll Aaron den Rechtsspruch für die Söhne Israel beständig vor dem HERRN auf seinem Herzen tragen.", footnotes: ["o. Brustschild", "hier vielleicht: Losentscheid", "Urim und Tummim sind heilige Lose, die in schwierigen Fällen Rechtsentscheidungen herbeiführten; deshalb: Brusttasche des Rechtsspruchs. Die Bedeutung der Wörter Urim und Tummim ist unsicher. LXX: Licht und Recht.\n℘ 3Mo 8,8; 4Mo 27,21; 5Mo 33,8; 1Sam 28,6; Esr 2,63; Neh 7,65"] },
      { number: 31, text: "*Mache das Oberkleid des Efods ganz aus violettem Purpur!", footnotes: ["℘ V. 31-35: Kap. 39,22-26"] },
      { number: 32, text: "Seine Kopföffnung soll in seiner Mitte sein, und einen Rand in Weberarbeit soll es ringsum an seiner Öffnung haben. Wie die Öffnung eines Lederpanzers soll sie für ihn sein, damit es nicht einreißt." },
      { number: 33, text: "An seinem unteren Saum sollst du Granatäpfel aus violettem und rotem Purpur und Karmesinstoff anbringen, ringsum an seinem Saum, und zwischen ihnen ringsum goldene Glöckchen:" },
      { number: 34, text: "erst ein goldenes Glöckchen, dann einen Granatapfel und wieder ein goldenes Glöckchen und einen Granatapfel ringsum an dem Saum des Oberkleides." },
      { number: 35, text: "Und Aaron soll es anhaben, um darin den Dienst zu verrichten, und der Klang soll gehört werden, wenn er ins Heiligtum hineingeht vor den HERRN, und wenn er herausgeht, damit er nicht stirbt." },
      { number: 36, text: "*Und stelle aus reinem Gold ein blumenförmiges Stirnblatt her* und graviere darauf mit Siegelgravur ein: »Heiligkeit dem HERRN!«*", footnotes: ["℘ V. 36-43: Kap. 39,27-31; 1Chr 23,13", "℘ 3Mo 8,9", "℘ Kap. 19,6; Ps 93,5; Sach 14,20; 1Petr 2,9"] },
      { number: 37, text: "Das hänge an eine Schnur aus violettem Purpur, so dass es sich am Kopfbund befindet! An der Vorderseite des Kopfbundes soll es sein." },
      { number: 38, text: "So sei es auf der Stirn Aarons, damit Aaron die Schuld der heiligen Dinge trage*, die die Söhne Israel heiligen werden, bei allen Gaben ihrer heiligen Dinge. Und es soll beständig an seiner Stirn sein zum Gefallen für sie vor dem HERRN.", footnotes: ["℘ 3Mo 10,17; 4Mo 18,1.23"] },
      { number: 39, text: "Den Leibrock aber webe aus Byssus, gemustert, und mache einen Kopfbund aus Byssus! Dazu sollst du einen Gürtel in Buntwirkerarbeit anfertigen." },
      { number: 40, text: "Auch den Söhnen Aarons sollst du Leibröcke machen und Gürtel für sie anfertigen, und hohe Turbane sollst du ihnen machen zur Ehre und zum Schmuck*.", footnotes: ["℘ V. 2"] },
      { number: 41, text: "Und du sollst deinen Bruder Aaron damit bekleiden und seine Söhne mit ihm. Dann sollst du sie salben* und ihnen die Hände füllen* und sie heiligen, damit sie mir den Priesterdienst ausüben*.", footnotes: ["℘ Kap. 29,7; 30,25; 1Jo 2,20", "Der Ausdruck bezieht sich normalerweise auf die Einkünfte des Priesters aus seiner Amtstätigkeit. Hier ist aber wohl speziell die Amtseinsetzung gemeint (vgl. 3Mo 8,28).", "℘ Kap. 30,30; 40,15; 3Mo 8,12.30; 4Mo 3,3"] },
      { number: 42, text: "Ferner mache ihnen leinene Beinkleider, um das Fleisch der Blöße zu bedecken!* Von den Hüften bis zu den Oberschenkeln sollen sie reichen.", footnotes: ["℘ 3Mo 6,3"] },
      { number: 43, text: "Und Aaron und seine Söhne sollen sie anhaben, wenn sie in das Zelt der Begegnung hineingehen oder wenn sie an den Altar herantreten*, um den Dienst im Heiligtum zu verrichten, damit sie nicht eine Schuld auf sich laden und sterben*. Das ist eine ewige Ordnung für ihn und für seine Nachkommenschaft nach ihm*.", footnotes: ["℘ Kap. 20,26", "℘ 3Mo 22,9; 4Mo 18,22.23.32", "℘ Kap. 27,21; 3Mo 3,17; 4Mo 15,15; 18,8.23"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "*Und dies ist es, was du mit ihnen tun sollst, sie zu heiligen, damit sie mir den Priesterdienst ausüben*: Nimm einen Jungstier und zwei Widder ohne Fehler,", heading: "Heiligtum: Weihe Aarons und seiner Söhne und des Altars", footnotes: ["℘ 3Mo 8", "℘ Kap. 28,1"] },
      { number: 2, text: "dazu ungesäuertes Brot und ungesäuerte, mit Öl gemengte* Kuchen sowie ungesäuerte, mit Öl bestrichene* Fladen; aus Weizengrieß sollst du sie machen*.", footnotes: ["o. angefeuchtete", "w. gesalbte", "℘ 3Mo 2,4; 6,13-15"] },
      { number: 3, text: "Dann lege sie in einen Korb und bringe sie in dem Korb dar, und den Stier und die zwei Widder!" },
      { number: 4, text: "Aaron und seine Söhne aber sollst du an den Eingang des Zeltes der Begegnung herantreten lassen* und sie mit Wasser waschen*.", footnotes: ["℘ 4Mo 8,9", "℘ Kap. 30,19; 40,12.31.32; Tit 3,5; Hebr 10,22"] },
      { number: 5, text: "Darauf sollst du die Kleider nehmen und Aaron bekleiden mit dem Leibrock, dem Oberkleid des Efods, dem Efod und der Brusttasche und ihm den Gurt des Efods umbinden." },
      { number: 6, text: "Dann setze ihm den Kopfbund auf sein Haupt* und befestige das heilige Diadem am Kopfbund,", footnotes: ["℘ Sach 3,5"] },
      { number: 7, text: "nimm das Salböl, gieße es auf sein Haupt und salbe ihn*!", footnotes: ["℘ Kap. 28,41; 3Mo 10,7; 4Mo 35,25; Ps 133,2; Jes 61,1"] },
      { number: 8, text: "Auch seine Söhne sollst du herantreten lassen und sie mit Leibröcken bekleiden." },
      { number: 9, text: "Dann umgürte sie mit dem Gürtel, Aaron und seine Söhne, und binde ihnen die hohen Turbane um! So soll ihnen das Priesteramt zu einer ewigen Ordnung sein*. Und du sollst Aaron und seinen Söhnen die Hände füllen*.", footnotes: ["o. ihnen als ewige Verpflichtung zuteil werden\n℘ Kap. 27,21; 1Sam 2,30", "℘ Ri 17,5"] },
      { number: 10, text: "Auch sollst du den Stier vor das Zelt der Begegnung heranführen, und Aaron und seine Söhne sollen ihre Hände auf den Kopf des Stiers legen*.", footnotes: ["℘ 3Mo 1,4; 3,2"] },
      { number: 11, text: "Dann schlachte den Stier vor dem HERRN*, am Eingang des Zeltes der Begegnung,", footnotes: ["℘ 3Mo 4,4"] },
      { number: 12, text: "nimm von dem Blut des Stiers und tu es mit deinem Finger an die Hörner des Altars, und alles übrige Blut sollst du an den Fuß des Altars gießen*!", footnotes: ["℘ 3Mo 4,7.18.25.30.34"] },
      { number: 13, text: "Und nimm alles Fett, das die Eingeweide bedeckt, dazu den Lappen über der Leber und die beiden Nieren und das Fett, das an ihnen ist, und lass dies alles auf dem Altar als Rauch aufsteigen*!", footnotes: ["℘ 3Mo 3,3-5"] },
      { number: 14, text: "Das Fleisch des Stiers aber samt seiner Haut und dem Inhalt seines Magens* sollst du außerhalb des Lagers verbrennen*: ein Sündopfer ist es.", footnotes: ["o. seiner Gedärme", "℘ 3Mo 4,11.12.21; 4Mo 19,5; Hes 43,21"] },
      { number: 15, text: "Danach nimm den einen Widder, und Aaron und seine Söhne sollen ihre Hände auf den Kopf des Widders legen*,", footnotes: ["℘ 3Mo 1,4; 3,2"] },
      { number: 16, text: "dann sollst du den Widder schlachten und sein Blut nehmen und es ringsum an* den Altar sprengen.", footnotes: ["o. auf"] },
      { number: 17, text: "Und du sollst den Widder in seine Stücke zerlegen, seine Eingeweide und seine Unterschenkel waschen und sie auf seine Stücke und auf seinen Kopf* legen.", footnotes: ["LXX: zu seinen Stücken und zu seinem Kopf"] },
      { number: 18, text: "Den ganzen Widder aber sollst du auf dem Altar als Rauch aufsteigen lassen: ein Brandopfer für den HERRN ist es*, ein wohlgefälliger Geruch*. Ein Feueropfer ist es für den HERRN.", footnotes: ["℘ 1Mo 8,20.21", "o. Geruch der Befriedigung o. der Beschwichtigung"] },
      { number: 19, text: "Und nimm den zweiten Widder, und Aaron und seine Söhne sollen ihre Hände auf den Kopf des Widders legen*!", footnotes: ["℘ 3Mo 1,4; 3,2"] },
      { number: 20, text: "Dann sollst du den Widder schlachten und von seinem Blut etwas nehmen und es auf das rechte Ohrläppchen Aarons und auf das rechte Ohrläppchen seiner Söhne tun, auch auf den Daumen ihrer rechten Hand und auf die große Zehe ihres rechten Fußes*. Das übrige Blut aber sollst du ringsum an* den Altar sprengen.", footnotes: ["℘ 3Mo 14,14.17.25.28", "o. auf"] },
      { number: 21, text: "Und nimm von dem Blut, das auf dem Altar ist, und von dem Salböl und sprenge es auf Aaron und auf seine Kleider, und auf seine Söhne und auf die Kleider seiner Söhne mit ihm! So werden er und seine Kleider und seine Söhne und die Kleider seiner Söhne mit ihm geheiligt*.", footnotes: ["℘ Kap. 30,30; 2Kor 1,21"] },
      { number: 22, text: "Dann nimm von dem Widder das Fett, den Fettschwanz und das Fett, das die Eingeweide bedeckt, dazu den Leberlappen, die beiden Nieren und das Fett, das an ihnen ist, sowie die rechte Keule — denn ein Widder der Einsetzung* ist es —,", footnotes: ["w. Handfüllung; vgl. die Anm. zu Kap. 28,41"] },
      { number: 23, text: "ferner ein fladenförmiges Rundbrot, einen Ölbrotkuchen und einen Fladen aus dem Korb der ungesäuerten Brote, der vor dem HERRN steht," },
      { number: 24, text: "und lege das alles auf die Hände Aarons und auf die Hände seiner Söhne und schwinge es als Schwingopfer vor dem HERRN*!", footnotes: ["℘ 3Mo 7,30; 23,11"] },
      { number: 25, text: "Dann nimm es von ihren Händen und lass es auf dem Altar über dem Brandopfer als Rauch aufsteigen zum wohlgefälligen Geruch* vor dem HERRN! Ein Feueropfer ist es für den HERRN*.", footnotes: ["o. Geruch der Befriedigung o. der Beschwichtigung", "℘ 1Mo 8,20.21"] },
      { number: 26, text: "Und nimm die Brust von dem Einsetzungswidder, der für Aaron ist, und schwinge sie als Schwingopfer vor dem HERRN! Sie soll dein Anteil sein." },
      { number: 27, text: "Und heilige die Brust des Schwingopfers und die Keule des Hebopfers, die geschwungen und die abgehoben worden ist, von dem Einsetzungswidder, von dem, was für Aaron, und von dem, was für seine Söhne ist!" },
      { number: 28, text: "Und es soll Aaron und seinen Söhnen* zukommen als eine ewige Ordnung bei den Söhnen Israel, denn es ist ein Hebopfer, und ein Hebopfer soll es sein bei den Söhnen Israel, ihr Hebopfer von ihren Heilsopfern*: für den HERRN*.", footnotes: ["℘ Kap. 28,2; 4Mo 20,28", "o. Friedensopfern; o. Abschlussopfern; o. Gemeinschaftsopfern", "℘ 3Mo 10,15; 4Mo 5,9.10; 6,20; 18,8-19; 5Mo 18,3"] },
      { number: 29, text: "Die heiligen Kleider Aarons sollen nach ihm seinen Söhnen zuteil werden, damit man sie darin salbe und darin weihe*.", footnotes: ["w. ihre Hand fülle; vgl. die Anm. zu Kap. 28,41"] },
      { number: 30, text: "Sieben Tage soll sie anziehen, wer von seinen Söhnen an seiner Statt Priester wird, wer in das Zelt der Begegnung hineingeht, um im Heiligtum zu dienen*.", footnotes: ["℘ 3Mo 16,32"] },
      { number: 31, text: "Du sollst den Einsetzungswidder nehmen und sein Fleisch an heiliger Stätte kochen*.", footnotes: ["℘ Hes 46,20"] },
      { number: 32, text: "Dann sollen Aaron und seine Söhne das Fleisch des Widders und das Brot, das im Korb ist, am Eingang des Zeltes der Begegnung essen." },
      { number: 33, text: "Sie sollen die Stücke essen, mit denen die Sühnung vollzogen wurde, um ihnen die Hände zu füllen*, um sie dadurch zu heiligen*. Ein Fremder* darf aber nicht davon essen, denn sie sind heilig*.", footnotes: ["s. Anm. zu Kap. 28,41", "℘ 3Mo 10,12-18", "d. h. ein Unbefugter; einer, der nicht zum Stand der Priester gehört", "℘ 3Mo 22,10"] },
      { number: 34, text: "Wenn aber von dem Fleisch des Einsetzungsopfers und von dem Brot etwas bis zum nächsten Morgen übrig bleibt, dann sollst du das Übriggebliebene mit Feuer verbrennen*; es darf nicht gegessen werden, denn es ist heilig.", footnotes: ["℘ Kap. 12,10"] },
      { number: 35, text: "So sollst du mit Aaron und seinen Söhnen verfahren, nach allem, was ich dir geboten habe. Sieben Tage sollst du sie weihen*.", footnotes: ["w. ihre Hand füllen"] },
      { number: 36, text: "Auch sollst du täglich einen Stier zur Sühnung als Sündopfer darbringen und den Altar entsündigen, indem du Sühnung an ihm vollziehst, und du sollst ihn salben, um ihn zu heiligen*.", footnotes: ["℘ 4Mo 7,1"] },
      { number: 37, text: "Sieben Tage sollst du Sühnung am Altar vollziehen und ihn dadurch heiligen*. So wird der Altar hochheilig sein; alles, was* den Altar berührt, ist geheiligt*.", footnotes: ["℘ 2Chr 7,9; Hes 43,20-26", "o. jeder, der", "d. h. gehört dem Heiligtum\n℘ Kap. 30,29; 3Mo 6,11.20; Mt 23,19"] },
      { number: 38, text: "*Und dies ist es, was du auf dem Altar darbringen sollst: täglich zwei einjährige Lämmer* als regelmäßiges Brandopfer*.", heading: "Heiligtum: Tägliche Opfer", footnotes: ["℘ V. 38-42: 4Mo 28,3-8", "o. junge Widder; dann auch in V. 39—41", "℘ 3Mo 9,17; Dan 12,11; Hebr 10,11"] },
      { number: 39, text: "Das eine Lamm sollst du am Morgen darbringen*, und das zweite Lamm sollst du zwischen den zwei Abenden* darbringen*,", footnotes: ["℘ 2Kö 3,20; 16,15; Hes 46,13-15", "d. h. entweder zwischen Sonnenuntergang und völliger Nacht oder zwischen Niedergang (15 Uhr) und Untergang der Sonne", "℘ Kap. 12,6; 2Chr 2,3; Esr 9,4.5; Ps 141,2"] },
      { number: 40, text: "dazu ein Zehntel* Weizengrieß mit einem viertel Hin Öl aus zerstoßenen Oliven gemengt*, und als Trankopfer ein viertel Hin Wein zu dem einen Lamm*.", footnotes: ["d. h. wahrscheinlich: ein zehntel Efa", "o. angefeuchtet", "℘ 4Mo 15,4.5"] },
      { number: 41, text: "Das andere Lamm aber sollst du zwischen den zwei Abenden darbringen* — wie bei dem Morgen-Speisopfer* und bei seinem Trankopfer sollst du es dabei halten — zum wohlgefälligen Geruch*, ein Feueropfer für den HERRN*,", footnotes: ["℘ Kap. 12,6; 2Chr 2,3; Esr 9,4.5; Ps 141,2", "Das hebr. Wort für »Speisopfer« heißt eigentlich »Geschenk, Gabe«.", "o. Geruch der Befriedigung o. der Beschwichtigung", "℘ Kap. 12,6; 2Chr 2,3; Esr 9,4.5; Ps 141,2"] },
      { number: 42, text: "als ein regelmäßiges Brandopfer für all eure Generationen am Eingang des Zeltes der Begegnung vor dem HERRN, wo ich euch begegnen werde, um dort zu dir zu reden*.", footnotes: ["℘ Kap. 25,22"] },
      { number: 43, text: "Und ich werde dort den Söhnen Israel begegnen, und es* wird durch meine Herrlichkeit geheiligt werden*.", footnotes: ["d. h. das Zelt", "℘ 3Mo 9,4.6; 1Kö 8,11"] },
      { number: 44, text: "So werde ich das Zelt der Begegnung und den Altar heiligen*. Und Aaron und seine Söhne werde ich heiligen, damit sie mir den Priesterdienst ausüben.", footnotes: ["℘ 1Kö 9,3"] },
      { number: 45, text: "Und ich werde mitten unter den Söhnen Israel wohnen* und ihr Gott sein*.", footnotes: ["℘ Kap. 25,8; 3Mo 26,12; 4Mo 16,3; 2Chr 6,18; Jer 14,9", "w. ihnen zum Gott werden, o. zum Gott sein\n℘ Kap. 6,7; Hes 34,24; Offb 21,3"] },
      { number: 46, text: "Und sie werden erkennen, dass ich, der HERR, ihr Gott bin, der ich sie aus dem Land Ägypten herausgeführt habe*, um mitten unter ihnen zu wohnen*, ich, der HERR, ihr Gott*.", footnotes: ["℘ Kap. 20,2; 1Sam 10,18", "℘ Kap. 6,7; Hes 34,24; Offb 21,3", "℘ Kap. 6,7; Hes 34,24; Offb 21,3"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "*Ferner sollst du einen Altar anfertigen zum Räuchern des Räucherwerks*, aus Akazienholz sollst du ihn machen*:", heading: "Heiligtum: Räucheraltar", footnotes: ["℘ Kap. 37,25-28", "℘ Hes 41,22; Hebr 9,4", "℘ Kap. 31,8"] },
      { number: 2, text: "eine Elle seine Länge und eine Elle seine Breite — viereckig* soll er sein — und zwei Ellen seine Höhe; seine Hörner sollen aus einem Stück mit ihm sein.", footnotes: ["o. quadratisch"] },
      { number: 3, text: "Und überzieh ihn mit reinem Gold*, seine Platte und seine Wände ringsum sowie seine Hörner, und bringe an ihm ringsum eine goldene Kante an*!", footnotes: ["℘ 1Kö 6,20; 7,48", "℘ Kap. 25,11.24; Offb 8,3; 9,13"] },
      { number: 4, text: "Und bringe an ihm unter seiner Kante zwei goldene Ringe an! An seine beiden Seiten* sollst du sie anbringen, an seine beiden Wände*. Die sollen* als Behälter für die Stangen dienen, damit man ihn daran tragen kann.", footnotes: ["w. Längsseiten; andere Üs.: Ecken", "w. Seiten", "so mit mehreren hebr. Handschr., SamPent und den alten Üs.; Mas. T.: Das soll"] },
      { number: 5, text: "Und stelle die Stangen aus Akazienholz her und überzieh sie mit Gold!" },
      { number: 6, text: "Und stelle ihn vor dem Vorhang* auf, der an* der Lade des Zeugnisses ist, vor der Deckplatte*, die über dem Zeugnis liegt, wo ich dir begegnen werde*.", footnotes: ["w. Absperrenden", "o. über", "s. Anm. zu Kap. 25,17", "℘ V. 36; Kap. 25,22"] },
      { number: 7, text: "Und Aaron soll wohlriechendes Räucherwerk als Rauch aufsteigen lassen*. Morgen für Morgen*, wenn er die Lampen zurichtet, soll er es als Rauch aufsteigen lassen*.", footnotes: ["℘ V. 34.35; Kap. 40,27; 5Mo 33,10; 1Sam 2,28; 1Chr 6,34; 2Chr 2,3; 26,18; 29,7; Ps 141,2; Lk 1,9", "℘ 3Mo 6,5", "℘ Kap. 6,7; Hes 34,24; Offb 21,3"] },
      { number: 8, text: "Auch wenn Aaron die Lampen zwischen den zwei Abenden* aufsetzt, soll er es als Rauch aufsteigen lassen. Dies sei ein regelmäßiges Räucheropfer* vor dem HERRN für all eure Generationen.*", footnotes: ["s. Anm. zu Kap. 29,39", "o. Räucherwerk", "℘ Hebr 9,6"] },
      { number: 9, text: "Ihr dürft kein fremdes Räucherwerk auf ihm darbringen*, auch kein Brandopfer oder Speisopfer; auch Trankopfer dürft ihr nicht auf ihm ausgießen.", footnotes: ["℘ 3Mo 10,1.2"] },
      { number: 10, text: "Und Aaron soll einmal im Jahr an seinen Hörnern Sühnung vollziehen mit dem Blut des Sündopfers der Versöhnung; einmal im Jahr soll er Sühnung an ihm vollziehen, für all eure Generationen*: Hochheilig ist er dem HERRN.", footnotes: ["℘ 3Mo 16,18.34; Hebr 9,7"] },
      { number: 11, text: "Und der HERR redete zu Mose und sprach:", heading: "Heiligtum: Abgabe bei der Musterung" },
      { number: 12, text: "Wenn du die Gesamtzahl der Söhne Israel aufnimmst nach ihren Gemusterten*, dann sollen sie bei ihrer Musterung ein jeder dem HERRN ein Lösegeld für sein Leben* geben*, damit bei ihrer Musterung keine Plage über sie kommt*.", footnotes: ["℘ 4Mo 1,2.3; 2Sam 24,4", "o. seine Seele", "℘ 4Mo 31,49.50", "℘ 1Chr 21,1-14"] },
      { number: 13, text: "Dies sollen sie geben: jeder, der zu den Gemusterten hinübergeht*, einen halben Schekel, nach dem Schekel des Heiligtums*, zwanzig Gera der Schekel, einen halben Schekel* als Hebopfer für den HERRN.", footnotes: ["o. durch die Musterung geht\n℘ 2Kö 12,5", "d. h. nach dem am Heiligtum gültigen Schekelgewicht", "℘ 3Mo 27,3.25; 4Mo 3,47"] },
      { number: 14, text: "Jeder, der zu den Gemusterten hinübergeht*, von zwanzig Jahren an und darüber, soll das Hebopfer für den HERRN geben*.", footnotes: ["o. durch die Musterung geht", "℘ Hes 45,12.16"] },
      { number: 15, text: "Der Reiche soll nicht mehr geben und der Geringe nicht weniger als einen halben Schekel*, wenn ihr das Hebopfer des HERRN gebt, um für euer Leben* Sühnung zu erwirken*.", footnotes: ["℘ Hi 34,19", "o. für eure Seelen", "℘ Röm 3,22-24"] },
      { number: 16, text: "Und du sollst das Sühngeld vonseiten der Söhne Israel nehmen und es für die Arbeit* des Zeltes der Begegnung geben*. So soll es den Söhnen Israel zur Erinnerung vor dem HERRN dienen*, um Sühnung für euer Leben* zu erwirken*.", footnotes: ["o. den Dienst", "℘ 2Chr 24,6.9; Neh 10,33.34; Mt 17,24", "℘ 4Mo 31,54", "o. für eure Seelen", "℘ Kap. 38,25-28"] },
      { number: 17, text: "*Und der HERR redete zu Mose und sprach:", heading: "Heiligtum: Waschbecken", footnotes: ["℘ Kap. 38,8"] },
      { number: 18, text: "Stelle ein bronzenes Becken und sein bronzenes Gestell her zum Waschen*! Das stelle zwischen das Zelt der Begegnung und den Altar, tu Wasser hinein*,", footnotes: ["℘ Kap. 31,9; 1Kö 7,23-39; 2Chr 4,2-6", "℘ Kap. 40,7"] },
      { number: 19, text: "und Aaron und seine Söhne sollen ihre Hände und ihre Füße darin* waschen*!", footnotes: ["w. daraus", "℘ Kap. 29,4"] },
      { number: 20, text: "Wenn sie in das Zelt der Begegnung hineingehen, sollen sie sich mit Wasser waschen, damit sie nicht sterben. Oder wenn sie an den Altar herantreten zum Dienst, um für den HERRN ein Feueropfer als Rauch aufsteigen zu lassen," },
      { number: 21, text: "dann sollen sie ihre Hände und ihre Füße waschen, damit sie nicht sterben. Und das soll für sie eine ewige Ordnung sein, für ihn und seine Nachkommen, für all ihre Generationen*.", footnotes: ["℘ Kap. 27,21"] },
      { number: 22, text: "*Und der HERR redete zu Mose und sprach:", heading: "Heiligtum: Salböl und Räucherwerk", footnotes: ["℘ Kap. 37,29"] },
      { number: 23, text: "Du nun, *nimm dir Balsamöle bester Art, 500 Schekel von selbst ausgeflossene Myrrhe* und die Hälfte davon, 250 Schekel, wohlriechenden Zimt, ferner 250 Schekel Würzrohr*", footnotes: ["o. nimm dir wohlriechende Stoffe, 500 Schekel beste, von selbst ausgeflossene Myrrhe", "o. nimm dir wohlriechende Stoffe, 500 Schekel beste, von selbst ausgeflossene Myrrhe", "℘ Jes 43,24; Jer 6,20; Hes 27,19"] },
      { number: 24, text: "und 500 Schekel Zimtblüten, nach dem Schekel des Heiligtums, dazu ein Hin Olivenöl" },
      { number: 25, text: "und mache daraus ein Öl der heiligen Salbung, eine Mischung von Gewürzsalbe, ein Werk des Salbenmischers; es soll ein Öl für die heilige Salbung sein*.", footnotes: ["℘ Kap. 28,41; 1Kö 1,39; 1Chr 9,30; Ps 133,2"] },
      { number: 26, text: "Und du sollst damit das Zelt der Begegnung und die Lade des Zeugnisses salben," },
      { number: 27, text: "auch den Tisch und all seine Geräte, den Leuchter und seine Geräte und den Räucheraltar*,", footnotes: ["w. Altar des Räucherwerks"] },
      { number: 28, text: "sowie den Brandopferaltar samt all seinen Geräten, das Becken und sein Gestell." },
      { number: 29, text: "So sollst du diese Dinge heiligen*, und sie sollen hochheilig sein*; alles, was* sie berührt, ist geheiligt*.", footnotes: ["℘ 3Mo 8,10; 4Mo 7,1", "℘ Kap. 40,10", "o. jeder, der", "d. h. gehört dem Heiligtum; vgl. Jos 6,19\n℘ Kap. 29,37"] },
      { number: 30, text: "Auch Aaron und seine Söhne sollst du salben und sie dadurch heiligen, damit sie mir den Priesterdienst ausüben*.", footnotes: ["℘ Kap. 28,41; 29,21.30"] },
      { number: 31, text: "Zu den Söhnen Israel sollst du so reden: Ein Öl der heiligen Salbung soll dies für mich* sein, für all eure Generationen.", footnotes: ["LXX: für euch"] },
      { number: 32, text: "Auf den Leib* eines Menschen darf man es nicht gießen, und ihr dürft nichts herstellen, was ihm in seiner Zusammensetzung gleich ist: heilig ist es, heilig soll es euch sein.", footnotes: ["w. Auf das Fleisch"] },
      { number: 33, text: "Wer sonst eine Mischung wie diese herstellt oder etwas davon auf einen Fremden* streicht, der soll aus seinen Völkern* ausgerottet werden*.", footnotes: ["o. auf einen Unbefugten", "d. h. aus seiner Volksgemeinschaft", "℘ Kap. 12,15.19; 31,14; 1Mo 17,14; 3Mo 7,20; 17,4; 4Mo 4,18; 9,13; Apg 3,23"] },
      { number: 34, text: "Und der HERR sprach zu Mose: Nimm dir wohlriechende Stoffe: Staktetropfen, Räucherklaue, wohlriechendes Galbanum* und reinen Weihrauch — zu gleichen Teilen soll es sein —,", footnotes: ["Staktetropfen: d. i. ein wohlriechendes Harz; w. Tropfen. Räucherklaue: d. i. vermutlich der Deckel von einer Flügelschneckenart, der stark riecht, wenn man ihn verbrennt. Galbanum: d. i. ein Harz."] },
      { number: 35, text: "und mache Räucherwerk daraus*, eine würzige Mischung, ein Werk des Salbenmischers*, gesalzen*, rein, heilig.", footnotes: ["℘ 3Mo 16,12", "℘ Kap. 28,41; 1Kö 1,39; 1Chr 9,30; Ps 133,2", "℘ 3Mo 2,13"] },
      { number: 36, text: "Dann zerstoße etwas davon zu Pulver und lege etwas davon vor das Zeugnis in das Zelt der Begegnung, wo ich dir begegnen werde*; als Hochheiliges soll es euch gelten.", footnotes: ["℘ V. 6"] },
      { number: 37, text: "Was aber das Räucherwerk, das du machen sollst, angeht — in seiner Zusammensetzung dürft ihr keins für euch herstellen; als etwas Heiliges für den HERRN soll es dir gelten." },
      { number: 38, text: "Wer etwas Derartiges macht, um daran zu riechen, der soll aus seinen Völkern* ausgerottet werden*.", footnotes: ["d. h. aus seiner Volksgemeinschaft", "℘ Kap. 12,15.19; 31,14; 1Mo 17,14; 3Mo 7,20; 17,4; 4Mo 4,18; 9,13; Apg 3,23"] },
    ]},
    { number: 31, verses: [
      { number: 1, text: "*Und der HERR redete zu Mose und sprach:", heading: "Heiligtum: Berufung der Werkmeister Bezalel und Oholiab", footnotes: ["℘ Kap. 35,10-19.30-35"] },
      { number: 2, text: "Siehe, ich habe mit Namen berufen Bezalel, den Sohn des Uri, des Sohnes Hurs, vom Stamm Juda*,", footnotes: ["℘ Kap. 38,22; 1Chr 2,20; 2Chr 1,5"] },
      { number: 3, text: "und habe ihn mit dem Geist Gottes erfüllt, mit Weisheit, Verstand und Können* und für jedes Kunsthandwerk*,", footnotes: ["w. Erkenntnis", "w. in jedem Werk; so auch V. 5; verschiedene Üs. lassen das »und« weg\n℘ 1Kö 7,13.14; Spr 2,6"] },
      { number: 4, text: "Pläne zu entwerfen*, um in Gold, Silber und Bronze zu arbeiten.", footnotes: ["w. Erfindungen zu erfinden"] },
      { number: 5, text: "Auch mit der Fertigkeit zum Schneiden von Steinen zum Einsetzen und mit der Holzschnitzerei habe ich ihn begabt, damit er in jedem Handwerk arbeiten kann*.", footnotes: ["℘ 2Chr 2,6.13"] },
      { number: 6, text: "Und ich, siehe, ich habe ihm Oholiab*, den Sohn des Ahisamach, vom Stamm Dan, als Mitarbeiter gegeben. Dazu habe ich jedem, der ein weises Herz hat*, Weisheit ins Herz gelegt, damit sie alles machen, was ich dir geboten habe:", footnotes: ["℘ Kap. 38,23", "℘ Kap. 28,3"] },
      { number: 7, text: "*das Zelt der Begegnung, die Lade des Zeugnisses, die Deckplatte* darauf und alle Geräte des Zeltes;", footnotes: ["℘ V. 7-11: Kap. 39,32-43; 40,3-30", "s. Anm. zu Kap. 25,17"] },
      { number: 8, text: "dazu den Tisch und all seine Geräte, den Leuchter aus reinem Gold und all seine Geräte und den Räucheraltar;" },
      { number: 9, text: "den Brandopferaltar und all seine Geräte, das Becken und sein Gestell;" },
      { number: 10, text: "auch die gewirkten Kleider* und die heiligen Kleider* für den Priester Aaron und die Kleider seiner Söhne zur Ausübung des Priesterdienstes", footnotes: ["5 hebr. Handschr. lesen: die gewirkten Kleider für den heiligen Dienst, o. für den Dienst im Heiligtum", "o. nämlich die heiligen Gewänder. — LXX lässt diese Wörter weg."] },
      { number: 11, text: "und das Salböl und das wohlriechende Räucherwerk für das Heiligtum. Nach allem, was ich dir geboten habe, sollen sie es machen*.", footnotes: ["℘ Kap. 25,40; 36,1.2"] },
      { number: 12, text: "*Und der HERR redete zu Mose und sprach:", heading: "Sabbatgebot und Gesetzestafeln", footnotes: ["℘ V. 12-17: Kap. 20,8-11"] },
      { number: 13, text: "Du aber, rede zu den Söhnen Israel und sage ihnen: Haltet nur ja meine Sabbate!* Denn sie sind* ein Zeichen zwischen mir und euch für all eure Generationen, damit man erkenne, dass ich, der HERR, es bin, der euch heiligt*.", footnotes: ["℘ 3Mo 19,3.30; 26,2", "w. er ist", "℘ 3Mo 20,8; Hes 20,20"] },
      { number: 14, text: "Haltet also den Sabbat, denn heilig ist er euch*. Wer ihn entweiht, muss getötet werden*, ja, jeder, der an ihm eine Arbeit verrichtet, eine solche Seele soll aus der Mitte seiner Völker* ausgerottet werden*.", footnotes: ["o. ja, als heilig soll er euch gelten", "℘ 4Mo 15,35", "d. h. aus der Mitte seiner Volksgemeinschaft", "℘ Kap. 30,33.38"] },
      { number: 15, text: "Sechs Tage soll man seine Arbeit verrichten, aber am siebten Tag ist Sabbat, ein Tag völliger Ruhe*, heilig dem HERRN. Jeder, der am Tag des Sabbats eine Arbeit verrichtet, muss getötet werden.", footnotes: ["w. Sabbat der Sabbatfeier"] },
      { number: 16, text: "So sollen denn die Söhne Israel den Sabbat halten, um den Sabbat in all ihren Generationen zu feiern, als ewigen Bund*.", footnotes: ["℘ Neh 13,15.18"] },
      { number: 17, text: "Er ist ein Zeichen zwischen mir und den Söhnen Israel für ewig. Denn in sechs Tagen hat der HERR den Himmel und die Erde gemacht, am siebten Tag aber hat er geruht und Atem geschöpft*.", footnotes: ["℘ Hebr 4,4"] },
      { number: 18, text: "Und als er auf dem Berg Sinai mit Mose zu Ende geredet hatte, gab er ihm die zwei Tafeln des Zeugnisses*, steinerne Tafeln, beschrieben mit dem Finger Gottes*.", footnotes: ["℘ Joh 1,17", "℘ Kap. 24,12; 32,15.16; 34,1-4.28.29; 5Mo 4,13; 9,10; 10,4; 2Kor 3,3"] },
    ]},
    { number: 32, verses: [
      { number: 1, text: "*Als nun das Volk sah, dass Mose säumte, vom Berg herabzukommen*, versammelte sich das Volk zu Aaron, und sie sagten zu ihm: Auf! Mache uns Götter*, die vor uns herziehen*! Denn dieser Mose, der Mann, der uns aus dem Land Ägypten heraufgeführt hat — wir wissen nicht*, was ihm geschehen ist*.", heading: "Goldenes Kalb — Moses Fürbitte — Gottes Gericht", footnotes: ["℘ 5Mo 9", "℘ Kap. 24,18", "o. einen Gott. — Vielleicht soll durch die Mehrzahl die Verehrung des Kalbes verächtlich als Vielgötterei gebrandmarkt werden.", "℘ Kap. 13,21; 5Mo 31,8", "o. wir haben nicht erkannt", "℘ V. 23; Apg 7,40"] },
      { number: 2, text: "Und Aaron sagte zu ihnen: Reißt die goldenen Ringe ab, die an den Ohren eurer Frauen, *eurer Söhne* und eurer Töchter sind, und bringt sie zu mir!", footnotes: ["in LXX nicht enthalten", "in LXX nicht enthalten"] },
      { number: 3, text: "So riss sich denn das ganze Volk die goldenen Ringe ab, die an ihren Ohren hingen, und sie brachten sie zu Aaron*.", footnotes: ["℘ Jes 3,19"] },
      { number: 4, text: "Der nahm alles aus ihrer Hand, formte es mit einem Meißel und machte ein gegossenes Kalb* daraus*. Und sie sagten: Das ist dein Gott*, Israel, der dich aus dem Land Ägypten heraufgeführt hat*.", footnotes: ["o. (mit geringer Veränderung): schmolz es in einem Behälter ein. — »Kalb« ist wohl eine verächtliche Bezeichnung für ein Stierbild.", "℘ Kap. 20,4.23; Ri 8,24-27; Ps 106,19", "o. sind deine Götter, die ... haben", "℘ 1Kö 12,28; Neh 9,18; Jes 46,6"] },
      { number: 5, text: "Als Aaron das sah, baute er einen Altar vor ihm, und Aaron rief aus und sagte: Ein Fest für den HERRN ist morgen*!", footnotes: ["℘ 1Kö 12,32.33"] },
      { number: 6, text: "So standen sie am folgenden Tag früh auf, opferten Brandopfer und brachten Heilsopfer* dar. Und das Volk setzte sich nieder, um zu essen und zu trinken. Dann standen sie auf, um sich zu belustigen*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Apg 7,41; 1Kor 10,7"] },
      { number: 7, text: "Da sprach der HERR zu Mose: Geh, steig hinab! Denn dein Volk, das du aus dem Land Ägypten heraufgeführt hast*, hat schändlich* gehandelt*.", footnotes: ["℘ Kap. 33,1", "w. verderbt", "℘ 5Mo 4,16; 31,29; 2Chr 27,2; Jes 1,4; Hos 9,9"] },
      { number: 8, text: "Sie sind schnell von dem Weg abgewichen, den ich ihnen geboten habe*. Sie haben sich ein gegossenes Kalb gemacht*, sind vor ihm niedergefallen, haben ihm geopfert und gesagt: Das sind deine Götter, Israel, die dich aus dem Land Ägypten heraufgeführt haben*!", footnotes: ["℘ Ri 2,17.19; Jer 31,32", "℘ 1Kö 12,28; Neh 9,18; Jes 46,6", "℘ 1Kö 12,28; Neh 9,18; Jes 46,6"] },
      { number: 9, text: "Weiter sagte der HERR zu Mose: Ich habe dieses Volk gesehen, und siehe, es ist ein halsstarriges Volk*.", footnotes: ["℘ Kap. 33,3.5; 34,9; 5Mo 31,27; 2Chr 30,8; Neh 9,16.17; Apg 7,51"] },
      { number: 10, text: "Und nun lass mich, damit mein Zorn gegen sie entbrenne und ich sie vernichte*, dich aber will ich zu einer großen Nation machen*.", footnotes: ["℘ 4Mo 16,21", "℘ 1Mo 12,2; 4Mo 14,12"] },
      { number: 11, text: "Mose jedoch flehte den HERRN, seinen Gott*, an* und sagte: Wozu, HERR, entbrennt dein Zorn gegen dein Volk, das du mit großer Kraft und starker Hand aus dem Land Ägypten herausgeführt hast*?", footnotes: ["o. besänftigte den HERRN, seinen Gott", "℘ Kap. 8,8; 4Mo 21,7; Jer 15,1", "℘ Kap. 6,6; 4Mo 14,13; Ps 74,1.2; 106,23; Dan 9,15"] },
      { number: 12, text: "Wozu sollen die Ägypter sagen: In böser Absicht* hat er sie herausgeführt, um sie im Gebirge umzubringen und sie von der Fläche des Erdbodens zu vertilgen*? Lass ab von der Glut deines Zornes und lass dich das Unheil gereuen*, das du über dein Volk bringen willst!", footnotes: ["o. Zum Unglück; w. Im Bösen", "℘ 4Mo 14,16; 5Mo 32,26.27; Jos 7,9", "℘ 4Mo 14,19; Jos 7,26; Ps 90,13; Jes 64,7.8"] },
      { number: 13, text: "Denke an deine Knechte Abraham, Isaak und Israel, denen du bei dir selbst geschworen und denen du gesagt hast*: Ich will eure Nachkommen so zahlreich machen wie die Sterne des Himmels*, und dieses ganze Land, von dem ich gesagt habe: »Ich werde es euren Nachkommen geben«, das werden sie* für ewig in Besitz nehmen*.", footnotes: ["℘ 1Mo 22,16.17", "℘ 1Mo 15,5", "o. von dem ich geredet habe, das werde ich . . ., und sie werden", "℘ Kap. 33,1; 1Mo 15,7; 17,8"] },
      { number: 14, text: "Da gereute* den HERRN das Unheil, von dem er gesagt hatte, er werde es seinem Volk antun*.", footnotes: ["℘ 1Mo 6,6", "℘ 4Mo 14,20; 5Mo 10,10; 32,36; Ri 2,18; 2Sam 24,16; Ps 106,23; Jer 18,8; Am 7,3.6; Jak 5,16"] },
      { number: 15, text: "Und Mose wandte sich um und stieg vom Berg hinab, die beiden Tafeln* des Zeugnisses in seiner Hand, Tafeln, beschrieben auf ihren beiden Seiten; vorn und hinten waren sie beschrieben.", footnotes: ["℘ Kap. 24,12; 34,29"] },
      { number: 16, text: "Diese Tafeln waren Gottes Werk, und die Schrift, sie war Gottes Schrift*, auf den Tafeln eingegraben.", footnotes: ["℘ Kap. 31,18"] },
      { number: 17, text: "Als nun Josua die Stimme des Volkes bei seinem Lärmen hörte, sagte er zu Mose: Kriegslärm ist im Lager!" },
      { number: 18, text: "Der aber antwortete: Es ist kein Schall von Siegesgeschrei* und kein Schall vom Geschrei* bei einer Niederlage; den Schall von Gesang* höre ich.", footnotes: ["w. Siegesgesang bzw. Gesang", "w. Siegesgesang bzw. Gesang", "LXX: des Weines"] },
      { number: 19, text: "Und es geschah, als Mose sich dem Lager näherte und das Kalb und die Reigentänze sah, da entbrannte der Zorn Moses, und er warf die Tafeln aus seinen Händen und zerschmetterte sie unten am Berg*.", footnotes: ["℘ Kap. 34,1; 5Mo 10,2"] },
      { number: 20, text: "Dann nahm er das Kalb, das sie gemacht hatten, verbrannte es im Feuer und zermalmte es, bis es feiner Staub war, streute es auf die Oberfläche des Wassers und gab es den Söhnen Israel zu trinken." },
      { number: 21, text: "Und Mose sagte zu Aaron: Was hat dir dieses Volk getan, dass du eine so große Sünde über es gebracht hast?" },
      { number: 22, text: "Aaron aber sagte: Der Zorn meines Herrn entbrenne nicht*. Du selbst kennst das Volk, dass es böse* ist*.", footnotes: ["℘ 1Mo 44,18", "o. in übler Lage; w. im Bösen", "℘ V. 1"] },
      { number: 23, text: "Sie haben nämlich zu mir gesagt: Mach uns Götter, die vor uns hergehen! Denn dieser Mose, der Mann, der uns aus dem Land Ägypten heraufgeführt hat — wir wissen nicht*, was ihm geschehen ist.", footnotes: ["o. wir haben nicht erkannt"] },
      { number: 24, text: "Da fragte ich sie: Wer hat Gold? Sie rissen es sich ab und gaben es mir, und ich warf es ins Feuer, und dieses Kalb ist daraus hervorgegangen." },
      { number: 25, text: "Als nun Mose sah, dass das Volk zuchtlos war, denn Aaron hatte es zuchtlos werden lassen* zur Schadenfreude ihrer Gegner*,", footnotes: ["℘ 2Chr 28,19", "so mit alten Üs.; andere Üs.: zum schmutzigen Namen unter ihren Gegnern. Die Bedeutung des hebr. Wortes ist unsicher."] },
      { number: 26, text: "da trat Mose in das Tor des Lagers und rief: Her zu mir, wer für den HERRN ist! Daraufhin versammelten sich bei ihm alle Söhne Levis." },
      { number: 27, text: "Und er sagte zu ihnen: So spricht der HERR, der Gott Israels: Ein jeder lege sein Schwert an die Hüfte! Geht im Lager hin und zurück, von Tor zu Tor, und erschlagt jeder seinen Bruder und seinen Freund und seinen Verwandten*!", footnotes: ["℘ 4Mo 25,5; 5Mo 13,6-12; 2Kö 10,25.26; Hes 9,5; Lk 14,26"] },
      { number: 28, text: "Die Söhne Levis nun handelten nach dem Wort des Mose*; und es fielen vom Volk an jenem Tage etwa dreitausend Mann.", footnotes: ["℘ 5Mo 33,9"] },
      { number: 29, text: "Darauf sagte Mose: Weiht euch* heute für den HERRN — denn jeder von euch ist gegen seinen Sohn und gegen seinen Bruder gewesen* —, um heute Segen auf euch zu bringen*!", footnotes: ["w. füllt eure Hand; vgl. die Anm. zu Kap. 28,41", "o. ja, jeder sei gegen seinen Sohn und gegen seinen Bruder; o. ja, jeder um den Preis seines Sohnes und seines Bruders; o. in seinem Sohn und in seinem Bruder", "℘ 2Chr 35,3"] },
      { number: 30, text: "Und es geschah am folgenden Tag, da sagte Mose zum Volk: Ihr habt eine große Sünde begangen*. Doch jetzt will ich zum HERRN hinaufsteigen, vielleicht kann ich Sühnung für eure Sünde erwirken.", footnotes: ["℘ 1Sam 12,17"] },
      { number: 31, text: "Darauf kehrte Mose zum HERRN zurück und sagte: Ach, dieses Volk hat eine große Sünde begangen*: Sie haben sich einen Gott aus Gold gemacht.", footnotes: ["℘ Esr 9,6; Neh 9,33"] },
      { number: 32, text: "Und nun, wenn du doch ihre Sünde vergeben wolltest! Wenn aber nicht, so lösche mich denn aus deinem Buch, das du geschrieben hast, aus*.", footnotes: ["℘ 4Mo 11,25; Jes 4,3; Dan 12,1; Lk 10,20; Röm 9,3"] },
      { number: 33, text: "Der HERR aber sprach zu Mose: Wer gegen mich gesündigt hat, den lösche ich aus meinem Buch aus*.", footnotes: ["℘ Ps 69,29; Hes 18,20"] },
      { number: 34, text: "Und nun gehe hin, führe das Volk an den Ort, den ich dir genannt habe*! Siehe, mein Engel wird vor dir hergehen*. Am Tag meiner Heimsuchung, da werde ich ihre Sünde an ihnen heimsuchen*.", footnotes: ["℘ Kap. 33,12", "℘ Kap. 23,20", "℘ Jer 14,10; 23,2.12; Hos 8,13; Am 3,2"] },
      { number: 35, text: "Und der HERR schlug das Volk* mit Unheil dafür, dass sie das Kalb gemacht hatten*, das Aaron gemacht hatte.", footnotes: ["℘ 4Mo 25,9", "Mehrere Üs. lesen: dass sie dem Kalb gedient hatten"] },
    ]},
    { number: 33, verses: [
      { number: 1, text: "Und der HERR redete zu Mose: Geh, ziehe von hier hinauf, du und das Volk, das du aus dem Land Ägypten heraufgeführt hast*, in das Land, von dem ich Abraham, Isaak und Jakob geschworen habe*: Deinen Nachkommen will ich es geben*!", heading: "Trauer des Volkes — Zelt außerhalb des Lagers — Moses Verhandlung mit Gott und sein Begehren, die Herrlichkeit Gottes zu sehen", footnotes: ["℘ Kap. 32,7; 5Mo 1,8", "℘ Kap. 34,1; 5Mo 10,2", "℘ Kap. 32,13; 1Mo 50,24"] },
      { number: 2, text: "— Und ich werde einen Engel vor dir hersenden* und die Kanaaniter, Amoriter, Hetiter, Perisiter, Hewiter und Jebusiter vertreiben* —", footnotes: ["℘ Kap. 23,20", "℘ 1Mo 15,21; Ri 6,9"] },
      { number: 3, text: "in ein Land, das von Milch und Honig überfließt*. Denn ich werde nicht in deiner Mitte hinaufziehen — du bist nämlich ein halsstarriges Volk* —, damit ich dich nicht auf dem Wege vernichte*.", footnotes: ["℘ Kap. 3,8.17", "℘ Kap. 32,9; Jes 48,4; Apg 7,51", "℘ 5Mo 4,24; Hebr 10,30.31; 12,29"] },
      { number: 4, text: "Als das Volk diese böse Rede hörte, trauerten sie*, und keiner legte seinen Schmuck an*.", footnotes: ["℘ 4Mo 14,39; 1Sam 6,19", "℘ 1Kö 21,27; Jes 32,11"] },
      { number: 5, text: "Denn der HERR hatte zu Mose gesagt*: Sprich zu den Söhnen Israel: Ihr seid ein halsstarriges Volk*. Zöge ich nur einen Augenblick in deiner Mitte hinauf, so würde ich dich vernichten. Und nun lege deinen Schmuck von dir ab, und ich werde zusehen*, was ich für dich tun kann*.", footnotes: ["o. Da sprach der HERR zu Mose", "℘ Kap. 32,9; Jes 48,4; Apg 7,51", "w. erkennen", "℘ Joe 2,12"] },
      { number: 6, text: "Da entledigten sich die Söhne Israel ihres Schmuckes, vom Berg Horeb an*.", footnotes: ["℘ Jon 3,5-9"] },
      { number: 7, text: "Mose nun nahm jeweils das Zelt und schlug es sich außerhalb des Lagers auf, fern vom Lager für sich*, und nannte es: Zelt der Begegnung. Und es geschah, jeder, der den HERRN suchte, ging zum Zelt der Begegnung außerhalb des Lagers* hinaus.", footnotes: ["o. für ihn; d. h. für den HERRN", "℘ Hebr 13,13"] },
      { number: 8, text: "Es geschah auch, sooft Mose zum Zelt hinausging, dann standen alle Leute auf, und sie traten jeder an den Eingang seines Zeltes und sahen Mose nach, bis er in das Zelt hineinkam." },
      { number: 9, text: "Und es geschah jedes Mal, wenn Mose in das Zelt kam, dann stieg die Wolkensäule herab und blieb am Eingang des Zeltes stehen*; und der HERR redete mit Mose*.", footnotes: ["℘ 5Mo 31,15", "℘ 4Mo 7,89; Ps 99,7"] },
      { number: 10, text: "Und das ganze Volk sah die Wolkensäule am Eingang des Zeltes stehen. Und das ganze Volk erhob sich, und sie warfen sich nieder, jeder am Eingang seines Zeltes." },
      { number: 11, text: "Und der HERR redete mit Mose von Angesicht zu Angesicht*, wie ein Mann mit seinem Freund redet; dann kehrte er, Mose, ins Lager zurück. Sein Diener Josua aber, der Sohn des Nun, ein junger Mann, wich nicht aus dem Innern des Zeltes*.", footnotes: ["℘ 5Mo 34,10; 4Mo 12,7.8", "℘ Kap. 17,9; 5Mo 31,14"] },
      { number: 12, text: "Mose nun sagte zum HERRN: Siehe, du sagst zu mir: Führe dieses Volk hinauf*! — aber du hast mich nicht erkennen lassen, wen du mit mir senden willst, wo du doch selbst gesagt hast: Ich kenne dich mit Namen*, ja, du hast Gunst gefunden in meinen Augen*.", footnotes: ["℘ Kap. 32,34", "℘ Kap. 3,4; Joh 10,14", "℘ Kap. 34,9; 2Sam 15,25"] },
      { number: 13, text: "Und nun, wenn ich also Gunst gefunden habe in deinen Augen*, dann lass mich doch* deine Wege erkennen*, so dass ich dich erkenne, damit ich Gunst finde in deinen Augen, und bedenke, dass diese Nation dein Volk ist*!", footnotes: ["℘ Kap. 34,9; 2Sam 15,25", "o. Und nun, möge ich doch Gunst finden in deinen Augen. Lass mich doch. — Diese Üs. ist auch in Kap. 34,9 möglich.", "℘ Ps 25,4; 103,7; Joh 14,5", "℘ 5Mo 9,29"] },
      { number: 14, text: "Er antwortete: Mein Angesicht* wird mitgehen* und dich zur Ruhe bringen.*", footnotes: ["d. h. ich selbst", "℘ Jes 63,9", "o. Wenn mein Angesicht mitgeht, werde ich dich dann zur Ruhe bringen?\n℘ Hi 34,29; Dan 12,13"] },
      { number: 15, text: "Er aber sagte zu ihm: Wenn dein Angesicht nicht mitgeht, dann führe uns nicht von hier hinauf*!", footnotes: ["℘ 2Kö 6,3"] },
      { number: 16, text: "Woran soll man denn sonst erkennen, dass ich Gunst gefunden habe in deinen Augen, ich und dein Volk? Nicht daran, dass du mit uns gehst* und wir, ich und dein Volk, dadurch vor jedem Volk auf dem Erdboden ausgezeichnet* werden?*", footnotes: ["℘ Kap. 34,9; 4Mo 14,14", "o. besonders behandelt", "℘ 4Mo 23,9; 2Sam 7,23"] },
      { number: 17, text: "Der HERR antwortete Mose: Auch diesen Wunsch, den* du jetzt ausgesprochen hast, werde ich erfüllen*; denn du hast Gunst gefunden in meinen Augen, und ich kenne dich mit Namen.", footnotes: ["w. diese Sache, die", "℘ 1Mo 19,21; 5Mo 9,19; 1Jo 5,14"] },
      { number: 18, text: "Er aber sagte: Lass mich doch deine Herrlichkeit sehen*!", footnotes: ["℘ Ps 63,3; Joh 1,14; Apg 7,55"] },
      { number: 19, text: "Er antwortete: Ich werde all meine Güte an deinem Angesicht vorübergehen lassen und den Namen Jahwe vor dir ausrufen*: Ich werde* gnädig sein, wem ich gnädig bin, und mich erbarmen, über wen ich mich erbarme*.", footnotes: ["℘ Kap. 34,5-7", "o. ausrufen. Und ich werde", "℘ Röm 9,15"] },
      { number: 20, text: "Dann sprach er: Du kannst es nicht ertragen, mein Angesicht zu sehen, denn kein Mensch kann mich sehen und am Leben bleiben*.", footnotes: ["℘ Kap. 3,6; 24,9-11; Ri 6,22; 13,22; Jes 6,5; 1Tim 6,16; 1Jo 4,12"] },
      { number: 21, text: "Weiter sagte der HERR: Siehe, hier ist ein Platz bei mir, da sollst du dich auf den Felsen stellen." },
      { number: 22, text: "Und es wird geschehen, wenn meine Herrlichkeit vorüberzieht, dann werde ich dich in die Felsenhöhle stellen und meine Hand schützend über dich halten, bis ich vorübergegangen bin." },
      { number: 23, text: "Dann werde ich meine Hand wegnehmen, und du wirst mich von hinten sehen; aber mein Angesicht darf nicht gesehen werden." },
    ]},
    { number: 34, verses: [
      { number: 1, text: "Darauf sprach der HERR zu Mose: Haue dir zwei steinerne Tafeln wie die ersten zurecht! Dann werde ich auf die Tafeln die Worte schreiben, die auf den ersten Tafeln standen*, die du zerschmettert hast*.", heading: "Neue Gesetzestafeln — Gotteserscheinung — Erneuerung des Bundes — Moses glänzendes Gesicht", footnotes: ["℘ Kap. 24,12; 31,18", "℘ Kap. 32,19"] },
      { number: 2, text: "Und halte dich für den Morgen bereit, und steige am Morgen auf den Berg Sinai und stehe dort vor mir auf dem Gipfel des Berges!" },
      { number: 3, text: "Es soll aber niemand mit dir hinaufsteigen, und es darf überhaupt niemand auf dem ganzen Berg gesehen werden; sogar Schafe und Rinder dürfen nicht in Richtung auf diesen Berg hin weiden*.", footnotes: ["℘ Kap. 19,12.13"] },
      { number: 4, text: "So hieb er denn zwei steinerne Tafeln wie die ersten zurecht. Und Mose stand früh am Morgen auf und stieg auf den Berg Sinai*, wie ihm der HERR geboten hatte, und nahm die zwei steinernen Tafeln in seine Hand*.", footnotes: ["℘ Kap. 19,3", "℘ 5Mo 10,3"] },
      { number: 5, text: "Da stieg der HERR in der Wolke herab, und er trat dort neben ihn und rief den Namen des HERRN aus*.", footnotes: ["℘ Kap. 33,19; 5Mo 32,3"] },
      { number: 6, text: "Und der HERR ging vor seinem Angesicht vorüber* und rief*: Jahwe, Jahwe, Gott, barmherzig und gnädig*, langsam zum Zorn und reich an Gnade und Treue*,", footnotes: ["℘ 4Mo 12,8", "o. und er (Mose) rief", "℘ 5Mo 4,31; 2Sam 24,14; 2Chr 30,9; Ps 62,13; 116,5", "o. Wahrheit\n℘ 1Mo 24,27; Ps 86,15; Spr 3,3; Joe 2,13; Joh 1,17; Röm 2,4"] },
      { number: 7, text: "der Gnade bewahrt an Tausenden von Generationen*, der Schuld, Vergehen und Sünde vergibt*, aber keineswegs ungestraft lässt*, sondern die Schuld der Väter heimsucht an den Kindern und Kindeskindern, an der dritten und vierten Generation*.", footnotes: ["℘ Kap. 20,6", "℘ Ps 25,11; 130,4; 1Jo 1,9", "℘ 1Kö 8,32; Ps 99,8; Jer 30,11; Nah 1,2.3", "℘ Kap. 20,5"] },
      { number: 8, text: "Da warf sich Mose eilends zur Erde nieder, betete an*", footnotes: ["℘ Kap. 4,31"] },
      { number: 9, text: "und sagte: Wenn ich doch Gunst gefunden habe in deinen Augen*, Herr, so möge doch der Herr in unserer Mitte mitgehen*! Wenn es auch ein halsstarriges Volk ist*, vergib uns aber dennoch unsere Schuld und Sünde und nimm uns als Erbe* an!", footnotes: ["℘ Kap. 33,13", "℘ Kap. 33,15.16", "o. Denn es ist ein halsstarriges Volk\n℘ Kap. 32,9", "o. Eigentum\n℘ Kap. 19,5; Ps 33,12; Jer 10,16"] },
      { number: 10, text: "Er sprach: Siehe, ich schließe einen Bund*: Vor deinem ganzen Volk will ich Wunder tun, wie sie bisher nicht vollbracht* worden sind auf der ganzen Erde und unter allen Nationen. Und das ganze Volk, in dessen Mitte du lebst, soll das Tun des HERRN sehen; denn* furchterregend ist, was ich an dir tun werde*.", footnotes: ["℘ 5Mo 5,2.3", "w. geschaffen", "o. dass", "℘ 5Mo 10,21; Offb 15,3"] },
      { number: 11, text: "Beachte genau, was ich dir heute gebiete! Siehe, ich will vor dir die Amoriter, Kanaaniter, Hetiter, Perisiter, Hewiter und Jebusiter vertreiben*.", footnotes: ["℘ 1Mo 15,21; Jos 23,5"] },
      { number: 12, text: "Hüte dich, mit den Bewohnern des Landes, in das du kommen wirst, einen Bund zu schließen, damit sie nicht zur Falle* werden in deiner Mitte*!", footnotes: ["d. i. das Stellholz eines Vogelstellers", "℘ Kap. 23,32.33"] },
      { number: 13, text: "Vielmehr sollt ihr ihre Altäre niederreißen, ihre Gedenksteine* zertrümmern und ihre Ascherim ausrotten*.", footnotes: ["hebr. mazzebot; das sind aufrecht hingestellte Steine, die kultisch verehrt wurden", "℘ Kap. 23,24; 4Mo 33,52; Ri 6,25; 2Kö 10,27"] },
      { number: 14, text: "Denn du darfst dich vor keinem andern Gott anbetend niederwerfen*; denn der HERR, dessen Name »Eifersüchtig« ist, ist ein eifersüchtiger Gott*.", footnotes: ["℘ Ri 6,10; Mt 4,10", "℘ Kap. 20,5; 5Mo 4,24; Jos 24,19; Nah 1,2"] },
      { number: 15, text: "Dass du ja keinen Bund mit den Bewohnern des Landes schließt*! Denn dann könnte man dich einladen, und du könntest, wenn sie ihren Göttern nachhuren und ihren Göttern opfern, von ihren Schlachtopfern essen*.", footnotes: ["o. Sonst könntest du nämlich . . . schließen", "℘ 4Mo 25,1.2; 5Mo 31,16; Ps 106,28; 1Kor 10,20-22; Offb 2,20"] },
      { number: 16, text: "Und du könntest von ihren Töchtern für deine Söhne Frauen nehmen*, und wenn dann ihre Töchter ihren Göttern nachhuren, könnten sie deine Söhne dazu verführen, ihren Göttern nachzuhuren*.", footnotes: ["℘ 1Mo 24,3; Jos 23,12; 3Mo 21,15", "℘ 5Mo 7,3.4; Ri 3,5-7; 8,27; Neh 10,31"] },
      { number: 17, text: "Gegossene Götter sollst du dir nicht machen*.", footnotes: ["℘ Kap. 20,4.23; 3Mo 19,4"] },
      { number: 18, text: "*Das Fest der ungesäuerten Brote sollst du halten; sieben Tage sollst du ungesäuertes Brot essen, wie ich dir geboten habe, zur festgesetzten Zeit des Monats Abib; denn im Monat Abib bist du aus Ägypten ausgezogen. —", footnotes: ["℘ V. 18-26: Kap. 23,14-19"] },
      { number: 19, text: "Alles, was zuerst den Mutterschoß durchbricht, gehört mir; auch all dein männliches Vieh, die Erstgeburt von Rind und Schaf*.", footnotes: ["So mit LXX, Vulg. und aram. Üs. Eine alte Handschrift liest: all dein Vieh erinnere an die Erstgeburt; Mas. T. ist fehlerhaft und könnte auch üs. werden: auch an dein Vieh erinnere dich, an Rind und Schaf\n℘ Kap. 13,2"] },
      { number: 20, text: "Die Erstgeburt vom Esel aber sollst du mit einem Schaf auslösen. Wenn du sie jedoch nicht auslösen willst, dann brich ihr das Genick! Alle Erstgeburt deiner Söhne sollst du auslösen*. Und man soll nicht mit leeren Händen vor meinem Angesicht erscheinen.", footnotes: ["℘ Kap. 13,12.13"] },
      { number: 21, text: "Sechs Tage sollst du arbeiten, aber am siebten Tag sollst du ruhen*; auch in der Zeit des Pflügens und in der Ernte sollst du ruhen.", footnotes: ["℘ Kap. 20,9.10"] },
      { number: 22, text: "Auch das Wochenfest*, das Fest der Erstlinge der Weizenernte, sollst du feiern, ferner das Fest des Einsammelns und die Wende des Jahres*.", footnotes: ["℘ 3Mo 23,15.16", "w. der Drehung; d. h. der Tagundnachtgleiche (hier: im Herbst)"] },
      { number: 23, text: "Dreimal im Jahr soll alles bei dir, was männlich ist, vor dem Angesicht des Herrn, HERRN, des Gottes Israels, erscheinen." },
      { number: 24, text: "Denn ich werde die Nationen vor dir austreiben und deine Grenze erweitern*. Und niemand wird dein Land begehren, wenn du dreimal im Jahr hinaufziehst, um vor dem Angesicht des HERRN, deines Gottes, zu erscheinen.", footnotes: ["℘ Kap. 23,27-31; 5Mo 12,20; 1Kö 5,1"] },
      { number: 25, text: "Du sollst das Blut meines Schlachtopfers nicht zusammen mit Gesäuertem darbringen*, und das Schlachtopfer des Passahfestes darf nicht über Nacht bleiben bis zum nächsten Morgen.", footnotes: ["w. schlachten"] },
      { number: 26, text: "Das Erste* der Erstlinge deines Landes sollst du in das Haus des HERRN, deines Gottes, bringen. Du sollst ein Böckchen nicht in der Milch seiner Mutter kochen.", footnotes: ["d. h. Das Beste"] },
      { number: 27, text: "Und der HERR sprach zu Mose: Schreibe dir diese Worte auf*! Denn nach diesen Worten schließe ich mit dir und mit Israel einen Bund.", footnotes: ["℘ Kap. 24,4"] },
      { number: 28, text: "Und Mose* blieb vierzig Tage und vierzig Nächte dort beim HERRN*. Brot aß er nicht, und Wasser trank er nicht*. Und er schrieb auf die Tafeln die Worte des Bundes, die zehn Worte*.", footnotes: ["w. er", "℘ Kap. 24,18", "℘ 5Mo 9,9.18; Mt 4,2", "℘ V. 1; Kap. 31,18; Joh 1,17"] },
      { number: 29, text: "Es geschah aber, als Mose vom Berg Sinai herabstieg — und die beiden Tafeln des Zeugnisses waren in Moses Hand, als er vom Berg herabstieg* —, da wusste* Mose nicht, dass die Haut seines Gesichtes strahlend geworden war, als* er mit ihm geredet hatte*.", footnotes: ["℘ Kap. 32,15", "o. erkannte", "o. weil", "℘ 2Kor 3,7"] },
      { number: 30, text: "Und Aaron und alle Söhne Israel sahen Mose an, und siehe, die Haut seines Gesichtes strahlte*; und sie fürchteten sich, zu ihm heranzutreten.", footnotes: ["℘ 2Kor 3,7"] },
      { number: 31, text: "Mose jedoch rief ihnen zu, und Aaron und alle Fürsten in der Gemeinde wandten sich ihm zu, und Mose redete zu ihnen." },
      { number: 32, text: "Danach aber traten alle Söhne Israel heran, und er gebot ihnen alles, was der HERR auf dem Berg Sinai zu ihm geredet hatte*.", footnotes: ["℘ Kap. 35,1"] },
      { number: 33, text: "Als nun Mose aufgehört hatte, mit ihnen zu reden, legte er eine Decke auf sein Gesicht." },
      { number: 34, text: "Sooft aber Mose vor den HERRN hineinging, um mit ihm zu reden, legte er die Decke ab*, bis er hinausging. Dann ging er hinaus, um zu den Söhnen Israel zu reden, was ihm aufgetragen war.", footnotes: ["℘ 2Kor 3,18"] },
      { number: 35, text: "Da sahen die Söhne Israel Moses Gesicht, dass die Haut von Moses Gesicht strahlte. Dann legte Mose die Decke wieder auf sein Gesicht, bis er hineinging, um mit ihm zu reden*.", footnotes: ["℘ 2Kor 3,13-16"] },
    ]},
    { number: 35, verses: [
      { number: 1, text: "*Und Mose versammelte die ganze Gemeinde der Söhne Israel und sagte zu ihnen: Dies sind die Worte*, die der HERR zu tun geboten hat*:", heading: "Sabbatgebot", footnotes: ["℘ Kap. 20,8-11", "o. Dinge", "℘ Kap. 34,32"] },
      { number: 2, text: "Sechs Tage soll man seine Arbeit verrichten, aber den siebten Tag sollt ihr heilig halten*, er sei euch ein ganz feierlicher Sabbat* für den HERRN. Jeder, der an ihm eine Arbeit verrichtet, muss getötet werden.", footnotes: ["w. aber am siebten Tag sei euch Heiliges", "w. ein Sabbat der Sabbatfeier"] },
      { number: 3, text: "Ihr dürft am Sabbattag in all euren Wohnsitzen kein Feuer anzünden." },
      { number: 4, text: "*Weiter sagte Mose zur ganzen Gemeinde der Söhne Israel: Dies ist es, was der HERR geboten hat:", heading: "Heiligtum: Freiwillige Gaben", footnotes: ["℘ V. 4-29: Kap. 25,1-9; V. 10-19: Kap. 31,6-11; 39,32-43; 40,3-30"] },
      { number: 5, text: "Nehmt aus eurem Besitz ein Hebopfer für den HERRN! Jeder, dessen Herz willig ist*, soll es herbeibringen, das Hebopfer für den HERRN: Gold, Silber und Bronze,", footnotes: ["℘ V. 29; 2Kor 9,7"] },
      { number: 6, text: "violetten und roten Purpur, Karmesinstoff, Byssus und Ziegenhaar," },
      { number: 7, text: "rot gefärbte Widderfelle, Häute von Delfinen* und Akazienholz;", footnotes: ["s. Anm. zu Kap. 25,5"] },
      { number: 8, text: "Öl für den Leuchter, Balsamöle für das Salböl und für das wohlriechende Räucherwerk;" },
      { number: 9, text: "und Onyxsteine und andere Edelsteine zum Besatz für das Efod und die Brusttasche*.", footnotes: ["o. den Brustschild"] },
      { number: 10, text: "Und alle, die ein weises Herz haben unter euch*, sollen kommen und alles machen, was der HERR geboten hat:", footnotes: ["℘ Kap. 28,3"] },
      { number: 11, text: "die Wohnung, ihr Zeltdach und ihre Decke, ihre Haken, Bretter, Riegel, Säulen und Fußgestelle;" },
      { number: 12, text: "die Lade und ihre Stangen, die Deckplatte* und den verhüllenden Vorhang;", footnotes: ["s. Anm. zu Kap. 25,17"] },
      { number: 13, text: "den Tisch mit seinen Stangen und all seinen Geräten und die Schaubrote*;", footnotes: ["s. Anm. zu Kap. 25,30"] },
      { number: 14, text: "ferner den Leuchter zur Beleuchtung mit seinen Geräten und Lampen, dazu das Öl für die Beleuchtung;" },
      { number: 15, text: "auch den Räucheraltar mit seinen Stangen, das Salböl und das wohlriechende Räucherwerk; und den Eingangsvorhang* für den Eingang der Wohnung;", footnotes: ["w. die Eingangsdecke"] },
      { number: 16, text: "den Brandopferaltar und das bronzene Gitter an ihm, seine Stangen und all seine Geräte; das Becken und sein Gestell;" },
      { number: 17, text: "die Behänge des Vorhofs, seine Säulen und Fußgestelle und den Vorhang für das Tor des Vorhofs;" },
      { number: 18, text: "die Pflöcke der Wohnung und die Pflöcke des Vorhofs mit ihren Seilen;" },
      { number: 19, text: "die gewirkten Kleider für den Dienst im Heiligtum, die heiligen Kleider für den Priester Aaron und die Kleider seiner Söhne zur Ausübung des Priesterdienstes." },
      { number: 20, text: "Darauf ging die ganze Gemeinde der Söhne Israel von Mose fort." },
      { number: 21, text: "Dann kamen sie, jeder, den sein Herz willig machte. Und jeder, dessen Geist ihn antrieb, brachte das Hebopfer des HERRN zur Arbeit am Zelt der Begegnung* und für den ganzen Dienst darin und für die heiligen Kleider*.", footnotes: ["℘ 1Chr 29,8", "℘ Esr 2,68.69"] },
      { number: 22, text: "So kamen die Männer mit den Frauen: jeder, dessen Herz willig war, brachte Spangen*, Ohrringe*, Siegelringe und Halsketten*, allerlei goldene Schmucksachen; ja, jeder, der dem HERRN ein Schwingopfer an Gold darbrachte*.", footnotes: ["o. Nasenringe; wie man sie für Tiere und Gefangene verwendete", "o. Nasenringe; als Frauenschmuck wie z. B. 1Mo 24,22", "Das sind Halsketten mit Kügelchen oder mit kleinen Platten.", "w. schwang"] },
      { number: 23, text: "Und jeder, bei dem sich violetter und roter Purpur vorfand, auch etwa Karmesinstoff oder Byssus, Ziegenhaar, rot gefärbte Widderfelle oder Häute von Delfinen*, brachte es herbei.", footnotes: ["s. Anm. zu Kap. 25,5"] },
      { number: 24, text: "Jeder, der ein Hebopfer an Silber oder Bronze entrichten wollte*, brachte das Hebopfer des HERRN herbei; und jeder, bei dem sich Akazienholz für irgendeine Arbeit am Bau* des Heiligtums vorfand, brachte es.", footnotes: ["w. hochhob; d. i. ein Opfer, das durch Emporheben Gott geweiht wurde", "w. Dienstwerk"] },
      { number: 25, text: "Ferner spann jede Frau, die ein weises Herz hatte, mit ihren Händen und brachte das Gesponnene: den violetten und roten Purpur, den Karmesinstoff und den Byssus." },
      { number: 26, text: "Alle Frauen, die ihr Herz mit Weisheit dazu trieb, spannen das Ziegenhaar*.", footnotes: ["℘ Spr 31,19"] },
      { number: 27, text: "Die Fürsten aber brachten Onyxsteine und andere Edelsteine zum Einsetzen für das Efod und für die Brusttasche*,", footnotes: ["o. den Brustschild"] },
      { number: 28, text: "ferner das Balsamöl und das Öl für den Leuchter, für das Salböl und für das wohlriechende Räucherwerk." },
      { number: 29, text: "Die Söhne Israel, alle Männer und Frauen, deren Herz sie antrieb, zu dem ganzen Werk beizutragen, das zu tun der HERR durch Mose geboten hatte, brachten dem HERRN eine freiwillige Gabe*.", footnotes: ["℘ V. 5; Kap. 36,3"] },
      { number: 30, text: "*Darauf sagte Mose zu den Söhnen Israel: Seht, der HERR hat Bezalel, den Sohn Uris, des Sohnes Hurs, vom Stamm Juda, mit Namen berufen", heading: "Heiligtum: Einführung der Werkmeister Bezalel und Oholiab", footnotes: ["℘ Kap. 31,1-6"] },
      { number: 31, text: "und ihn mit dem Geist Gottes erfüllt, mit Kunstfertigkeit, Verstand und Können* und für jedes Kunsthandwerk*,", footnotes: ["w. Erkenntnis", "w. in jedem Werk"] },
      { number: 32, text: "und zwar Pläne zu entwerfen*, um in Gold, Silber und Bronze zu arbeiten.", footnotes: ["w. Erfindungen zu erfinden"] },
      { number: 33, text: "Auch im Schneiden von Steinen zum Einsetzen und mit der Holzschnitzerei hat er ihn begabt, damit er in jedem künstlerischen Werk* arbeiten kann.", footnotes: ["w. in jeder Arbeit der Erfindung"] },
      { number: 34, text: "Dazu hat er ihm die Gabe zu unterweisen ins Herz gelegt, ihm und Oholiab, dem Sohn des Ahisamach, vom Stamm Dan." },
      { number: 35, text: "Er hat sie mit Weisheit des Herzens erfüllt, damit sie jeden Plan eines Kunsthandwerkers oder Kunststickers oder Buntwirkers ausführen können, mit violettem und rotem Purpur, Karmesinstoff und Byssus, und die des Webers; die Arbeit derer, die allerlei Arbeiten ausführen und Pläne ersinnen." },
    ]},
    { number: 36, verses: [
      { number: 1, text: "Und Bezalel und Oholiab und alle Männer mit einem weisen Herzen*, denen der HERR Weisheit und Verstand eingegeben hatte, damit sie die ganze Arbeit zum Bau* des Heiligtums ausführen könnten*, machten es ganz so, wie der HERR geboten hatte.", heading: "Heiligtum: Freigebigkeit des Volkes", footnotes: ["℘ Kap. 28,3; 1Chr 28,21", "w. Dienstwerk", "o. damit sie erkennen sollten, wie die ganze Arbeit . . . zu machen sei"] },
      { number: 2, text: "So rief Mose Bezalel und Oholiab und jeden Mann mit einem weisen Herzen* herbei, dem Gott Weisheit ins Herz gelegt hatte, jeden, den sein Herz willig machte, ans Werk zu gehen, um es auszuführen.", footnotes: ["℘ Kap. 28,3; 1Chr 28,21"] },
      { number: 3, text: "Und sie nahmen von Mose das ganze Hebopfer entgegen, das die Söhne Israel für die Arbeit am Bau* des Heiligtums gebracht hatten, um ihn auszuführen. Diese aber brachten ihm immer* noch freiwillige Gaben, Morgen für Morgen*.", footnotes: ["w. Dienstwerk", "o. fortwährend", "℘ Kap. 35,29"] },
      { number: 4, text: "Da kamen alle weisen Männer, die alle Arbeit des Heiligtums ausführten, Mann für Mann von ihrer Arbeit, die sie ausführten," },
      { number: 5, text: "und sagten zu Mose: Das Volk bringt viel, mehr als genug zur Verwendung* für die Arbeit, deren Ausführung der HERR geboten hat.", footnotes: ["w. Arbeit, o. Dienst"] },
      { number: 6, text: "Da gab Mose Befehl, und man ließ im Lager den Ruf ergehen: Niemand soll* mehr eine Arbeit für das Hebopfer des Heiligtums anfertigen, und so hörte das Volk auf, noch mehr zu bringen.", footnotes: ["w. Mann und Frau sollen nicht"] },
      { number: 7, text: "Und alle Spenden reichten ihnen aus, um die Arbeit zu tun*, so dass noch etwas übrig blieb*.", footnotes: ["w. Und die Arbeit war ein ihnen Ausreichendes, für alle Arbeit, sie zu tun", "℘ 2Chr 31,10"] },
      { number: 8, text: "*Und alle, die ein weises Herz hatten unter denen, die die Arbeit ausführten, machten die Wohnung aus zehn Zeltdecken. Aus gezwirntem Byssus*, violettem und rotem Purpur und Karmesinstoff machte er* sie, mit Cherubim, als Kunststickerarbeit.", heading: "Heiligtum: Bau des Heiligtums", footnotes: ["℘ Kap. 26,1-30", "s. Anm. zu Kap. 25,4", "d. i. Bezalel"] },
      { number: 9, text: "Die Länge einer Zeltdecke betrug achtundzwanzig Ellen und vier Ellen die Breite einer Zeltdecke: ein Maß für alle Zeltdecken." },
      { number: 10, text: "Er verband fünf Zeltdecken miteinander, und auch die übrigen fünf Zeltdecken verband er miteinander." },
      { number: 11, text: "Am Saum der einen Zeltdecke am Ende der einen Verbindungsstelle brachte er Schleifen aus violettem Purpur an. Ebenso machte er es am Saum der äußersten Zeltdecke an der andern Verbindungsstelle:" },
      { number: 12, text: "fünfzig Schleifen brachte er an der einen Zeltdecke an, und fünfzig Schleifen brachte er am Ende der Zeltdecke an, die sich an der andern Verbindungsstelle befand, so dass die Schleifen einander gegenüberstanden." },
      { number: 13, text: "Dann stellte er fünfzig goldene Haken her und verband die Zeltdecken durch die Haken miteinander, so dass die Wohnung ein Ganzes wurde." },
      { number: 14, text: "Und er machte Zeltdecken aus Ziegenhaar als ein Zeltdach über der Wohnung; elf solcher Zeltdecken machte er." },
      { number: 15, text: "Die Länge einer Zeltdecke betrug dreißig Ellen und vier Ellen die Breite einer Zeltdecke: ein Maß für die elf Zeltdecken." },
      { number: 16, text: "Dann verband er fünf Zeltdecken für sich und ebenso die übrigen sechs Zeltdecken für sich." },
      { number: 17, text: "Und er brachte fünfzig Schleifen am Saum der äußersten Zeltdecke an, an der einen Verbindungsstelle, und ebenso brachte er fünfzig Schleifen am Saum der äußersten Zeltdecke der anderen Verbindungsstelle an." },
      { number: 18, text: "Dann stellte er fünfzig bronzene Haken her, um das Zeltdach zusammenzufügen, damit es ein Ganzes wurde." },
      { number: 19, text: "Er fertigte für das Zelt eine Decke aus rot gefärbten Widderfellen an und oben darüber eine Decke aus Delfinhäuten*.", footnotes: ["s. Anm. zu Kap. 25,5"] },
      { number: 20, text: "Die Bretter für die Wohnung stellte er aus Akazienholz her, aufrecht stehend:" },
      { number: 21, text: "zehn Ellen war die Länge eines Brettes und anderthalb Ellen die Breite eines Brettes." },
      { number: 22, text: "Ein Brett hatte zwei Zapfen, einer dem andern gegenüber eingefügt; so machte er es an allen Brettern der Wohnung." },
      { number: 23, text: "Und zwar machte er an Brettern für die Wohnung zwanzig Bretter für die Südseite, nach Süden zu," },
      { number: 24, text: "und brachte unter den zwanzig Brettern vierzig silberne Fußgestelle an: zwei Fußgestelle unter einem Brett für seine zwei Zapfen und wieder zwei Fußgestelle unter einem Brett für seine zwei Zapfen." },
      { number: 25, text: "Auch für die andere Längsseite der Wohnung, für die Nordseite, machte er zwanzig Bretter" },
      { number: 26, text: "und ihre vierzig silbernen Fußgestelle: zwei Fußgestelle unter einem Brett und wieder zwei Fußgestelle unter einem Brett." },
      { number: 27, text: "Für die Rückseite der Wohnung aber, nach Westen zu, machte er sechs Bretter." },
      { number: 28, text: "Und zwei Bretter stellte er für die Ecken der Wohnung an der Rückseite her;" },
      { number: 29, text: "die waren von unten herauf doppelt und an* ihrem Oberteil ganz beieinander bis zu einem Ring. So machte er es mit ihnen beiden für die beiden Winkel.", footnotes: ["o. bis zu"] },
      { number: 30, text: "Es waren acht Bretter und ihre silbernen Fußgestelle: sechzehn Fußgestelle, je zwei Fußgestelle unter einem Brett." },
      { number: 31, text: "Und er fertigte Riegel aus Akazienholz an: fünf für die Bretter der einen Längsseite der Wohnung" },
      { number: 32, text: "und fünf Riegel für die Bretter der anderen Längsseite der Wohnung und fünf Riegel für die Bretter der Wohnung an der Rückseite nach Westen zu." },
      { number: 33, text: "Und er machte den mittleren Riegel in der Mitte der Bretter so, dass er von einem Ende zum andern durchlief." },
      { number: 34, text: "Die Bretter aber überzog er mit Gold. Und ihre Ringe, die Ösen* für die Riegel, machte er aus Gold, auch die Riegel überzog er mit Gold.", footnotes: ["w. Häuser"] },
      { number: 35, text: "*Und er fertigte den Vorhang an aus violettem und rotem Purpur, Karmesinstoff und gezwirntem Byssus. In Kunststickerarbeit machte er ihn, mit Cherubim.", footnotes: ["℘ V. 35-38: Kap. 26,31-37"] },
      { number: 36, text: "Dann machte er für ihn vier Säulen aus Akazienholz und überzog sie mit Gold — auch ihre Nägel waren aus Gold —, und er goss für sie vier silberne Fußgestelle." },
      { number: 37, text: "Und er machte für den Eingang des Zeltes einen Vorhang* aus violettem und rotem Purpur und Karmesinstoff und gezwirntem Byssus, in Buntwirkerarbeit,", footnotes: ["w. eine Decke"] },
      { number: 38, text: "und seine fünf Säulen und ihre Nägel. Dann überzog er ihre Köpfe und ihre Bindestäbe* mit Gold; ihre fünf Fußgestelle aber waren aus Bronze.", footnotes: ["o. ihre Ringe. — Mit ihnen waren die Säulen verziert und verbunden."] },
    ]},
    { number: 37, verses: [
      { number: 1, text: "*Und Bezalel machte die Lade aus Akazienholz: zweieinhalb Ellen war ihre Länge, anderthalb Ellen ihre Breite und anderthalb Ellen ihre Höhe.", heading: "Heiligtum: Geräte des Heiligtums", footnotes: ["℘ V. 1-9: Kap. 25,10-22"] },
      { number: 2, text: "Dann überzog er sie von innen und außen mit reinem Gold und brachte an ihr ringsum eine goldene Kante an." },
      { number: 3, text: "Und er goss für sie* vier goldene Ringe und befestigte sie an ihren vier Füßen, zwei Ringe an ihrer einen Längsseite und zwei Ringe an ihrer andern Längsseite.", footnotes: ["d. i. für die Lade"] },
      { number: 4, text: "Er fertigte Stangen aus Akazienholz an und überzog sie mit Gold." },
      { number: 5, text: "Diese Stangen steckte er in die Ringe an den Seiten der Lade, damit man die Lade tragen konnte." },
      { number: 6, text: "Dann stellte er eine Deckplatte* aus reinem Gold her: zweieinhalb Ellen war ihre Länge und anderthalb Ellen ihre Breite.", footnotes: ["o. Sühneplatte. — Das hebr. Wort ist von einem Zeitwort abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, versöhnen« bedeutet."] },
      { number: 7, text: "Und er machte zwei goldene Cherubim; in getriebener Arbeit machte er sie, an beiden Enden der Deckplatte*,", footnotes: ["o. Sühneplatte. — Das hebr. Wort ist von einem Zeitwort abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, versöhnen« bedeutet."] },
      { number: 8, text: "den einen Cherub am Ende hier und einen Cherub am Ende drüben; aus einem Stück mit der Deckplatte* machte er die Cherubim an ihren beiden Enden.", footnotes: ["o. Sühneplatte. — Das hebr. Wort ist von einem Zeitwort abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, versöhnen« bedeutet."] },
      { number: 9, text: "Und die Cherubim breiteten die Flügel nach oben aus, die Deckplatte* mit ihren Flügeln überdeckend, und ihre Gesichter waren einander zugewandt*, gegen die Deckplatte waren die Gesichter der Cherubim gerichtet.", footnotes: ["o. Sühneplatte. — Das hebr. Wort ist von einem Zeitwort abgeleitet, das ursprünglich »verdecken, verhüllen, bestreichen«, gewöhnlich aber »sühnen, versöhnen« bedeutet.", "w. waren jedes zu seinem Bruder gewandt"] },
      { number: 10, text: "*Und er machte den Tisch aus Akazienholz: zwei Ellen war seine Länge, eine Elle seine Breite und anderthalb Ellen seine Höhe.", footnotes: ["℘ V. 10-16: Kap. 25,23-30"] },
      { number: 11, text: "Den überzog er mit reinem Gold, und er brachte an ihm ringsum eine goldene Kante an;" },
      { number: 12, text: "er machte an ihm ringsum eine Leiste von einer Handbreit und brachte an seiner Leiste ringsum eine goldene Kante an." },
      { number: 13, text: "Er machte für ihn auch vier goldene Ringe und befestigte die Ringe an den vier Seiten seiner vier Beine*.", footnotes: ["o. über den vier Ecken, die an seinen vier Füßen sind"] },
      { number: 14, text: "Dicht an der Leiste waren die Ringe als Ösen* für die Stangen, damit man den Tisch tragen konnte.", footnotes: ["w. Häuser"] },
      { number: 15, text: "Die Stangen aber machte er aus Akazienholz und überzog sie mit Gold, damit man den Tisch tragen konnte*.", footnotes: ["w. um . . . zu tragen"] },
      { number: 16, text: "Dann fertigte er die Geräte an, die auf dem Tisch stehen sollten: seine Schüsseln, Schalen und Opferschalen und die Kannen, mit denen man Trankopfer ausgießt — alles aus reinem Gold." },
      { number: 17, text: "*Und er machte den Leuchter aus reinem Gold. In getriebener Arbeit machte er den Leuchter, sein Fuß* und seine Schaftröhre; seine Kelche, Knäufe und Blüten waren aus einem Stück mit ihm.", footnotes: ["℘ V. 17-24: Kap. 25,31-40", "w. Schenkel"] },
      { number: 18, text: "Sechs Arme gingen von seinen beiden Seiten aus: drei Arme des Leuchters aus seiner einen Seite und drei Arme des Leuchters aus seiner andern Seite." },
      { number: 19, text: "Drei Kelche in der Form von Mandelblüten waren an dem einen Arm, aus Knauf und Blüte bestehend, und drei Kelche in der Form von Mandelblüten an dem nächsten Arm, aus Knauf und Blüte bestehend; so war es an den sechs Armen, die vom Leuchter ausgingen." },
      { number: 20, text: "Am Leuchter* aber waren vier Kelche in der Form von Mandelblüten, aus seinen Knäufen und Blüten bestehend,", footnotes: ["d. h. am Schaft des Leuchters"] },
      { number: 21, text: "und zwar ein Knauf unter den ersten zwei von ihm ausgehenden Armen, ein Knauf unter den nächsten zwei von ihm ausgehenden Armen und wieder ein Knauf unter den dritten zwei von ihm ausgehenden Armen; so war es an den sechs Armen, die von ihm ausgingen." },
      { number: 22, text: "Ihre Knäufe und Arme waren aus einem Stück mit ihm. Der ganze Leuchter war eine getriebene Arbeit aus reinem Gold." },
      { number: 23, text: "Auch seine sieben Lampen, seine Dochtscheren und Feuerbecken* stellte er aus reinem Gold her.", footnotes: ["Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen."] },
      { number: 24, text: "Aus einem Talent reinen Goldes machte er ihn und all seine Geräte." },
      { number: 25, text: "*Weiter machte er den Räucheraltar aus Akazienholz: eine Elle seine Länge und eine Elle seine Breite, viereckig*, und zwei Ellen seine Höhe; seine Hörner waren aus einem Stück mit ihm.", footnotes: ["℘ V. 25-29: Kap. 30,1-10.22-38", "o. quadratisch"] },
      { number: 26, text: "Dann überzog er ihn mit reinem Gold, seine Platte und seine Wände ringsum sowie seine Hörner, und er brachte an ihm ringsum eine goldene Kante an." },
      { number: 27, text: "Und er brachte an ihm unter seiner Kante zwei goldene Ringe an, an seinen beiden Seiten*, an seinen beiden Wänden* als Ösen* für die Stangen, damit man ihn daran tragen konnte*.", footnotes: ["w. Längsseiten. — Andere üs.: Ecken", "w. Seiten", "w. Häuser", "w. um ihn daran zu tragen"] },
      { number: 28, text: "Auch die Stangen machte er aus Akazienholz und überzog sie mit Gold." },
      { number: 29, text: "Außerdem machte er das heilige Salböl und das reine, wohlriechende Räucherwerk, beides ein Werk des Salbenmischers." },
    ]},
    { number: 38, verses: [
      { number: 1, text: "*Und er machte den Brandopferaltar* aus Akazienholz: fünf Ellen seine Länge und fünf Ellen seine Breite, viereckig*, und drei Ellen seine Höhe.", heading: "Heiligtum: Vorhof und Geräte", footnotes: ["℘ Kap. 27,1-8; 30,17-21", "℘ 2Chr 1,5", "o. quadratisch"] },
      { number: 2, text: "Und er machte seine Hörner an seinen vier Ecken — seine Hörner waren aus einem Stück mit ihm —, und er überzog ihn mit Bronze." },
      { number: 3, text: "Und er fertigte alle Geräte des Altars an: die Töpfe, Schaufeln und Sprengschalen, die Fleischgabeln und Feuerbecken*; all seine Geräte machte er aus Bronze*.", footnotes: ["Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen.", "℘ 2Chr 4,2.16"] },
      { number: 4, text: "Und er machte für den Altar ein bronzenes Gitter wie ein Netz* unter seiner Einfassung, von unten her, bis zu seiner halben Höhe.", footnotes: ["w. ein Gitter, Netzarbeit aus Bronze"] },
      { number: 5, text: "Und er goss vier Ringe und befestigte sie an den vier Ecken des bronzenen Gitters als Ösen* für die Stangen.", footnotes: ["w. Häuser"] },
      { number: 6, text: "Dann machte er die Stangen aus Akazienholz, überzog sie mit Bronze" },
      { number: 7, text: "und steckte die Stangen in die Ringe an die Seiten des Altars, damit man ihn daran tragen konnte*; aus Brettern fertigte er ihn an, innen hohl.", footnotes: ["w. um ihn daran zu tragen"] },
      { number: 8, text: "Außerdem machte er das Becken aus Bronze und ebenso sein Gestell aus Bronze, aus den Spiegeln der diensttuenden Frauen*, die am Eingang des Zeltes der Begegnung Dienst taten*.", footnotes: ["℘ Jes 3,23", "o. der sich zusammenfindenden Frauen, die sich . . . zusammenfanden\n℘ 1Sam 2,22"] },
      { number: 9, text: "*Und er machte den Vorhof: an der Südseite, nach Süden zu, die Behänge des Vorhofs aus gezwirntem Byssus, hundert Ellen lang.", footnotes: ["℘ V. 9-20: Kap. 27,9-19"] },
      { number: 10, text: "Ihre zwanzig Säulen und ihre zwanzig Fußgestelle machte er aus Bronze, die Nägel der Säulen und ihre Bindestäbe* aus Silber.", footnotes: ["o. ihre Ringe. — Mit ihnen waren die Säulen verziert und verbunden."] },
      { number: 11, text: "Auch an der Nordseite brachte er hundert Ellen Behänge an; ihre zwanzig Säulen und ihre zwanzig Fußgestelle aus Bronze, die Nägel der Säulen und ihre Bindestäbe* aus Silber.", footnotes: ["o. ihre Ringe. — Mit ihnen waren die Säulen verziert und verbunden."] },
      { number: 12, text: "An der Westseite aber machte er fünfzig Ellen Behänge; ihre zehn Säulen und ihre zehn Fußgestelle, die Nägel der Säulen und ihre Bindestäbe* aus Silber.", footnotes: ["o. ihre Ringe. — Mit ihnen waren die Säulen verziert und verbunden."] },
      { number: 13, text: "Und an der östlichen, dem Sonnenaufgang zugekehrten Seite fünfzig Ellen:" },
      { number: 14, text: "fünfzehn Ellen Behänge auf der einen Seite*, ihre drei Säulen und ihre drei Fußgestelle,", footnotes: ["w. Schulter. — Gemeint sind die beiden Seitenstücke neben dem Eingang."] },
      { number: 15, text: "und auf der andern Seite — diesseits und jenseits vom Tor des Vorhofs — fünfzehn Ellen Behänge, ihre drei Säulen und ihre drei Fußgestelle." },
      { number: 16, text: "Alle Behänge des Vorhofs ringsum waren aus gezwirntem Byssus," },
      { number: 17, text: "die Fußgestelle der Säulen aus Bronze, die Nägel der Säulen und ihre Bindestäbe* aus Silber und der Überzug ihrer Köpfe aus Silber. Und die Säulen des Vorhofs waren alle mit silbernen Bindestäben versehen.", footnotes: ["o. ihre Ringe. — Mit ihnen waren die Säulen verziert und verbunden."] },
      { number: 18, text: "Den Vorhang für das Tor des Vorhofs aber machte er in Buntwirkerarbeit, aus violettem und rotem Purpur, Karmesinstoff und gezwirntem Byssus, und zwar zwanzig Ellen lang und fünf Ellen hoch, entsprechend der Breite einer Stoffbahn gerade wie die Behänge des Vorhofs." },
      { number: 19, text: "Ihre vier Säulen und ihre vier Fußgestelle waren aus Bronze, ihre Nägel aus Silber und der Überzug ihrer Köpfe und ihre Bindestäbe* aus Silber.", footnotes: ["o. ihre Ringe. — Mit ihnen waren die Säulen verziert und verbunden."] },
      { number: 20, text: "Aber alle Pflöcke für die Wohnung und den Vorhof ringsum waren aus Bronze." },
      { number: 21, text: "Dies ist die Kostenberechnung* für die Wohnung, die Wohnung des Zeugnisses*, die auf Moses Befehl als Dienst der Leviten unter der Leitung* Itamars, des Sohnes des Priesters Aaron*, vorgenommen wurde* —", heading: "Heiligtum: Berechnung des Goldes, Silbers und der Bronze des Heiligtums", footnotes: ["w. Musterung", "℘ Offb 15,5", "w. Hand", "℘ 4Mo 4,28.33", "w. gemustert wurde"] },
      { number: 22, text: "Bezalel, der Sohn Uris, des Sohnes Hurs, vom Stamm Juda, machte alles, was der HERR dem Mose geboten hatte," },
      { number: 23, text: "und mit ihm Oholiab, der Sohn Ahisamachs, vom Stamm Dan, ein Kunsthandwerker und Kunststicker und Buntwirker in violettem und rotem Purpur, Karmesinstoff und Byssus* —:", footnotes: ["℘ Kap. 31,2-6; 36,1"] },
      { number: 24, text: "Alles Gold, das zur Arbeit am ganzen Bau* des Heiligtums verwendet wurde, das Gold des Schwingopfers, betrug 29 Talente und 730 Schekel, nach dem Schekel des Heiligtums*.", footnotes: ["w. zur Arbeit an der ganzen Arbeit", "d. h. nach dem am Heiligtum gültigen Schekelgewicht\n℘ 3Mo 27,3.25"] },
      { number: 25, text: "Und das Silber von den Gemusterten der Gemeinde betrug 100 Talente und 1 775 Schekel, nach dem Schekel des Heiligtums*:", footnotes: ["℘ Kap. 30,12-16"] },
      { number: 26, text: "ein Beka je Kopf, ein halber Schekel, nach dem Schekel des Heiligtums, von jedem, der zu den Gemusterten hinüberging, von zwanzig Jahren an und darüber, von 603 550 Mann*.", footnotes: ["℘ Kap. 12,37"] },
      { number: 27, text: "Die 100 Talente Silber waren zum Gießen der Fußgestelle des Heiligtums und der Fußgestelle des Vorhangs*: 100 Fußgestelle auf 100 Talente, ein Talent auf ein Fußgestell.", footnotes: ["w. des Absperrenden\n℘ Kap. 26,19.32"] },
      { number: 28, text: "Aus den 1 775 Schekeln aber machte er Nägel für die Säulen, überzog ihre Köpfe und verband sie mit Stäben**.", footnotes: ["o. Ringen", "℘ Kap. 27,17"] },
      { number: 29, text: "Die Bronze des Schwingopfers betrug 70 Talente und 2 400 Schekel." },
      { number: 30, text: "Und er machte daraus die Fußgestelle vom Eingang des Zeltes der Begegnung*, den bronzenen Altar und sein bronzenes Gitter und alle Geräte des Altars*,", footnotes: ["℘ Kap. 26,37", "℘ Kap. 27,2-6"] },
      { number: 31, text: "die Fußgestelle des Vorhofs ringsum und die Fußgestelle am Tor des Vorhofs sowie alle Pflöcke der Wohnung und alle Pflöcke des Vorhofs ringsum.*", footnotes: ["℘ Kap. 27,10-19"] },
    ]},
    { number: 39, verses: [
      { number: 1, text: "*Aus dem violetten und dem roten Purpur aber und aus dem Karmesinstoff machten sie die gewirkten Kleider für den Dienst im Heiligtum, und sie machten die heiligen Kleider für Aaron, wie der HERR dem Mose geboten hatte.", heading: "Heiligtum: Kleidung der Priester", footnotes: ["℘ V. 1-7: Kap. 28,5-14"] },
      { number: 2, text: "Und zwar machte man das Efod aus Gold, violettem und rotem Purpur, Karmesinstoff und gezwirntem Byssus:" },
      { number: 3, text: "Sie hämmerten die Goldbleche zurecht, und man zerschnitt sie zu Fäden, um sie in den violetten und roten Purpur, in den Karmesinstoff und den Byssus hineinzuarbeiten, in Kunststickerarbeit." },
      { number: 4, text: "Sie machten zusammenfügbare* Schulterstücke daran: An seinen beiden Rändern wurde es mit ihnen zusammengefügt.", footnotes: ["o. zwei mit ihm verbundene; o. zwei zusammengefügte"] },
      { number: 5, text: "Und der Gurt, mit dem es angelegt wurde, der sich oben darüber befand, war von gleicher Arbeit aus einem Stück mit ihm: aus Gold, violettem und rotem Purpur, Karmesinstoff und gezwirntem Byssus — wie der HERR dem Mose geboten hatte." },
      { number: 6, text: "Und sie machten die Onyxsteine, umgeben mit goldenen Einfassungen, graviert in Siegelgravur, entsprechend den Namen der Söhne Israels." },
      { number: 7, text: "Dann setzte man sie oben auf die Schulterstücke des Efods, als Steine der Erinnerung für die Söhne Israel — wie der HERR dem Mose geboten hatte." },
      { number: 8, text: "*Man machte die Brusttasche* in Kunststickerarbeit wie die Arbeit des Efods: aus Gold, violettem und rotem Purpur, Karmesinstoff und gezwirntem Byssus.", footnotes: ["℘ V. 8-21: Kap. 28,15-30", "o. Brustschild"] },
      { number: 9, text: "Sie war viereckig*; doppelt gelegt machten sie die Brusttasche*, eine Spanne ihre Länge und eine Spanne ihre Breite, doppelt gelegt.", footnotes: ["o. quadratisch", "o. Brustschild"] },
      { number: 10, text: "Dann besetzten sie sie mit vier Reihen von Steinen: eine Reihe mit Karneol, Topas und Smaragd, die erste Reihe;" },
      { number: 11, text: "die zweite Reihe: Rubin, Saphir und Jaspis;" },
      { number: 12, text: "und die dritte Reihe: Hyazinth, Achat und Amethyst;" },
      { number: 13, text: "und die vierte Reihe: Türkis, Onyx und Nephrit; sie waren mit goldenen Einfassungen umgeben in ihren Einsetzungen." },
      { number: 14, text: "Die Steine waren — entsprechend den Namen der Söhne Israels — zwölf an der Zahl, entsprechend ihren Namen; in Siegelgravur waren sie hergestellt, jeder nach seinem Namen für die zwölf Stämme." },
      { number: 15, text: "Und sie machten an die Brusttasche* gedrehte Ketten* in Seilerarbeit aus reinem Gold;", footnotes: ["o. Brustschild", "w. Ketten der Drehung o. als Drehung"] },
      { number: 16, text: "und zwar fertigten sie zwei goldene Einfassungen* und zwei goldene Ringe an und befestigten die beiden Ringe an den beiden oberen Enden der Brusttasche*;", footnotes: ["wahrscheinlich die V. 6 erwähnten", "o. Brustschild"] },
      { number: 17, text: "und die zwei goldenen Schnüre befestigten sie an den beiden Ringen an den Enden der Brusttasche*.", footnotes: ["o. Brustschild"] },
      { number: 18, text: "Die beiden anderen Enden der zwei Schnüre aber befestigten sie an den beiden Einfassungen und befestigten sie so an den Schulterstücken des Efods, an seiner Vorderseite." },
      { number: 19, text: "Und sie stellten zwei andere goldene Ringe her und befestigten sie an den beiden unteren Enden der Brusttasche*, an ihrem Rand, der dem Efod zugekehrt war, auf der Innenseite.", footnotes: ["o. Brustschild"] },
      { number: 20, text: "Dann machten sie noch zwei goldene Ringe und befestigten sie unten an den beiden Schulterstücken des Efods, an seiner Vorderseite, dicht an seiner Zusammenfügung mit den Schulterstücken oberhalb des Gurtes des Efods." },
      { number: 21, text: "Und sie banden die Brusttasche* von ihren Ringen mit einer Schnur aus violettem Purpur an den Ringen des Efods fest, damit es über dem Gurt des Efods saß und sich die Brusttasche* nicht von der Stelle über dem Efod verschob — wie der HERR dem Mose geboten hatte.", footnotes: ["o. der Brustschild", "o. der Brustschild"] },
      { number: 22, text: "*Und man machte das Oberkleid des Efods in Weberarbeit, ganz aus violettem Purpur.", footnotes: ["℘ V. 22-26: Kap. 28,31-35"] },
      { number: 23, text: "Und die Öffnung des Oberkleides war in seiner Mitte wie die Öffnung eines Lederpanzers. Ringsum an seiner Öffnung hatte es einen Rand, damit es nicht einriss." },
      { number: 24, text: "Am unteren Saum des Oberkleides aber brachten sie Granatäpfel aus violettem und rotem Purpur und Karmesinstoff an, gezwirnt." },
      { number: 25, text: "Dann machten sie Glöckchen aus reinem Gold und setzten die Glöckchen zwischen die Granatäpfel ringsum an den Saum des Oberkleides zwischen die Granatäpfel:" },
      { number: 26, text: "erst ein Glöckchen, dann einen Granatapfel und wieder ein Glöckchen und einen Granatapfel, ringsum an den Saum des Oberkleides, um darin den Dienst zu verrichten — wie der HERR dem Mose geboten hatte." },
      { number: 27, text: "*Weiter machten sie die Leibröcke für Aaron und für seine Söhne aus Byssus, in Weberarbeit,", footnotes: ["℘ V. 27-31: Kap. 28,36-43"] },
      { number: 28, text: "und den Kopfbund aus Byssus und die turbanartigen Kopfbedeckungen* aus Byssus und die leinenen Beinkleider aus gezwirntem Byssus", footnotes: ["w. den Kopfschmuck der hohen Turbane"] },
      { number: 29, text: "und den Gürtel* aus gezwirntem Byssus, aus violettem und rotem Purpur und Karmesinstoff, in Buntwirkerarbeit — wie der HERR dem Mose geboten hatte.", footnotes: ["o. die Schärpe"] },
      { number: 30, text: "Schließlich machten sie das blumenförmige Stirnblatt, das heilige Diadem, aus reinem Gold und schrieben darauf mit Siegelgravurschrift: »Heiligkeit dem HERRN!«" },
      { number: 31, text: "Und sie befestigten daran eine Schnur aus violettem Purpur, um sie von oben über den Kopfbund zu legen — wie der HERR dem Mose geboten hatte." },
      { number: 32, text: "*So wurde die ganze Arbeit der Wohnung des Zeltes der Begegnung vollendet*: Die Söhne Israel machten es ganz so, wie der HERR dem Mose geboten hatte, so machten sie es*.", heading: "Heiligtum: Fertigstellung des Heiligtums", footnotes: ["℘ Kap. 31,7-11; 35,10-19; 40,3-30; V. 33-36: Kap. 25,10-30", "℘ 1Kö 7,40; Hebr 9,2", "℘ Kap. 12,28.35.50; 25,9.40; 1Kö 6,38"] },
      { number: 33, text: "Und sie brachten die Wohnung zu Mose: das Zelt und all seine Geräte, seine Haken, Bretter, Riegel, Säulen und Fußgestelle;" },
      { number: 34, text: "dazu die Decke aus rot gefärbten Widderfellen, die Decke aus Delfinhäuten* und den verhüllenden Vorhang;", footnotes: ["s. Anm. zu Kap. 25,5"] },
      { number: 35, text: "die Lade des Zeugnisses und ihre Stangen und die Deckplatte*;", footnotes: ["s. Anm. zu Kap. 37,6"] },
      { number: 36, text: "den Tisch mit all seinen Geräten und die Schaubrote*;", footnotes: ["s. Anm. zu Kap. 25,30"] },
      { number: 37, text: "den Leuchter* aus reinem Gold mit seinen Lampen, die Lampenreihe*, und all seine Geräte* sowie das Öl für die Beleuchtung*;", footnotes: ["℘ 4Mo 8,2-4", "w. den Lampen der Reihe", "℘ Kap. 25,31-40", "℘ Kap. 27,20"] },
      { number: 38, text: "und den goldenen Altar*, das Salböl und das wohlriechende Räucherwerk*; ferner den Vorhang für den Eingang des Zeltes;", footnotes: ["℘ Kap. 30,1-5", "℘ Kap. 30,22-38"] },
      { number: 39, text: "den bronzenen Altar, sein bronzenes Gitter, seine Stangen und all seine Geräte*; das Becken und sein Gestell;", footnotes: ["℘ Kap. 27,1-8"] },
      { number: 40, text: "die Behänge des Vorhofs, seine Säulen und Fußgestelle; dazu den Vorhang für das Tor des Vorhofs, seine Seile und seine Pflöcke; und alle Geräte für den Dienst* an der Wohnung, dem Zelt der Begegnung;", footnotes: ["℘ Kap. 27,9-19"] },
      { number: 41, text: "die gewirkten Kleider für den Dienst im Heiligtum, die heiligen Kleider für den Priester Aaron und die Kleider seiner Söhne* zur Ausübung des Priesterdienstes.", footnotes: ["℘ Kap. 28"] },
      { number: 42, text: "Genau wie der HERR dem Mose geboten hatte, so hatten die Söhne Israel die ganze Arbeit gemacht*.", footnotes: ["℘ Kap. 12,28.35.50; 25,9.40; 1Kö 6,38"] },
      { number: 43, text: "Und Mose sah sich das ganze Werk an — und siehe, sie hatten es ausgeführt; wie der HERR geboten hatte, so hatten sie es ausgeführt*. Da segnete Mose sie*.", footnotes: ["℘ Kap. 12,28.35.50; 25,9.40; 1Kö 6,38", "℘ 3Mo 9,22.23; Jos 22,6; 2Sam 6,18; 1Kö 8,55; 2Chr 30,27"] },
    ]},
    { number: 40, verses: [
      { number: 1, text: "*Und der HERR redete zu Mose und sprach:", heading: "Heiligtum: Aufrichtung und Einweihung des Heiligtums", footnotes: ["℘ V. 1-33: Kap. 31,7-11; 35,10-19; 39,32-43; V. 1-16: V. 17-33"] },
      { number: 2, text: "Am Tag des ersten Monats*, am Ersten des Monats*, sollst du die Wohnung des Zeltes der Begegnung aufrichten.", footnotes: ["o. Neumonds", "℘ 2Chr 29,3; Hes 45,18"] },
      { number: 3, text: "Und du sollst die Lade des Zeugnisses hineinstellen und die Lade mit dem Vorhang verdecken*.", footnotes: ["℘ 4Mo 4,5"] },
      { number: 4, text: "Dann bringe den Tisch hinein und richte zu, was auf ihm zuzurichten ist*! Auch den Leuchter bringe hinein und setze seine Lampen auf*!", footnotes: ["℘ 3Mo 24,5-8", "℘ Kap. 26,35; 27,20.21"] },
      { number: 5, text: "Ferner stelle den goldenen Altar für das Räucherwerk vor die Lade des Zeugnisses*, und hänge den Vorhang des Eingangs zur Wohnung auf*!", footnotes: ["℘ Kap. 30,6", "℘ Kap. 26,36"] },
      { number: 6, text: "Den Brandopferaltar aber stelle vor den Eingang der Wohnung des Zeltes der Begegnung*!", footnotes: ["℘ Kap. 27,1"] },
      { number: 7, text: "Dann stelle das Becken zwischen das Zelt der Begegnung und den Altar und tu Wasser hinein*!", footnotes: ["℘ Kap. 30,18.19"] },
      { number: 8, text: "Richte ringsum den Vorhof auf! Auch den Vorhang des Tors zum Vorhof hänge auf*!", footnotes: ["℘ Kap. 27,9.16"] },
      { number: 9, text: "Darauf nimm das Salböl und salbe die Wohnung und alles, was darin ist, und heilige dadurch sie und all ihre Geräte, damit sie heilig wird!" },
      { number: 10, text: "Salbe auch den Brandopferaltar und all seine Geräte und heilige dadurch den Altar, damit der Altar hochheilig wird*!", footnotes: ["℘ Kap. 30,29"] },
      { number: 11, text: "Salbe das Becken und sein Gestell und heilige es dadurch*!", footnotes: ["℘ Kap. 30,28; 4Mo 7,1"] },
      { number: 12, text: "Dann lass Aaron und seine Söhne an den Eingang des Zeltes der Begegnung herantreten und wasche sie mit Wasser*!", footnotes: ["℘ Kap. 29,4"] },
      { number: 13, text: "Und bekleide Aaron mit den heiligen Kleidern, salbe ihn und heilige ihn dadurch, damit er mir den Priesterdienst ausübt*!", footnotes: ["℘ Kap. 29,7"] },
      { number: 14, text: "Auch seine Söhne sollst du herantreten lassen und sie mit den Leibröcken bekleiden*.", footnotes: ["℘ Kap. 29,8"] },
      { number: 15, text: "Und du sollst sie salben, wie du ihren Vater gesalbt hast, damit sie mir den Priesterdienst ausüben*. Das soll geschehen, damit ihnen ihre Salbung zu einem ewigen Priesteramt sei, in all ihren Generationen*.", footnotes: ["℘ Kap. 28,41", "℘ Kap. 29,9; 4Mo 25,13"] },
      { number: 16, text: "Und Mose handelte ganz, wie ihm der HERR geboten hatte; so handelte er*.", footnotes: ["℘ 1Mo 6,22; 3Mo 8,13.36; 4Mo 1,19"] },
      { number: 17, text: "*Und es geschah im ersten Monat im zweiten Jahr*, am Ersten des Monats*, da wurde die Wohnung aufgerichtet:", footnotes: ["℘ V. 17-33: V. 1-16", "wohl nach dem Auszug aus Ägypten; vgl. Kap. 12,2", "℘ Kap. 12,2"] },
      { number: 18, text: "Mose richtete die Wohnung auf, indem er ihre Fußgestelle setzte, ihre Bretter hinstellte, ihre Riegel einsetzte und ihre Säulen aufrichtete." },
      { number: 19, text: "Auch spannte er das Zeltdach über der Wohnung und legte die Decke des Zeltes oben darüber — wie der HERR dem Mose geboten hatte." },
      { number: 20, text: "Dann nahm er das Zeugnis und legte es in die Lade*, brachte die Stangen an der Lade an und legte die Deckplatte* oben auf die Lade.", footnotes: ["℘ 5Mo 10,5; Hebr 9,4", "s. Anm. zu Kap. 37,6"] },
      { number: 21, text: "Und er brachte die Lade in die Wohnung, hängte den verhüllenden Vorhang auf und verdeckte so die Lade des Zeugnisses — wie der HERR dem Mose geboten hatte." },
      { number: 22, text: "Weiter setzte er den Tisch in das Zelt der Begegnung an die Nordseite der Wohnung, außerhalb des inneren Vorhangs," },
      { number: 23, text: "und schichtete darauf die Brote übereinander* vor dem HERRN* — wie der HERR dem Mose geboten hatte.", footnotes: ["w. schichtete die Aufschichtung Brote, o. ordnete die Ordnung Brote", "℘ Kap. 25,30"] },
      { number: 24, text: "Dann stellte er den Leuchter in das Zelt der Begegnung dem Tisch gegenüber, an die Südseite der Wohnung*,", footnotes: ["℘ Hebr 9,2"] },
      { number: 25, text: "und setzte vor dem HERRN die Lampen auf* — wie der HERR dem Mose geboten hatte.", footnotes: ["℘ 4Mo 8,2.3"] },
      { number: 26, text: "Er stellte den goldenen Altar in das Zelt der Begegnung, vor den inneren Vorhang," },
      { number: 27, text: "und ließ darauf wohlriechendes Räucherwerk als Rauch aufsteigen* — wie der HERR dem Mose geboten hatte.", footnotes: ["℘ Kap. 30,7"] },
      { number: 28, text: "Und er hängte den Vorhang des Eingangs zur Wohnung auf," },
      { number: 29, text: "und den Brandopferaltar stellte er an den Eingang der Wohnung des Zeltes der Begegnung*, und er opferte darauf das Brandopfer und das Speisopfer — wie der HERR dem Mose geboten hatte.", footnotes: ["℘ 3Mo 1,1; Hes 40,47"] },
      { number: 30, text: "Dann stellte er das Becken zwischen das Zelt der Begegnung und den Altar und tat Wasser zum Waschen hinein," },
      { number: 31, text: "damit sich Mose und Aaron und dessen Söhne darin* ihre Hände und ihre Füße wuschen.", footnotes: ["w. daraus"] },
      { number: 32, text: "Sooft sie in das Zelt der Begegnung hineingingen, und sooft sie an den Altar herantraten, wuschen sie sich* — wie der HERR dem Mose geboten hatte.", footnotes: ["℘ Kap. 29,4"] },
      { number: 33, text: "Und er richtete den Vorhof auf, rings um die Wohnung und um den Altar, und hängte den Vorhang des Tores zum Vorhof auf. So vollendete Mose das Werk*.", footnotes: ["℘ 1Kö 6,14"] },
      { number: 34, text: "Da bedeckte die Wolke* das Zelt der Begegnung, und die Herrlichkeit des HERRN erfüllte die Wohnung*.", footnotes: ["℘ Mk 9,7", "℘ Kap. 16,10; 29,43; 4Mo 9,15; 1Kö 8,10.11; Jes 4,5; 57,15; Hes 43,4.5; Röm 9,4; Offb 15,8"] },
      { number: 35, text: "Und Mose konnte nicht in das Zelt der Begegnung hineingehen; denn die Wolke hatte sich darauf niedergelassen, und die Herrlichkeit des HERRN erfüllte die Wohnung*.", footnotes: ["℘ Kap. 16,10; 29,43; 4Mo 9,15; 1Kö 8,10.11; Jes 4,5; 57,15; Hes 43,4.5; Röm 9,4; Offb 15,8"] },
      { number: 36, text: "Sooft sich die Wolke von der Wohnung erhob, brachen die Söhne Israel auf, auf all ihren Wanderungen." },
      { number: 37, text: "Wenn sich aber die Wolke nicht erhob, dann brachen sie nicht auf bis zu dem Tag, an dem sie sich erhob." },
      { number: 38, text: "Denn die Wolke des HERRN war bei Tag auf der Wohnung*, und bei Nacht war ein Feuer in der Wolke* vor den Augen des ganzen Hauses Israel, solange sie auf der Wanderung waren*.", footnotes: ["℘ 4Mo 10,34; 2Sam 7,6", "w. in ihr", "o. auf all ihren Wanderungen; w. bei all ihren Aufbrüchen\n℘ Kap. 13,21.22"] },
    ]},
  ]
};
